        }

        return `${this.fieldName} ge ${this.range[0]} and ${this.fieldName} le ${this.range[1]}`;
    }

    @observable
    private _values: number[] = [];
    @observable
    private _minValue: number;
    @observable
    private _maxValue: number;

    private parseFilterExpression(filterClause: string): number[] {

        if (!filterClause) {
