}

def:pub Yamde(
    value: str,
    handler: Callable[[str], None],
    toolbar: list[str] | None = None,
    required: bool = False,
) -> JsxElement {
    has isPreviewMode: bool = False;
    has textEditor: Ref[HTMLTextAreaElement] = Ref();
    classes: dict[str, str] = useStyles();
    htmlPreview: str = converter.makeHtml(value);

    def handleChange(e: ChangeEvent) {
        handler(e.target.value);
    }

    def handleClick(action: dict[str, object]) {
        name: str = action["name"] as str;
        schema: dict[str, str] = action["schema"] as dict[str, str];
        openingTag: str = schema["openingTag"];
        closingTag: str = schema["closingTag"];
        if textEditor.current {
            editorValue: str = textEditor.current.value as str;
            selectionStart: int = textEditor.current.selectionStart as int;
            selectionEnd: int = textEditor.current.selectionEnd as int;
            selectedText: str = editorValue[selectionStart:selectionEnd];
            listMatch: list[str] = re.findall(r"[^\n]+", selectedText);
            fullReplacement: str = "";
            if listMatch and len(listMatch) > 0 and (name == "olist" or name == "ulist") {
                fullReplacement = (
                    editorValue[:selectionStart]
                    + formatText(listMatch, name, openingTag, closingTag)
                    + editorValue[selectionEnd:]
                );
            } else {
                replacement: str = f"{openingTag}{selectedText}{closingTag}";
                fullReplacement = (
                    editorValue[:selectionStart]
                    + replacement
                    + editorValue[selectionEnd:]
                );
            }
            handler(fullReplacement);
        }
    }

    <div className={classes["yamde"]}>
        <div className={classes["toolbar"]}>
            <div className={classes["buttons"]}>
                {[
                    <div
                        className={classes["button"]}
                        onClick={lambda { handleClick(action); }}
                    >
                        {action["icon"]}
                    </div>
                    for action in [a for a in toolbarActions if toolbar and a["name"] in toolbar]
                ]}
            </div>
            <div className={classes["viewSwitch"]}>
                <div
                    className={classes["viewButton"] + (" " + classes["activeView"] if not isPreviewMode else "")}
                    onClick={lambda { isPreviewMode = False; }}
                >
                    Editor
                </div>
                <div
                    className={classes["viewButton"] + (" " + classes["activeView"] if isPreviewMode else "")}
                    onClick={lambda { isPreviewMode = True; }}
                >
                    Preview
                </div>
            </div>
        </div>
        <div className={classes["contentArea"]}>
            {if not isPreviewMode {
                <textarea required={required} ref={textEditor} value={value} onChange={handleChange} />
            } else {
                <div className={classes["preview"]} dangerouslySetInnerHTML={{"__html": htmlPreview}} />
            }}
        </div>
    </div>
}

