/**
 * @fileoverview A simple organizer for ordering hooks.
 * @author Romullo @hiukky
 */
'use strict'

import { Context, Program, Node } from './types'

export const DEFAULT_GROUPS: string[] = [
  'useReducer',
  'useContext',
  'useState',
  'useRef',
  'useDispatch',
  'useCallback',
  'useEffect',
]

module.exports = {
  meta: {
    docs: {
      description: 'A simple organizer for ordering hooks.',
      category: 'Non-matching declaration order.',
      url: 'https://github.com/hiukky/eslint-plugin-hooks/blob/main/docs/rules/sort.md',
      recommended: false,
    },
    fixable: undefined,
    schema: [
      {
        type: 'object',
        properties: {
          groups: {
            type: 'array',
          },
        },
      },
    ],
  },

  create: (ctx: Context) => {
    const options = ctx.options[0]
    const groups: string[] = options?.groups || DEFAULT_GROUPS

    return {
      Program({ body }: Program) {
        body
          .filter(({ type }) =>
            [
              'FunctionDeclaration',
              'VariableDeclaration',
              'ExportNamedDeclaration',
              'ExportDefaultDeclaration',
            ].includes(type),
          )
          .map(node => {
            let declarations: Node = node

            const isExportableDeclaration = (): boolean =>
              ['ExportNamedDeclaration', 'ExportDefaultDeclaration'].includes(
                node.type,
              )

            if (isExportableDeclaration()) {
              declarations =
                node['declaration']?.['declarations']?.[0]['init'] ||
                node['declaration']
            } else {
              declarations = node['declarations']?.[0]['init'] || node
            }

            return declarations?.['body']?.['body']
          })
          .filter(Boolean)
          .forEach((declarations: Node[]) => {
            let nodes: Node[] = []

            declarations.forEach?.(node => {
              if (node['type'] === 'ExpressionStatement') {
                nodes.push(node['expression'])
              }

              if (node['type'] === 'VariableDeclaration') {
                nodes.push(...node['declarations'])
              }
            })

            const hooks = nodes
              ?.map(
                ({ type, callee, init }) =>
                  (type === 'CallExpression'
                    ? [type, callee]
                    : type === 'VariableDeclarator'
                    ? [type, init]
                    : []) as [Node['type'], Node],
              )
              .filter(node => node.length === 2)
              .map(([type, declaration]) => {
                switch (type) {
                  case 'MemberExpression':
                    return declaration.property

                  case 'CallExpression':
                    return declaration.type === 'MemberExpression'
                      ? declaration.property
                      : declaration.callee || declaration

                  case 'VariableDeclarator':
                  default:
                    return declaration?.callee?.property || declaration?.callee
                }
              })
              .filter(Boolean)
              .filter(
                hook =>
                  hook.name?.slice(0, 3) === 'use' &&
                  groups.includes(hook.name),
              )

            const correctOrdering: Node[] = [...hooks].sort(
              (a, b) => groups.indexOf(a.name) - groups.indexOf(b.name),
            )

            hooks.forEach((hook, idx) => {
              const noMatching = (): boolean =>
                correctOrdering.length > 1 &&
                correctOrdering[idx].name !== hook.name

              if (noMatching()) {
                ctx.report(
                  hook,
                  `Non-matching declaration order. ${hook.name} comes ${
                    !idx ? 'after' : 'before'
                  } ${correctOrdering[idx].name}.`,
                )
              }
            })
          })
      },
    }
  },
}

import { messageQuality } from "../../convex/coachScore";
import type { Conversation, Message } from "./types";

export type CoachKind = "fix" | "tip" | "tone" | "gem";

export interface CoachTip {
	kind: CoachKind;
	/** Character span in the message text the tip is anchored to. */
	start: number;
	end: number;
	title: string;
	detail: string;
	/** The flagged text itself. */
	quote: string;
	/** For fixes: what the span should read instead. */
	correction?: string;
}

/** Absent = not analyzed yet, [] = analyzed and clean. */
export function tipsForMessage(message: Pick<Message, "tips">): CoachTip[] {
	return message.tips ?? [];
}

export function rewriteForMessage(
	message: Pick<Message, "author" | "rewrite">,
): string | null {
	if (message.author !== "user") return null;
	return message.rewrite ?? null;
}

/**
 * Live-coach tips, mapped from the trimmed draft the coach reviewed onto the
 * raw text still sitting in the composer. Returns nothing once the draft has
 * moved on: a mark on the wrong characters is worse than no mark at all.
 */
export function draftMarks(
	draft: string,
	review: { tips: CoachTip[]; reviewedText: string },
): CoachTip[] {
	if (review.tips.length === 0 || draft.trim() !== review.reviewedText) {
		return [];
	}
	// The coach only ever sees the trimmed draft, so every span is short by
	// whatever whitespace the learner left in front of it.
	const leadingWhitespace = draft.length - draft.trimStart().length;
	if (leadingWhitespace === 0) return review.tips;
	return review.tips.map((tip) => ({
		...tip,
		start: tip.start + leadingWhitespace,
		end: tip.end + leadingWhitespace,
	}));
}

export interface SessionInsights {
	/** Messages the learner sent. */
	sent: number;
	/** Sent messages that needed no fixes and no tone adjustments. */
	clean: number;
	/** Average message quality, 0-100; null when nothing was sent. */
	score: number | null;
	/** 0-100 share of sent messages whose tone matched the room. */
	toneMatch: number | null;
	/** Everything flagged on the learner's messages, worth practicing. */
	practice: CoachTip[];
	/** Phrases the partner used that are worth keeping. */
	gems: CoachTip[];
}

export function summarizeSession(conversation: Conversation): SessionInsights {
	let sent = 0;
	let clean = 0;
	let toneClean = 0;
	let qualitySum = 0;
	const practice: CoachTip[] = [];
	const gems: CoachTip[] = [];
	const seenPractice = new Set<string>();
	const seenGems = new Set<string>();

	for (const message of conversation.messages) {
		const tips = tipsForMessage(message);
		if (message.author === "user") {
			sent++;
			if (tips.length === 0) clean++;
			if (!tips.some((t) => t.kind === "tone")) toneClean++;
			qualitySum += messageQuality(tips);
			for (const tip of tips) {
				const key = `${tip.title}:${tip.quote.toLowerCase()}`;
				if (seenPractice.has(key)) continue;
				seenPractice.add(key);
				practice.push(tip);
			}
		} else {
			for (const tip of tips) {
				const key = tip.quote.toLowerCase();
				if (seenGems.has(key)) continue;
				seenGems.add(key);
				gems.push(tip);
			}
		}
	}

	return {
		sent,
		clean,
		score: sent === 0 ? null : Math.round(qualitySum / sent),
		toneMatch: sent === 0 ? null : Math.round((toneClean / sent) * 100),
		practice,
		gems,
	};
}

