        storageValue = getStorageItem(key);
        if storageValue {
            return storageValue;
        }
        return initialState;
    });
    state = statePair[0];
    setState = statePair[1];
    useEffect(lambda () -> None { setStorageItem(key, state); }, [key, state]);
    return [state, setState];
}

