import from ..api.apiService { ApiService, TApiServiceOptions }
import from ...utils { handleAsync }
import from .auth.types {
    TAuthLoginRequestPayload,
    TAuthLoginResponsePayload,
    TAuthRefreshAccessTokenRequestPayload,
    TAuthRefreshAccessTokenResponsePayload,
}

glob apiService = ApiService();

obj AuthService {
    has rootEndpoint: str = "auth";
    has loginEndpoint: str = "auth/login";
    has logoutEndpoint: str = "auth/logout";
    has signupEndpoint: str = "auth/signup";
    has forgotPasswordEndpoint: str = "auth/forgotPassword";
    has refreshAccessTokenEndpoint: str = "auth/refreshAccessToken";

    def login(payload: TAuthLoginRequestPayload, options: TApiServiceOptions | None = None) -> object {
        return handleAsync(lambda -> object {
            return apiService.post(self.loginEndpoint, payload, options);
        });
    }

    def logout(options: TApiServiceOptions | None = None) -> object {
        return apiService.post(self.logoutEndpoint, None, options);
    }

    def refreshAccessToken(payload: TAuthRefreshAccessTokenRequestPayload, options: TApiServiceOptions | None = None) -> object {
        return handleAsync(lambda -> object {
