              className="animate-pulse rounded-lg bg-white p-4 shadow"
            >
              <div className="mb-2 h-6 w-3/4 rounded bg-gray-300"></div>
              <div className="h-4 w-1/2 rounded bg-gray-300"></div>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
};

