    width_class = "w-full justify-center" if widthFull else "";
    class_name = f"text-sm rounded-3xl flex items-center py-2 px-2 h-12 {variant_class} {width_class}";

    def handle_click(e: MouseEvent) {
        onClick(e);
    }

    return <button onClick={handle_click} className={class_name}>{[map_button_child(child) for child in Children.toArray(children)]}</button>;
}

