def:pub Dropdown() -> JsxElement {
    has isOpen: bool = False;
    has paymentTerm: int = 30;
    options: list[int] = [1, 7, 14, 30];

    def handle_select_payment_term(option: int) {
        paymentTerm = option;
        isOpen = False;
    }

    def handle_toggle_dropdown(e: MouseEvent) {
        isOpen = not isOpen;
    }

    def make_option_handler(option: int) -> Callable[[MouseEvent], None] {
