import { useEffect, useRef, useState } from 'react';

type UseControllerHookParams = {
  isVisible: boolean;
};

type UseControllerHook = (params: UseControllerHookParams) => { show: boolean };

const DELAY = 2000;
let TIMER: NodeJS.Timer;

export const useController: UseControllerHook = ({ isVisible }) => {
  const showRef = useRef(false);
  const [show, setShow] = useState(showRef.current);

  useEffect(() => {
    clearTimeout(TIMER);
    if (isVisible) {
      showRef.current = true;
      setShow(true);
    } else {
      TIMER = setTimeout(() => {
        setShow(false);
      }, DELAY);
    }

    return () => clearTimeout(TIMER);
  }, [isVisible]);

  return {
    show,
  };
};

jac:
glob DELAY = 2000;
glob timerId: float | None = None;

def:pub useController(params: dict[str, object]) -> dict[str, object] {
    isVisible = params["isVisible"] as bool;
    has show: bool = False;

    import from "react" { useEffect, useRef }
    showRef = useRef(False);

    useEffect(lambda {
        if timerId is not None {
            clearTimeout(timerId);
        }
        if isVisible {
            showRef.current = True;
            show = True;
        } else {
            timerId = setTimeout(lambda { show = False; }, DELAY) as float;
        }
        return lambda {
            if timerId is not None {
                clearTimeout(timerId);
            }
        };
    }, [isVisible]);

    return {"show": show};
}

