      <div
        className={`${invoiceBackgrounds[status]} ${
          status === "draft" ? "dark:bg-brand-violet-highlight" : ""
        } dark:bg-opacity-5 max-w-[104px] mx-auto w-full relative py-3 rounded-md lg:order-5 md:order-5 order-3 row-span-2`}
      >
        <p
          className={`${invoiceTexts[status]} ${
            status === "draft" ? "dark:text-brand-white" : ""
          } relative font-bold`}
        >
          <span
            className={`absolute top-1 before:absolute ${invoiceDots[status]} ${
              status === "draft" ? "dark:before:bg-brand-white" : ""
            } before:rounded-full before:p-[3px] before:right-1`}
          ></span>
          {normalizedStatus}
        </p>
      </div>
      <span className="ml-2 w-fit right-4 absolute lg:block lg:order-6 md:block md:order-6 hidden">
