    useEffect(lambda {
        timer = setTimeout(lambda { set_term(value); }, debounce);
        return lambda { clearTimeout(timer); };
    }, [value, debounce]);
    return useSWR(lambda { term ? ["search", term, page] : None; }, search);
}

