    has excludeAmbiguous: bool = False;
    has excludeCustom: str = "";
    has custom: bool = False;
    has customSet: str = "";
    has separator: str | None = None;
    has separatorInterval: int | None = None;
}

def isCharacterOptionEnabled(options: PasswordProps, key: str) -> bool {
    if key == "uppercase" { return options.uppercase; }
    if key == "lowercase" { return options.lowercase; }
    if key == "numeric" { return options.numeric; }
    if key == "special" { return options.special; }
    if key == "custom" { return options.custom; }
    return False;
}

def addSeparator(password: str, separator: str, interval: int) -> str {
    chunks: list[str] = [];
    i = 0;
    while i < len(password) {
        chunks.append(password[i:i + interval]);
        i += interval;
    }
    return separator.join(chunks);
}

