    if options.custom and len(options.customSet) > 0 {
        availableCharacters += options.customSet;
    }
    if options.excludeSimilar {
        availableCharacters = re.sub(f"[{similar}]", "", availableCharacters);
    }
    if options.special and not options.excludeAmbiguous {
        availableCharacters += ambiguous;
    }
    if len(options.excludeCustom) > 0 {
        availableCharacters = re.sub(f"[{options.excludeCustom}]", "", availableCharacters);
    }
    return availableCharacters;
}

def getRequiredCharacters(options: PasswordProps) -> str {
    result: str = "";
    characters: dict[str, str] = {**Characters};
    if not options.excludeAmbiguous {
        characters["special"] += ambiguous;
    }
    if options.custom and len(options.customSet) > 0 {
        characters["custom"] = options.customSet;
    }
    for key in characters.keys() {
        if options.excludeSimilar {
            characters[key] = re.sub(f"[{similar}]", "", characters[key]);
        }
        if len(options.excludeCustom) > 0 {
            characters[key] = re.sub(f"[{options.excludeCustom}]", "", characters[key]);
        }
    }
    for (key, value) in characters.items() {
