export default function* textNodes(nodes: TreeWalker | Node[]): Generator<Node> {
  if (nodes instanceof TreeWalker) {
    let node;
    while ((node = nodes.nextNode())) {
      yield node;
    }
  } else {
    for (const node of nodes) {
      yield node;
    }
  }
}

jac:
obj WalkerLike {
    def nextNode() -> object | None;
}

def textNodes(nodes: WalkerLike | list[object]) -> Iterator[object] {
    if not isinstance(nodes, list) {
        current = (nodes as WalkerLike).nextNode();
        while current is not None {
            yield current;
            current = (nodes as WalkerLike).nextNode();
        }
    } else {
        for item in nodes {
            yield item;
        }
    }
}

