obj:pub NotificationData {
    has id: str;
    has type: NotificationType;
    has text: str;
    has theme: NotificationTheme | None = None;
    has delay: int | None = None;
    has autoClose: bool | None = None;
    has isPaused: bool | None = None;
    has transition: NotificationTransition | None = None;
    has position: NotificationPosition | None = None;
}

obj:pub NotificationStore {
    has notifications: list[NotificationData] = [];
    has set_state: Callable[[list[NotificationData]], None] | None = None;

    static def getInstance() -> NotificationStore {
        if _notification_store_instance is None {
            _notification_store_instance = NotificationStore();
        }
        return _notification_store_instance;
    }

    def subscribe(set_state: Callable[[list[NotificationData]], None]) {
        self.set_state = set_state;
    }

    def add(value: NotificationData) {
        self.notifications = self.notifications + [value];
        if self.set_state is not None {
            self.set_state(self.notifications);
        }
    }

    def remove(id: str) {
        self.notifications = [n for n in self.notifications if n.id != id];
        if self.set_state is not None {
            self.set_state(self.notifications);
        }
    }

    def get() -> list[NotificationData] {
        return self.notifications;
    }
}

