def:pub ProgressBar(id: any, onRemove: any, delay: any, theme: any, type: any, isPaused: any, autoClose: any) -> JsxElement {
    parsedTheme: any = f"{type}-{theme}";
    return <Container style={{"animationDuration": f"{delay}ms"}} theme={parsedTheme} animationState={("paused" if isPaused else "running")} onAnimationEnd={lambda () -> any { return (autoClose and onRemove(id)); }} aria-label="Progress bar" />;
}

