  );
  return (
    <Box className={className} sx={sx}>
      {treeItems}
    </Box>
  );
}

function mapStateToProps(state) {
  return {
    nodes: nodesSelector(state),
  };
}

export default connect(mapStateToProps)(BookmarkTreeView);

