import { useState } from 'react'

/**
 * Custom hook for confirm dialog
 * @param initialState string | null
 * @returns A stateful value, and a function to update it.
 * @example const [open, setOpen] = useDialogState<"approve" | "reject">()
 */
export default function useDialogState<T extends string | boolean>(
  initialState: T | null = null
) {
  const [open, _setOpen] = useState<T | null>(initialState)

  const setOpen = (str: T | null) =>
    _setOpen((prev) => (prev === str ? null : str))

  return [open, setOpen] as const
}

jac:
type DialogState = str | bool | None;
type DialogSetter = Callable[[DialogState], None];

def:pub useDialogState(initialState: DialogState = None) -> list[DialogState | DialogSetter] {
    state = useState(initialState);
    open = state[0];
    _setOpen = state[1];
    setOpen = lambda (value: DialogState) -> None {
        _setOpen(lambda (prev: DialogState) -> DialogState {
            return None if prev == value else value;
        });
    };
    return [open, setOpen];
}

