import from "react" { useEffect, useState }
import from "next-themes" { useTheme }

obj TechUrlOptions {
    has name: str;
    has dark: bool = False;
}

obj ThemeContextValue {
    has theme: str | None = None;
    has setTheme: Callable[[str], None] | None = None;
    has resolvedTheme: str | None = None;
    has forcedTheme: str | None = None;
    has systemTheme: str | None = None;
}

def:pub getTechUrl(opts: TechUrlOptions, theme: str) -> str {
    icon = f"{opts.name}-dark" if (opts.dark and theme == "dark") else opts.name;
    return f"/icons/{icon.lower()}.svg";
}

def:pub getColor(color: list[str] | str, theme: str) -> str {
    if not isinstance(color, list) {
        return color;
    }
    return color[1] if (theme == "dark") else color[0];
}

def:pub useReactiveTheme() -> ThemeContextValue {
    state = useState(None);
    name = state[0] as str | None;
    set_name = state[1] as Callable[[str | None], None];
    ctx = useTheme();
    theme_src = ctx.theme as str | None;

    useEffect(lambda {
        if theme_src {
            set_name(theme_src);
        }
    }, [theme_src]);

    return ThemeContextValue(
        theme=name,
        setTheme=ctx.setTheme as Callable[[str], None] | None,
        resolvedTheme=ctx.resolvedTheme as str | None,
        forcedTheme=ctx.forcedTheme as str | None,
        systemTheme=ctx.systemTheme as str | None
    );
}

