import from "@radix-ui/react-icons" { ArrowDownIcon, ArrowUpIcon, CaretSortIcon, EyeNoneIcon }
import from "@tanstack/react-table" { Column }
import from "@/lib/utils" { cn }
import from "@/components/ui/button" { Button }
import from "@/components/ui/dropdown-menu" {
    DropdownMenu,
    DropdownMenuContent,
    DropdownMenuItem,
    DropdownMenuSeparator,
    DropdownMenuTrigger,
}

def:pub DataTableColumnHeader(column: Column, title: str, className: str = "") -> JsxElement {
    if not column.getCanSort() {
        return <div className={cn(className)}>{title}</div>;
    }

    <div className={cn("flex items-center space-x-2", className)}>
        <DropdownMenu>
            <DropdownMenuTrigger asChild>
                <Button variant="ghost" size="sm" className="-ml-3 h-8 data-[state=open]:bg-accent">
                    <span>{title}</span>
                    {if column.getIsSorted() == "desc" {
                        <ArrowDownIcon className="ml-2 h-4 w-4" />
                    } elif column.getIsSorted() == "asc" {
                        <ArrowUpIcon className="ml-2 h-4 w-4" />
                    } else {
                        <CaretSortIcon className="ml-2 h-4 w-4" />
                    }}
                </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent align="start">
                <DropdownMenuItem onClick={lambda () { column.toggleSorting(False); }}>
                    <ArrowUpIcon className="mr-2 h-3.5 w-3.5 text-muted-foreground/70" />
                    Asc
                </DropdownMenuItem>
                <DropdownMenuItem onClick={lambda () { column.toggleSorting(True); }}>
                    <ArrowDownIcon className="mr-2 h-3.5 w-3.5 text-muted-foreground/70" />
                    Desc
                </DropdownMenuItem>
                {if column.getCanHide() {
                    <>
                        <DropdownMenuSeparator />
                        <DropdownMenuItem onClick={lambda () { column.toggleVisibility(False); }}>
                            <EyeNoneIcon className="mr-2 h-3.5 w-3.5 text-muted-foreground/70" />
                            Hide
                        </DropdownMenuItem>
                    </>
                }}
            </DropdownMenuContent>
        </DropdownMenu>
    </div>
}

