def:pub sanitize(string: str) -> str {
    escapes: dict[str, str] = {
        "&": "&amp;",
        "<": "&lt;",
        ">": "&gt;",
        "\"": "&quot;",
        "'": "&#x27;",
        "/": "&#x2F;",
        ".": "_",
    };
    result = "";
    for ch in string {
        if ch in escapes {
            result += escapes[ch];
        } else {
            result += ch;
        }
    }
    return result;
}

