) {
  await user.click(screen.getByRole("combobox", { name: triggerName }));
  const option = await screen.findByRole("option", { name: optionName });
  await user.click(option);
}

function buildProjects(): ProjectCardModel[] {
  return [
    {
      id: "alpha",
