import from "lucide-react" { Check, Moon, Sun }
import from "@/components/ui/dropdown-menu" { DropdownMenu, DropdownMenuContent, DropdownMenuRadioGroup, DropdownMenuRadioItem, DropdownMenuRadioItemIndicator, DropdownMenuTrigger }

glob themeOptions: list[dict[str, str]] = [{"value": "light", "label": "Light"}, {"value": "dark", "label": "Dark"}, {"value": "system", "label": "System"}];

def isThemePreference(value: str | None) -> bool {
    return (value == "light") or (value == "dark") or (value == "system");
}

def getStoredThemePreference() -> str {
    try {
        stored = localStorage.getItem("theme") as str | None;
        if isThemePreference(stored) {
            return stored as str;
        }
    } except Exception {
    }
    return "system";
}

def:pub ThemeToggle() -> JsxElement {
    has preference: str = "system";

    can with entry {
        preference = getStoredThemePreference();
    }

    def handle_open_change(open: bool) {
        if open {
            preference = getStoredThemePreference();
        }
    }

    <DropdownMenu modal={False} onOpenChange={handle_open_change}>
        <DropdownMenuTrigger
            render={
                <button
                    type="button"
                    aria-label="Toggle theme"
                    className="relative inline-flex size-11 items-center justify-center rounded-md border border-border/60 bg-background text-foreground/80 transition-colors hover:bg-muted/60 focus-visible:outline-hidden focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background"
                >
                    <Sun className="absolute size-5 rotate-0 scale-100 transition-all dark:-rotate-90 dark:scale-0" aria-hidden="true" />
                    <Moon className="absolute size-5 rotate-90 scale-0 transition-all dark:rotate-0 dark:scale-100" aria-hidden="true" />
                </button>
            }
        />
        <DropdownMenuContent align="end" sideOffset={8}>
            <DropdownMenuRadioGroup value={preference}>
                {for option in themeOptions {
                    <DropdownMenuRadioItem key={option["value"]} value={option["value"]} data-theme-set={option["value"]}>
