   * @param index
   */
  const changeViewIndicator = (index: number) => {
    let viewIndicator: number = 0,viewMode: ViewMode = ViewMode.GanttViewer
    switch (index) {
      case 0: // gantt图
        viewIndicator = 0
        viewMode = ViewMode.GanttViewer
        changeScaleIndicator(0)
        break
      case 1: // 时标网络图
        viewIndicator = 1
        viewMode = ViewMode.TimeViewer
        changeScaleIndicator(0)
        break
      case 2: // 箭线图（双代号）
