        viewMode = ViewMode.AdmViewer
        changeScaleIndicator(2)
        break
      case 3: // 前导图（单代号、PERT图）
        viewIndicator = 3
        viewMode = ViewMode.PdmViewer
        changeScaleIndicator(2)
        break
    }
    setViewIndicator(viewIndicator)
    setViewMode(viewMode)
  }

