  const { switcher } = props

  const [typeKanban, setTypeKanban] = React.useState<boolean>(true)
  const [typeDefault, setTypeDefault] = React.useState<boolean>(false)

  const handleTypeKanban = () => {
    switcher(true)
    setTypeKanban(true)
