def route_render(auth: bool, children: JsxElement | None, renderProps: dict[str, object]) -> JsxElement {
    if auth {
        return children if children else <></>;
    }
    return <Redirect to={{"pathname": "/login", "state": {"from": renderProps["location"]}}} />;
}

def:pub PrivateRoute(auth: bool, children: JsxElement | None = None, rest: dict[str, object] | None = None) -> JsxElement {
    routeRest = rest if rest is not None else {};
    <Route {**routeRest} render={lambda (renderProps: dict[str, object]) { route_render(auth, children, renderProps); }} />
}

def mapStateToProps(state: AppState) -> dict[str, bool] {
    return {"auth": state.auth.isAuth};
}

glob:pub default = connect(mapStateToProps)(PrivateRoute);

