glob:pub SHARED_NAMESPACES: list[str] = ["Metadata", "navigation", "tools", "feedback", "common", "languages", "CopyToClipboard", "NotFound", "AppError"];

def:pub pickSharedMessages(all: dict[str, object]) -> dict[str, object] {
    out: dict[str, object] = {};
    for ns in SHARED_NAMESPACES {
        value = all.get(ns);
        if value is None {
            continue;
        }
        out[ns] = value;
    }
    return out;
}

