  return (
    <ListItem
      onClick={url ? () => redirectTo(url) : undefined}
      className={classNames(className, {
        [classes.button]: !!url,
        [classes.isDisabled]: isDisabled,
      })}
    >
      {icon && <ListItemIcon>{icon}</ListItemIcon>}

      <ListItemText primary={title} />
    </ListItem>
  );
};

export default MenuItem;

