export function isCompletelyVisible(element: HTMLElement): boolean {
	if (!element.parentElement) {
		throw new Error("not a carousel slide");
	}

	const elementBoundingRect = element.getBoundingClientRect();
	const sliderBoundingRect = element.parentElement.getBoundingClientRect();
	const sliderWidth = sliderBoundingRect.width;

	const positionLeft = elementBoundingRect.left - sliderBoundingRect.left;
	const positionRight = positionLeft + elementBoundingRect.width;

	return positionLeft >= 0 && positionRight <= sliderWidth;
}

jac:
def:pub isCompletelyVisible(element: HTMLElement) -> bool {
    if element.parentElement is None {
        raise ValueError("not a carousel slide");
    }
    slider = element.parentElement;
    elementBoundingRect = element.getBoundingClientRect();
    sliderBoundingRect = slider.getBoundingClientRect();
    sliderWidth = sliderBoundingRect.width;
    positionLeft = elementBoundingRect.left - sliderBoundingRect.left;
    positionRight = positionLeft + elementBoundingRect.width;
    return (positionLeft >= 0) and (positionRight <= sliderWidth);
}

