import from ..utils { forEach as utilForEach }

obj InterceptorManager[V] {
    has handlers: list[dict[str, object] | None] = [];

    def use(
        onFulfilled: Callable[[V], V] | None = None,
        onRejected: Callable[[Exception], object] | None = None,
        options: dict[str, object] | None = None
    ) -> int {
        synchronous = False;
        runWhen: object | None = None;
        if options {
            opt_sync = options.get("synchronous");
            if opt_sync {
                synchronous = opt_sync as bool;
            }
            runWhen = options.get("runWhen");
        }
        self.handlers.append({
            "fulfilled": onFulfilled,
            "rejected": onRejected,
            "synchronous": synchronous,
            "runWhen": runWhen
        });
        return len(self.handlers) - 1;
    }

    def eject(id: int) {
        if self.handlers[id] {
            self.handlers[id] = None;
        }
    }

    def forEach(fn: Callable[[dict[str, object]], None]) {
        utilForEach(self.handlers, lambda (h: dict[str, object] | None) {
            if h is not None {
                fn(h);
            }
        });
    }
}

glob:pub default = InterceptorManager;

