import { useEffect, useState } from 'react';
import { useMobilePlatform } from './use-mobile-platform';
import { useClick } from './use-click';
import { useClickOutside } from './use-click-outside';

/**
 * Use adaptive interaction flow.
 *
 * Desktop:
 * * [ mouse enter = hover ] --> [ click = use ] --> [ mouse leave = unhover ]
 *
 * Mobile:
 * * [ click = hover ] --> [ second click = use ] --> [ auto unhover ]
 * * [ click = hover ] --> [ outside click = unhover ]
 *
 * @param ref - Target ref
 * @param callback - Event callback
 * @param depends - Callback dependencies
 */
export function useInteraction(
  ref: React.RefObject<HTMLElement>,
  callback?: () => void,
  depends?: any[],
) {
  const isMobile = useMobilePlatform();

  const [isSelected, setSelected] = useState(false);

  useClickOutside(ref, () => {
    setSelected(false);
  }, []);

  useClick(ref, 'down', () => {
    if (isSelected) {
      callback?.();
      if (isMobile) {
        setSelected(false);
      }
    } else {
      setSelected(true);
    }
  }, [isSelected, isMobile, ...(depends ?? [])]);

  const onMouseEnter = () => {
    setSelected(true);
  };

  const onMouseLeave = () => {
    setSelected(false);
  };

  useEffect(() => {
    if (isMobile) {
      return;
    }

    const element = ref.current;

    if (!element) {
      return;
    }

    element.addEventListener('mouseenter', onMouseEnter);
    element.addEventListener('mouseleave', onMouseLeave);

    return () => {
      element.removeEventListener('mouseenter', onMouseEnter);
      element.removeEventListener('mouseleave', onMouseLeave);
    };
  }, [isMobile]);

  return isSelected;
}

