import isEqual from "lodash/isEqual";
import isObject from "./isObject";

export type State = Record<string, any> | undefined;
export type Action = {
  type: "UPDATE_FIELD";
  payload: any;
};

const getDataObject = (
  ids: string[],
  value: any,
  existingData: State,
): Record<string, any> => {
  if (ids[1]) {
    return {
      [ids[0]]: {
        ...existingData?.[ids[0]],
        ...getDataObject(ids.slice(1), value, existingData?.[ids[0]]),
      },
    };
  }

  return {
    [ids[0]]: {
      ...existingData?.[ids[0]],
      ...value,
    },
  };
};

export const enrichInitialData = (data: Record<string, any>) => {
  const enriched = {};

  Object.entries(data).forEach(([key, value]) => {
    if (isObject(value)) {
      enriched[key] = enrichInitialData(value);
    } else {
      enriched[key] = {
        value,
      };
    }
  });

  return enriched;
};

export const getFieldById = (
  ids: string[],
  data?: Record<string, any>,
): Record<string, any> => {
  if (ids[1]) {
    return getFieldById(ids.slice(1), data?.[ids[0]]);
  }

  return data?.[ids[0]];
};

const reducer = (onDataChanged?: (...args: any[]) => any) => (
  state: State,
  { type, payload }: Action,
) => {
  switch (type) {
    case "UPDATE_FIELD": {
      if (isEqual(state?.[payload.id], payload.data)) {
        return state;
      }

      const splittedId = payload.id.split(".");

      const data = {
        ...state,
        ...getDataObject(splittedId, payload.data, state),
      };

      onDataChanged && onDataChanged(data);

      return data;
    }

    default: {
      throw new Error("Action type not defined");
    }
  }
};

export default reducer;

