def:pub mergeParams(params: dict[str, object], defaultParams: dict[str, object]) -> dict[str, object] {
    o: dict[str, object] = {**defaultParams, **params};
    for (key, value) in defaultParams.items() {
        if value is None {
            o[key] = defaultParams[key];
        }
    }
    return o;
}

