"use client";

import {
  createContext,
  type PropsWithChildren,
  use,
  useActionState,
} from "react";
import type {
  ActionState,
  FailureState,
  FormAction,
  InitialState,
  InvalidState,
  SuccessState,
} from "./createFormAction";
import { createFormAction, initial } from "./createFormAction";

export type ActionProps<
  Data,
  Error,
  ValidationError,
  Arguments extends unknown[] = [],
> = PropsWithChildren<
  Arguments extends [unknown, ...unknown[]]
    ? {
        action: FormAction<Data, Error, ValidationError, FormData, Arguments>;
        args: Arguments;
        initialData: Data;
        permalink?: string;
        validate?: (payload: FormData) => null | ValidationError;
      }
    : {
        action: FormAction<Data, Error, ValidationError, FormData, Arguments>;
        initialData: Data;
        args?: undefined;
        permalink?: string;
        validate?: (payload: FormData) => null | ValidationError;
      }
>;

type ActionStatusFlags<
  T extends ActionState<unknown, unknown, unknown>["type"] | unknown = unknown,
> = {
  isInitial: T extends "initial" ? true : false;
  isInvalid: T extends "invalid" ? true : false;
  isFailure: T extends "failure" ? true : false;
  isSuccess: T extends "success" ? true : false;
};

export type ActionContextState<
  T extends ActionState<unknown, unknown, unknown>,
> = T &
  ActionStatusFlags<T["type"]> & {
    /**
     * The dispatch function returned from React.useActionState()
     */
    action: (payload: FormData) => void;
    isPending: boolean;
  };

const neverMetaState: ActionStatusFlags = {
  isInitial: false,
  isInvalid: false,
  isFailure: false,
  isSuccess: false,
};

/**
 * NOTE: ActionContextState<ActionState<...>> would not allow discriminate the union inside of the ActionState.
 */
type SpreadActionContext<
  Data = unknown,
  Error = unknown,
  ValidationError = unknown,
> =
  | ActionContextState<InitialState<Data>>
  | ActionContextState<InvalidState<ValidationError>>
  | ActionContextState<FailureState<Error>>
  | ActionContextState<SuccessState<Data>>;

/**
 * A context exposing the form action state.
 */
const ActionContext = createContext<SpreadActionContext | null>(null);

/**
 * A hook to consume the form action state from the context.
 */
export function useActionContext<
  Data,
  Error,
  ValidationError,
  Args extends unknown[] = [],
>(_action?: FormAction<Data, Error, ValidationError, FormData, Args>) {
  const ctx = use(ActionContext);

  if (!ctx) {
    throw new Error(
      "ActionContext must be initialized before use. Is your useActionContext hook wrapped with an <Action> Component?",
    );
  }

  // Generics shouldn't be used for explicit casts, I know
  return ctx as SpreadActionContext<Data, Error, ValidationError>;
}

export function Action<
  Data,
  Error,
  ValidationError,
  Args extends unknown[] = [],
>({
  children,
  action: formAction,
  initialData,
  args,
  permalink,
  validate,
}: ActionProps<Data, Error, ValidationError, Args>) {
  type NoArgsAction = FormAction<Data, Error, ValidationError, FormData, []>;

  const argAction = (
    args ? formAction.bind(null, ...args) : formAction
  ) as NoArgsAction;

  const [state, action, isPending] = useActionState(
    // biome-ignore lint/suspicious/noExplicitAny: fine
    async (state: any, payload: FormData) => {
      if (validate) {
        const clientValidateAction = createFormAction(
          ({ invalid, success }) => {
            return async (_, payload) => {
              const errors = validate(payload);

              if (errors) {
                return invalid(errors);
              }

              return success(true);
            };
          },
        );

        const clientValidationResult = await clientValidateAction(
          state,
          payload,
        );

        if (clientValidationResult.type === "invalid") {
          return clientValidationResult;
        }
      }

      return argAction(state, payload);
    },
    initial(initialData),
    permalink,
  );

  const metaState =
    state.type === "initial"
      ? {
          ...state,
          ...neverMetaState,
          action,
          isPending,
          isInitial: true as const,
        }
      : state.type === "invalid"
        ? {
            ...state,
            ...neverMetaState,
            action,
            isPending,
            isInvalid: true as const,
          }
        : state.type === "failure"
          ? {
              ...state,
              ...neverMetaState,
              action,
              isPending,
              isFailure: true as const,
            }
          : {
              ...state,
              ...neverMetaState,
              action,
              isPending,
              isSuccess: true as const,
            };

  return <ActionContext value={metaState}>{children}</ActionContext>;
}

"use client";

import type React from "react";
import type { $ZodErrorTree } from "zod/v4/core";

const SEPARATOR = "." as const;

export type Paths<
  Shape extends $ZodErrorTree<object>,
  Props = Required<NonNullable<Shape["properties"]>>,
> = {
  [k in keyof Props]: k extends string
    ? NonNullable<Props[k]> extends $ZodErrorTree<object>
      ? "properties" extends keyof NonNullable<Props[k]>
        ? `${k}${typeof SEPARATOR}${Paths<NonNullable<Props[k]>>}`
        : k // leaf node
      : k
    : never;
}[keyof Props];

export type InferZodErrorPaths<T> =
  T extends $ZodErrorTree<object> ? Paths<T> : never;

export type ZodFieldErrorProps<
  Errors extends $ZodErrorTree<any>,
  Name extends "" | InferZodErrorPaths<Errors>,
> = {
  errors: Errors;
  name: Name;
  children?: (props: ZodFieldErrorChildrenProps<Name>) => React.ReactNode;
};

export type ZodFieldErrorChildrenProps<Name> = {
  name: Name;
  error?: string;
  errors: readonly string[];
};

export const noError = Object.freeze({
  errors: Object.freeze([] as string[]),
});

export function ZodFieldError<
  Errors extends $ZodErrorTree<object>,
  Name extends "" | InferZodErrorPaths<Errors> = "",
>({
  errors,
  name,
  children = ({ error }) => <>{error}</>,
}: ZodFieldErrorProps<Errors, Name>) {
  // checking length avoids narroving name to never, which happens by truthines check e.g. !!name
  if (name.length === 0) {
    return children({
      name,
      error: errors.errors[0],
      errors: errors.errors,
    });
  }

  const path = name.split(SEPARATOR);

  let error = errors;
  for (const key of path) {
    if (!error.properties) {
      // @ts-expect-error non-existent property
      error = noError;
      break;
    }

    // @ts-expect-error accessing properties dynamically
    error = error.properties[key] ?? noError;
  }

  return children({
    name,
    error: error.errors[0],
    errors: error.errors,
  });
}

export type InitialState<T> = {
  type: "initial";
  data: T;
  error: null;
  validationError: null;
};

export type InvalidState<T> = {
  type: "invalid";
  data: null;
  error: null;
  validationError: T;
};

export type FailureState<T> = {
  type: "failure";
  data: null;
  error: T;
  validationError: null;
};

export type SuccessState<T> = {
  type: "success";
  data: T;
  error: null;
  validationError: null;
};

export type ActionState<Data, Error, ValidationError = Record<string, never>> =
  | InitialState<Data>
  | InvalidState<ValidationError>
  | FailureState<Error>
  | SuccessState<Data>;

export type FormAction<
  Data,
  Error = Data,
  ValidationError = Record<string, never>,
  Payload = FormData,
  Arguments extends unknown[] = [],
> = (
  ...args: [
    ...Arguments,
    state: ActionState<Data, Error, ValidationError>,
    payload: Payload,
  ]
) => Promise<ActionState<Data, Error, ValidationError>>;

export function initial<Data>(data: Data): InitialState<Data> {
  return { type: "initial", data, error: null, validationError: null };
}

export function createFormAction<
  Data,
  Error = Data,
  ValidationError = Record<string, never>,
  Payload = FormData,
  Arguments extends [...unknown[]] = [],
>(
  formAction: (
    params: {
      success: (data: Data) => SuccessState<Data>;
      failure: (error: Error) => FailureState<Error>;
      invalid: (
        validationError: ValidationError,
      ) => InvalidState<ValidationError>;
    },
    ...args: Arguments
  ) => FormAction<Data, Error, ValidationError, Payload>,
) {
  function success(data: Data): SuccessState<Data> {
    return { type: "success", data, error: null, validationError: null };
  }
  function failure(error: Error): FailureState<Error> {
    return { type: "failure", data: null, error, validationError: null };
  }
  function invalid(
    validationError: ValidationError,
  ): InvalidState<ValidationError> {
    return { type: "invalid", data: null, error: null, validationError };
  }

  return (
    ...args: [
      ...Arguments,
      state: ActionState<Data, Error, ValidationError>,
      payload: Payload,
    ]
  ) => {
    const payload = args.pop() as Payload;
    const state = args.pop() as ActionState<Data, Error, ValidationError>;
    const boundArgs = [...args] as Arguments;

    return formAction({ success, failure, invalid }, ...boundArgs)(
      state,
      payload,
    );
  };
}

