export function Pending({
  children,
}:
  | PropsWithChildren
  | { children?: (props: { isPending: boolean }) => React.ReactNode }) {
  const { isPending } = useActionContext();

  if (typeof children === "function") {
    return children({ isPending });
  }

  return isPending && children;
}

