import CryptoJS;
import from "../domain/entities/IUser" { default as IUser }
import from "../domain/repositories/UserRepository" { default as UserRepository }
import from "./AbstractUseCases" { default as AbstractUseCases }

obj UserUseCases(AbstractUseCases) {
    def buildRepository() -> UserRepository {
        return UserRepository();
    }

    def buildFrom(data: dict[str, object]) -> IUser {
        return {
            "email": data["email"] as str,
            "password": data["password"] as str,
            "google_client_id": data["google_client_id"] as str,
            "google_client_secret": data["google_client_secret"] as str,
            "google_redirect_url": data["google_redirect_url"] as str,
            "google_api_key": data["google_api_key"] as str,
            "google_tokens": data["google_tokens"] as dict[str, object]
        } as IUser;
    }

    def encryptField(fieldValue: str) -> str {
        salt = CryptoJS.lib.WordArray.random(16);
        derivedKey = CryptoJS.PBKDF2(fieldValue, salt, {
            "keySize": 64 / 32,
            "iterations": 1000
        }).toString(CryptoJS.enc.Hex);
        return str(salt.toString()) + derivedKey;
    }

    def decryptField(encryptedValue: str) -> str {
        return encryptedValue[32:];
    }

    async def create(unknownObj: dict[str, object]) -> IUser {
        hashedPassword = self.encryptField((unknownObj["password"] as str));
        newUser: dict[str, object] = {**unknownObj, "password": hashedPassword};
        return await super().create(newUser) as IUser;
    }

    async def loginUser(email: str, password: str) -> IUser {
        user = await super().findByQuery({"email": email}) as IUser | None;
        if not user {
            raise ValueError("User not found");
        }
        storedHashedPassword = user["password"] as str;
        salt = CryptoJS.enc.Hex.parse(storedHashedPassword[0:32]);
        storedDerivedKey = storedHashedPassword[32:];
        derivedKey = CryptoJS.PBKDF2(password, salt, {
            "keySize": 64 / 32,
            "iterations": 1000
        }).toString(CryptoJS.enc.Hex);
        if derivedKey != storedDerivedKey {
            raise ValueError("Incorrect password");
        }
        return user;
    }
}

