import from "zod" { ZodObject, ZodNullable, ZodArray, ZodOptional, ZodTypeAny, z }
import from "@/types/UtilityTypes" { UnwrapZodType }

obj ZodTypeDef {
    has innerType: object | None = None;
    has effect: object | None = None;
    has schema: object | None = None;
}

obj ZodTypeWithDef {
    has _def: ZodTypeDef | None = None;
}

def:pub unwrapZodType(zodType: object) -> object {
    unwrappedType: object = zodType;
    typed = unwrappedType as ZodTypeWithDef;
    while typed._def is not None {
        defn: ZodTypeDef = typed._def as ZodTypeDef;
        if defn.innerType is not None {
            unwrappedType = defn.innerType;
            typed = unwrappedType as ZodTypeWithDef;
        }
        elif defn.effect and defn.schema is not None {
            unwrappedType = defn.schema;
            typed = unwrappedType as ZodTypeWithDef;
        }
        else {
            break;
        }
    }
    return unwrappedType;
}

