    this.preferredColorScheme.init();
  }

  public toggleDarkMode() {
    this.isDarkMode.value = !this.isDarkMode.value;
    this.applyDarkModeUseCase.execute(this.isDarkMode.value ? 'dark' : 'light');
  }
}

