import from "../processes/startProcessHelpers" { startImagePreview, startVideoPlayer, startTextPreview }

def:pub getProcessStartingParams(file: any) -> any | None {
    if isImageFile(file) {
        return startImagePreview({"x": file.position.x, "y": file.position.y, "fileId": file._id, "fileName": file.name});
    }
    if isVideoFile(file) {
        return startVideoPlayer({"x": file.position.x, "y": file.position.y, "fileId": file._id, "fileName": file.name});
    }
    if isTextFile(file) {
        return startTextPreview({"x": file.position.x, "y": file.position.y, "fileId": file._id, "fileName": file.name});
    }
    return None;
}

