      execute({});
    } else {
      proModal.onOpen();
    }
  }

  return (
    <Button
      variant="primary"
      onClick={onClick}
      disabled={isLoading}
    >
      {isPro ? "Manage subscription" : "Upgrade to pro"}
    </Button>
  )
};

