  "==": EQ,
  "!=": NEQ,
  ">=": GEQ,
  "<=": LEQ,
  "<": LT,
  ">": GT,
  "+": ADD,
  "-": SUB,
  "*": MUL,
  "/": DIV,
  "%": MOD,
};

