async def getBlurDataURL(src: str, width: int = 10, quality: int = 1) -> str {
    cdnUrl = uploadcareLoader({"src": src, "width": width, "quality": quality});
    response = urllib.request.urlopen(cdnUrl);
    contentType = response.headers.get_content_type();
    data = response.read();
    response.close();
    encoded = base64.b64encode(data).decode("utf-8");
    return f"data:{contentType};base64,{encoded}";
}

