    base = Path(str(__file__)).resolve().parent.parent;
    env_paths: list[Path] = [base / ".env.local", base / ".env"];
    for env_path in env_paths {
        if env_path.exists() {
            try {
                content = env_path.read_text(encoding="utf-8");
                for line in content.split("\n") {
                    m = re.match(r"^\s*([\w.-]+)\s*=\s*(.*)?\s*$", line);
                    if m is not None {
                        key = m.group(1);
                        value = m.group(2) or "";
