import { useCallback, useEffect, useRef, useState } from 'react';
import { WatchedTitle, WatchedToggleResult } from '../types';
import { useAuth } from '../contexts/AuthContext';
import { isSupabaseConfigured } from '../lib/supabase';
import {
  fetchWatchedTitles,
  markWatchedCloud,
  unmarkWatchedCloud,
  uploadWatchedToCloud,
} from '../services/watchedService';

const LS_KEY = 'moviemonk_watched';
const CLOUD_WATCHED_CACHE_PREFIX = 'moviemonk_cloud_watched_cache_v1';

function loadLocalWatched(): WatchedTitle[] {
  try {
    const raw = localStorage.getItem(LS_KEY);
    return raw ? (JSON.parse(raw) as WatchedTitle[]) : [];
  } catch {
    return [];
  }
}

function saveLocalWatched(items: WatchedTitle[]): void {
  try {
    localStorage.setItem(LS_KEY, JSON.stringify(items));
  } catch {
    // storage full – silent
  }
}

function clearLocalWatched(): void {
  try {
    localStorage.removeItem(LS_KEY);
  } catch { /* noop */ }
}

function readCloudWatchedCache(userId: string): WatchedTitle[] {
  try {
    const raw = localStorage.getItem(`${CLOUD_WATCHED_CACHE_PREFIX}:${userId}`);
    return raw ? (JSON.parse(raw) as WatchedTitle[]) : [];
  } catch {
    return [];
  }
}

function writeCloudWatchedCache(userId: string, items: WatchedTitle[]): void {
  try {
    localStorage.setItem(`${CLOUD_WATCHED_CACHE_PREFIX}:${userId}`, JSON.stringify(items));
  } catch {
    // storage full – silent
  }
}

// ─── Hook ────────────────────────────────────────────────────────────────────

export function useWatched() {
  const { user } = useAuth();
  const [watched, setWatched] = useState<WatchedTitle[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const migrationAttempted = useRef(false);

  const isCloud = Boolean(user && isSupabaseConfigured);

  // Load on mount / user change with instant 0ms local cache hydration
  useEffect(() => {
    if (isCloud && user?.id) {
      const cached = readCloudWatchedCache(user.id);
      if (cached.length > 0) {
        setWatched(cached);
      }

      setIsLoading(true);
      fetchWatchedTitles(user.id)
        .then((fetched) => {
          setWatched(fetched);
          writeCloudWatchedCache(user.id, fetched);
        })
        .catch(() => {
          // If network fetch fails, keep cached items so user never sees 0
        })
        .finally(() => setIsLoading(false));
    } else {
      setWatched(loadLocalWatched());
    }
  }, [isCloud, user?.id]);

  // Keep local cache synced on state changes
  useEffect(() => {
    if (isCloud && user?.id && watched !== undefined) {
      writeCloudWatchedCache(user.id, watched);
    }
  }, [isCloud, user?.id, watched]);

  // Auto-migrate local → cloud on first sign-in
  useEffect(() => {
    if (!isCloud || !user?.id || migrationAttempted.current) return;
    migrationAttempted.current = true;

    const local = loadLocalWatched();
    if (local.length === 0) return;

    uploadWatchedToCloud(user.id, local)
      .then(() => {
        clearLocalWatched();
        return fetchWatchedTitles(user.id!);
      })
      .then((merged) => setWatched(merged))
      .catch(() => {
        // cloud failed – keep local state, don't clear local
      });
  }, [isCloud, user?.id]);

  // ── isWatched ──────────────────────────────────────────────────────────────
  const isWatched = useCallback(
    (tmdbId: string, mediaType: 'movie' | 'tv'): boolean =>
      watched.some((w) => w.tmdb_id === tmdbId && w.media_type === mediaType),
    [watched]
  );

  // ── toggle ─────────────────────────────────────────────────────────────────
  const toggle = useCallback(
    async (entry: Omit<WatchedTitle, 'id' | 'user_id' | 'watched_at'>) => {
      const previousEntry = watched.find(
        (w) => w.tmdb_id === entry.tmdb_id && w.media_type === entry.media_type
      );
      const already = Boolean(previousEntry);

      if (already) {
        // Optimistic remove
        setWatched((prev) =>
          prev.filter(
            (w) =>
              !(w.tmdb_id === entry.tmdb_id && w.media_type === entry.media_type)
          )
        );

        if (isCloud && user?.id) {
          try {
            await unmarkWatchedCloud(user.id, entry.tmdb_id, entry.media_type);
          } catch (error) {
            console.warn('Cloud unmark watched failed (RLS/auth), persisting to local storage:', error);
            const next = loadLocalWatched().filter(
              (w) =>
                !(w.tmdb_id === entry.tmdb_id && w.media_type === entry.media_type)
            );
            saveLocalWatched(next);
          }
        } else {
          const next = loadLocalWatched().filter(
            (w) =>
              !(w.tmdb_id === entry.tmdb_id && w.media_type === entry.media_type)
          );
          saveLocalWatched(next);
        }

        const result: WatchedToggleResult = {
          action: 'unmarked',
          entry: {
            ...(previousEntry || entry),
            watched_at: previousEntry?.watched_at || new Date().toISOString()
          },
          previousEntry
        };
        return result;
      } else {
        // Optimistic add
        const newEntry: WatchedTitle = {
          ...entry,
          watched_at: new Date().toISOString(),
        };
        setWatched((prev) => [newEntry, ...prev]);

        if (isCloud && user?.id) {
          try {
            await markWatchedCloud(user.id, entry);
          } catch (error) {
            console.warn('Cloud mark watched failed (RLS/auth), persisting to local storage:', error);
            const next = [
              newEntry,
              ...loadLocalWatched().filter(
                (w) =>
                  !(w.tmdb_id === entry.tmdb_id && w.media_type === entry.media_type)
              ),
            ];
            saveLocalWatched(next);
          }
        } else {
          const next = [newEntry, ...loadLocalWatched()];
          saveLocalWatched(next);
        }

        const result: WatchedToggleResult = {
          action: 'marked',
          entry: newEntry
        };
        return result;
      }
    },
    [isCloud, user?.id, watched]
  );

  return {
    watched,
    isWatched,
    toggle,
    isLoading,
    watchedCount: watched.length,
  };
}

