import from "react-d3-tree" { default as Tree, ReactD3TreeProps }
import from "datastore/collections/tree/tree.model" { UnionedTreeData }
import from "helpers/tree" { REGULAR_NODE_SVG_STYLE }

glob TEXT_LAYOUT = {"textAnchor": "middle", "x": 0, "y": 0};

def pathFunc(link: dict[str, object]) -> str | None {
    source = link["source"] as dict[str, object];
    target = link["target"] as dict[str, object];
    if target["type"] == "plus" {
        return None;
    }
    return f"M{source['x']},{source['y']}L{target['x']},{target['y']}";
}

def:pub TreeView(
    data: object,
    onClick: Callable[[UnionedTreeData, Event], None] | None = None
) -> JsxElement {
    has width: int = 0;
    has height: int = 0;

    can with entry {
        width = window.innerWidth as int;
        height = window.innerHeight as int;
    }

    return <Tree data={data} collapsible={False} nodeSvgShape={REGULAR_NODE_SVG_STYLE} orientation="vertical" textLayout={TEXT_LAYOUT} transitionDuration={0} translate={{"x": width / 2, "y": height / 3}} onClick={onClick} pathFunc={pathFunc} />;
}

