import React from "react";
import { X } from "lucide-react";

interface ModalProps {
  isOpen: boolean;
  onClose: () => void;
  title?: string;
  children: React.ReactNode;
  size?: "sm" | "md" | "lg" | "xl";
  showCloseButton?: boolean;
}

export const Modal: React.FC<ModalProps> = ({
  isOpen,
  onClose,
  title,
  children,
  size = "md",
  showCloseButton = true,
}) => {
  if (!isOpen) return null;

  const sizes = {
    sm: "max-w-md",
    md: "max-w-lg",
    lg: "max-w-2xl",
    xl: "max-w-4xl",
  };

  return (
    <div className="fixed inset-0 z-50 overflow-y-auto">
      {/* Backdrop */}
      <div
        className="fixed inset-0 bg-black/50 transition-opacity"
        onClick={onClose}
      />

      {/* Modal */}
      <div className="flex min-h-full items-center justify-center p-4">
        <div
          className={`relative w-full ${sizes[size]} bg-white rounded-lg shadow-xl transform transition-all`}
          onClick={(e) => e.stopPropagation()}
        >
          {/* Header */}
          {(title || showCloseButton) && (
            <div className="flex items-center justify-between p-6 border-b border-border">
              {title && (
                <h2 className="text-xl font-bold text-text">{title}</h2>
              )}
              {showCloseButton && (
                <button
                  onClick={onClose}
                  className="text-text-secondary hover:text-text transition-colors"
                >
                  <X className="w-6 h-6" />
                </button>
              )}
            </div>
          )}

          {/* Content */}
          <div className="p-6">{children}</div>
        </div>
      </div>
    </div>
  );
};

jac:
def:pub Modal(
    isOpen: bool,
    onClose: Callable[[], None],
    title: str | None = None,
    children: object | None = None,
    size: str = "md",
    showCloseButton: bool = True,
) -> JsxElement {
    if not isOpen {
        return <></>;
    }

    sizeClass = "max-w-lg";
    if size == "sm" {
        sizeClass = "max-w-md";
    } elif size == "lg" {
        sizeClass = "max-w-2xl";
    } elif size == "xl" {
        sizeClass = "max-w-4xl";
    }

    def stop_prop(e: MouseEvent) {
        e.stopPropagation();
    }

    <div className="fixed inset-0 z-50 overflow-y-auto">
        <div className="fixed inset-0 bg-black/50 transition-opacity" onClick={onClose} />
        <div className="flex min-h-full items-center justify-center p-4">
            <div className={f"relative w-full {sizeClass} bg-white rounded-lg shadow-xl transform transition-all"} onClick={stop_prop}>
                {if title or showCloseButton {
                    <div className="flex items-center justify-between p-6 border-b border-border">
                        {if title {
                            <h2 className="text-xl font-bold text-text">{title}</h2>
                        }}
                        {if showCloseButton {
                            <button onClick={onClose} className="text-text-secondary hover:text-text transition-colors">
