import from "@ninna-ui/utils" { cn }

glob HEADING_LEVEL_SIZES: dict[str, str] = {
    "h1": "text-4xl",
    "h2": "text-3xl",
    "h3": "text-2xl",
    "h4": "text-xl",
    "h5": "text-lg",
    "h6": "text-base",
};

glob HEADING_LEVEL_WEIGHTS: dict[str, str] = {
    "h1": "font-bold",
    "h2": "font-semibold",
    "h3": "font-semibold",
    "h4": "font-medium",
    "h5": "font-medium",
    "h6": "font-medium",
};

glob HEADING_LINE_CLAMP: dict[str, str] = {
    "1": "line-clamp-1",
    "2": "line-clamp-2",
    "3": "line-clamp-3",
    "4": "line-clamp-4",
    "5": "line-clamp-5",
    "6": "line-clamp-6",
};

def headingVariants(
    size: str | None = None,
    weight: str | None = None,
    color: str | None = None,
    align: str | None = None,
    truncate: bool = False,
    noWrap: bool = False,
) -> str {
    c = color if color is not None else "neutral";
    return cn(
        "heading",
        f"heading-size-{size}" if size is not None else "",
        f"heading-weight-{weight}" if weight is not None else "",
        f"heading-color-{c}",
        f"heading-align-{align}" if align is not None else "",
        "truncate" if truncate else "",
        "whitespace-nowrap" if noWrap else "",
    );
}

def:pub Heading(
    as_: str = "h2",
    size: str | None = None,
    weight: str | None = None,
    color: str = "neutral",
    align: str | None = None,
    truncate: bool = False,
    lineClamp: str | None = None,
    noWrap: bool = False,
    className: str | None = None,
    children: object | None = None,
    ref: Ref[HTMLHeadingElement] = Ref(),
    props: dict[str, object] = {},
) -> JsxElement {
  truncateVal = truncate and not lineClamp;
  classes = cn(
      headingVariants(size=size, weight=weight, color=color, align=align, truncate=truncateVal, noWrap=noWrap),
      HEADING_LEVEL_SIZES.get(as_, "") if size is None else "",
      HEADING_LEVEL_WEIGHTS.get(as_, "") if weight is None else "",
      HEADING_LINE_CLAMP.get(lineClamp, "") if lineClamp else "",
      className,
  );
  <@as_ ref={ref} data-slot="heading" className={classes} {**props}>{children}</@as_>
}

