 * <IconButton icon={<SearchIcon />} aria-label="Search" />
 * <IconButton icon={<EditIcon />} variant="ghost" aria-label="Edit" />
 * <IconButton icon={<DeleteIcon />} color="danger" aria-label="Delete" />
 * ```
 */
const IconButtonIcon = ({ icon, size, loading }: { icon: React.ReactNode; size: Size; loading?: boolean }) => {
  if (loading) {
    return (
      <span
        className={cn(
          'animate-spin rounded-full border-2 border-current border-t-transparent',
          ICON_BUTTON_SPINNER_SIZES[size]
        )}
        aria-hidden="true"
      />
    );
  }

  return (
    <span data-slot="icon" className={cn('inline-flex items-center justify-center', ICON_SIZES[size])} aria-hidden="true">
      {icon}
    </span>
  );
};

export const IconButton = forwardRef<HTMLButtonElement, IconButtonProps>(
  (
    {
      icon,
      variant = 'solid',
      color = 'primary',
      size = 'md',
      radius = 'md',
      loading = false,
      disabled,
      className,
      "aria-label": ariaLabel,
      ...props
    },
    ref
  ) => {
    const isDisabled = disabled || loading;

    return (
      <button
        ref={ref}
        data-slot="icon-button"
        type="button"
        className={cn(
          iconButtonVariants({ variant, color, size, radius }),
          className
        )}
        disabled={isDisabled}
        aria-disabled={isDisabled}
        aria-busy={loading}
        aria-label={ariaLabel}
        data-loading={loading}
        {...props}
      >
        <IconButtonIcon icon={icon} size={size} loading={loading} />
      </button>
    );
  }
);

IconButton.displayName = 'IconButton';

