  children: ReactNode;
  /** Additional CSS classes */
  className?: string;
}

/**
 * CheckboxGroupItem props
 */
export interface CheckboxGroupItemProps extends Omit<CheckboxProps, 'checked' | 'defaultChecked' | 'onCheckedChange'> {
