import from "@/lib/utils" { cn }

glob BADGE_BASE: str = "inline-flex items-center rounded-md border px-2.5 py-0.5 text-xs font-semibold transition-colors focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2";

glob BADGE_VARIANT_CLASSES: dict[str, str] = {
    "default": "border-transparent bg-primary text-primary-foreground shadow hover:bg-primary/80",
    "secondary": "border-transparent bg-secondary text-secondary-foreground hover:bg-secondary/80",
    "destructive": "border-transparent bg-destructive text-destructive-foreground shadow hover:bg-destructive/80",
    "outline": "text-foreground",
};

def:pub badgeVariants(variant: str | None = None) -> str {
    v = variant or "default";
    return cn(BADGE_BASE, BADGE_VARIANT_CLASSES.get(v, ""));
}

def:pub Badge(
    className: str | None = None,
    variant: str | None = None,
    children: object | None = None,
    props: dict[str, object] = {},
) -> JsxElement {
    <div className={cn(badgeVariants(variant=variant), className)} {**props}>{children}</div>
}

