        <div className="grid gap-1">
            {title and <ToastTitle>{title}</ToastTitle>}
            {description and <ToastDescription>{description}</ToastDescription>}
        </div>
        {action}
        <ToastClose />
    </Toast>
}

def:pub Toaster() -> JsxElement {
