import os;

def:pub makeUrl(path: str, parameters: dict[str, object] | None = None) -> str {
    if not parameters {
        return path;
    }
    keys = list(parameters.keys());
    params = "&".join([f"{key}={parameters[key]}" for key in keys]);
    return f"{path}?{params}";
}

glob:pub BASE_URL: str = (
    os.environ["NEXT_PUBLIC_API_PRODUCTION_URL"]
    if os.environ.get("NODE_ENV") == "production"
    else os.environ["NEXT_PUBLIC_API_DEVELOPMENT_URL"]
);

