    expect(getResponsiveGridCols({ base: 1, md: 2, lg: 4 })).toBe(
      "grid-cols-1 md:grid-cols-2 lg:grid-cols-4",
    );
  });

  it("returns an empty string for an empty responsive map", () => {
    expect(getResponsiveGridCols({})).toBe("");
  });
});

