/**
 * TagColorPicker Component
 *
 * Color picker for assigning colors to tags
 * Features:
 * - 12-color palette grid (same as Status field colors)
 * - "No color" option
 * - Preview of tag with selected color
 */

import { Check } from 'lucide-react';

export interface TagColorPickerProps {
  /** Selected color (semantic token name) */
  selectedColor?: string;
  /** Callback when color is selected */
  onColorSelect: (color: string) => void;
  /** Tag name for preview */
  tagName: string;
}

/**
 * Available tag colors (semantic tokens)
 * Same palette as Status custom field type
 */
export const TAG_COLORS = [
  { name: 'blue', token: 'accent-blue', displayName: 'Blue' },
  { name: 'cyan', token: 'accent-primary', displayName: 'Cyan' },
  { name: 'purple', token: 'accent-purple', displayName: 'Purple' },
  { name: 'magenta', token: 'accent-primary', displayName: 'Magenta' },
  { name: 'green', token: 'status-success', displayName: 'Green' },
  { name: 'yellow', token: 'status-warning', displayName: 'Yellow' },
  { name: 'orange', token: 'accent-orange', displayName: 'Orange' },
  { name: 'red', token: 'status-error', displayName: 'Red' },
  { name: 'gray', token: 'text-light-tertiary', displayName: 'Gray' },
  { name: 'slate', token: 'border-light', displayName: 'Slate' },
  { name: 'pink', token: 'accent-pink', displayName: 'Pink' },
  { name: 'indigo', token: 'accent-indigo', displayName: 'Indigo' },
] as const;

export function TagColorPicker({ selectedColor, onColorSelect, tagName }: TagColorPickerProps) {
  return (
    <div className="space-y-4">
      {/* Preview */}
      <div>
        <label className="block text-xs font-medium text-text-light-secondary dark:text-text-dark-secondary mb-2">
          Preview
        </label>
        <div className="flex items-center gap-2">
          <span
            className={`inline-flex items-center gap-1 px-2 py-1 text-xs font-medium rounded ${
              selectedColor
                ? `bg-${selectedColor}/10 text-${selectedColor} dark:bg-${selectedColor}/20`
                : 'bg-border-light dark:bg-border-dark text-text-light-secondary dark:text-text-dark-secondary'
            }`}
          >
            {tagName}
          </span>
        </div>
      </div>

      {/* Color Grid */}
      <div>
        <label className="block text-xs font-medium text-text-light-secondary dark:text-text-dark-secondary mb-2">
          Select Color
        </label>
        <div className="grid grid-cols-4 gap-2">
          {/* No Color Option */}
          <button
            onClick={() => onColorSelect('')}
            className={`
              relative h-10 rounded border-2 transition-all
              bg-surface-light-elevated dark:bg-surface-dark-elevated
              ${
                !selectedColor
                  ? 'border-accent-primary'
                  : 'border-border-light dark:border-border-dark hover:border-accent-primary/50'
              }
            `}
            title="No color"
          >
            <span className="text-xs text-text-light-secondary dark:text-text-dark-secondary">None</span>
            {!selectedColor && (
              <Check className="absolute top-1 right-1 w-3 h-3 text-accent-primary" />
            )}
          </button>

          {/* Color Options */}
          {TAG_COLORS.map((color) => (
            <button
              key={color.name}
              onClick={() => onColorSelect(color.token)}
              className={`
                relative h-10 rounded border-2 transition-all
                bg-${color.token} bg-opacity-20 dark:bg-opacity-30
                ${
                  selectedColor === color.token
                    ? 'border-accent-primary'
                    : 'border-border-light dark:border-border-dark hover:border-accent-primary/50'
                }
              `}
              title={color.displayName}
            >
              {selectedColor === color.token && (
                <Check className="absolute top-1 right-1 w-3 h-3 text-accent-primary" />
              )}
            </button>
          ))}
        </div>
      </div>
    </div>
  );
}

/**
 * TemplatePicker Component
 *
 * Modal for selecting document templates when creating new documents.
 * Shows template categories and previews.
 */

import { useState } from 'react';
import {
  FileText,
  BarChart2,
  Users,
  Target,
  Code,
  Lightbulb,
  Mail,
  Calendar,
  Search,
  X,
} from 'lucide-react';
import {
  DOCUMENT_TEMPLATES,
  getTemplateCategories,
  type DocumentTemplate,
} from './documentTemplates';

interface TemplatePickerProps {
  /** Called when a template is selected */
  onSelect: (template: DocumentTemplate) => void;
  /** Called when the picker is closed */
  onClose: () => void;
}

// Map icon names to Lucide components
const ICON_MAP: Record<string, React.ComponentType<{ className?: string }>> = {
  FileText,
  BarChart2,
  Users,
  Target,
  Code,
  Lightbulb,
  Mail,
  Calendar,
  Search,
};

export function TemplatePicker({ onSelect, onClose }: TemplatePickerProps) {
  const [selectedCategory, setSelectedCategory] = useState<DocumentTemplate['category'] | 'all'>('all');
  const categories = getTemplateCategories();

  const filteredTemplates =
    selectedCategory === 'all'
      ? DOCUMENT_TEMPLATES
      : DOCUMENT_TEMPLATES.filter((t) => t.category === selectedCategory);

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
      {/* Backdrop */}
      <div
        className="absolute inset-0 bg-black/50 backdrop-blur-sm"
        onClick={onClose}
        aria-hidden="true"
      />

      {/* Modal */}
      <div className="relative bg-surface-light dark:bg-surface-dark-elevated rounded-xl shadow-2xl w-full max-w-3xl max-h-[80vh] flex flex-col overflow-hidden">
        {/* Header */}
        <div className="flex items-center justify-between px-6 py-4 border-b border-border-light dark:border-border-dark">
          <h2 className="text-xl font-semibold text-text-light-primary dark:text-text-dark-primary">
            Choose a Template
          </h2>
          <button
            onClick={onClose}
            className="p-2 rounded-lg text-text-light-tertiary dark:text-text-dark-tertiary hover:bg-surface-light-alt dark:hover:bg-surface-dark transition-colors"
            aria-label="Close template picker"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Category tabs */}
        <div className="flex gap-2 px-6 py-3 border-b border-border-light dark:border-border-dark overflow-x-auto">
          <button
            onClick={() => setSelectedCategory('all')}
            className={`px-3 py-1.5 rounded-full text-sm font-medium whitespace-nowrap transition-colors ${
              selectedCategory === 'all'
                ? 'bg-accent-primary text-white'
                : 'bg-surface-light-alt dark:bg-surface-dark text-text-light-secondary dark:text-text-dark-secondary hover:bg-surface-light dark:hover:bg-surface-dark-elevated'
            }`}
          >
            All ({DOCUMENT_TEMPLATES.length})
          </button>
          {categories.map(({ category, label, count }) => (
            <button
              key={category}
              onClick={() => setSelectedCategory(category)}
              className={`px-3 py-1.5 rounded-full text-sm font-medium whitespace-nowrap transition-colors ${
                selectedCategory === category
                  ? 'bg-accent-primary text-white'
                  : 'bg-surface-light-alt dark:bg-surface-dark text-text-light-secondary dark:text-text-dark-secondary hover:bg-surface-light dark:hover:bg-surface-dark-elevated'
              }`}
            >
              {label} ({count})
            </button>
          ))}
        </div>

        {/* Template grid */}
        <div className="flex-1 overflow-y-auto p-6">
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
            {filteredTemplates.map((template) => {
              const IconComponent = ICON_MAP[template.icon] || FileText;

              return (
                <button
                  key={template.id}
                  onClick={() => onSelect(template)}
                  className="flex flex-col items-start p-4 rounded-lg border border-border-light dark:border-border-dark bg-surface-light dark:bg-surface-dark hover:border-accent-primary dark:hover:border-accent-primary hover:shadow-md transition-all text-left group"
                >
                  <div className="flex items-center gap-3 mb-2">
                    <div className="p-2 rounded-lg bg-accent-primary/10 text-accent-primary group-hover:bg-accent-primary group-hover:text-white transition-colors">
                      <IconComponent className="w-5 h-5" />
                    </div>
                    <h3 className="font-medium text-text-light-primary dark:text-text-dark-primary">
                      {template.name}
                    </h3>
                  </div>
                  <p className="text-sm text-text-light-tertiary dark:text-text-dark-tertiary line-clamp-2">
                    {template.description}
                  </p>
                  <span className="mt-2 text-xs text-text-light-tertiary dark:text-text-dark-tertiary capitalize bg-surface-light-alt dark:bg-surface-dark-elevated px-2 py-0.5 rounded">
                    {template.category}
                  </span>
                </button>
              );
            })}
          </div>
        </div>

        {/* Footer */}
        <div className="px-6 py-3 border-t border-border-light dark:border-border-dark bg-surface-light-alt dark:bg-surface-dark">
          <p className="text-sm text-text-light-tertiary dark:text-text-dark-tertiary text-center">
            Select a template to get started, or choose "Blank Document" for an empty page
          </p>
        </div>
      </div>
    </div>
  );
}

export default TemplatePicker;

/**
 * CalloutNode - Custom Lexical DecoratorNode for Callout/Admonition Blocks
 *
 * Types: info (blue), warning (yellow), tip (green), danger (red)
 * Renders as a styled container with icon + colored border/background
 */

import React, { useState, useCallback } from 'react';
import { DecoratorNode } from 'lexical';
import { useLexicalComposerContext } from '@lexical/react/LexicalComposerContext';
import type {
  LexicalNode,
  NodeKey,
  SerializedLexicalNode,
  Spread,
  EditorConfig,
} from 'lexical';

export type CalloutType = 'info' | 'warning' | 'tip' | 'danger';

export interface CalloutPayload {
  calloutType: CalloutType;
  title?: string;
  content?: string;
  key?: NodeKey;
}

export type SerializedCalloutNode = Spread<
  {
    calloutType: CalloutType;
    title: string;
    content: string;
  },
  SerializedLexicalNode
>;

const CALLOUT_CONFIG: Record<
  CalloutType,
  { icon: string; label: string; borderColor: string; bgColor: string; textColor: string }
> = {
  info: {
    icon: 'ℹ️',
    label: 'Info',
    borderColor: 'border-blue-400 dark:border-blue-500',
    bgColor: 'bg-blue-50 dark:bg-blue-950/30',
    textColor: 'text-blue-700 dark:text-blue-300',
  },
  warning: {
    icon: '⚠️',
    label: 'Warning',
    borderColor: 'border-yellow-400 dark:border-yellow-500',
    bgColor: 'bg-yellow-50 dark:bg-yellow-950/30',
    textColor: 'text-yellow-700 dark:text-yellow-300',
  },
  tip: {
    icon: '💡',
    label: 'Tip',
    borderColor: 'border-green-400 dark:border-green-500',
    bgColor: 'bg-green-50 dark:bg-green-950/30',
    textColor: 'text-green-700 dark:text-green-300',
  },
  danger: {
    icon: '🚨',
    label: 'Danger',
    borderColor: 'border-red-400 dark:border-red-500',
    bgColor: 'bg-red-50 dark:bg-red-950/30',
    textColor: 'text-red-700 dark:text-red-300',
  },
};

/**
 * CalloutComponent - React component rendered by the DecoratorNode
 */
function CalloutComponent({
  nodeKey,
  calloutType,
  title,
  content,
}: {
  nodeKey: NodeKey;
  calloutType: CalloutType;
  title: string;
  content: string;
}) {
  const [editor] = useLexicalComposerContext();
  const [editableTitle, setEditableTitle] = useState(title);
  const [editableContent, setEditableContent] = useState(content);
  const config = CALLOUT_CONFIG[calloutType];

  const updateNode = useCallback(
    (newTitle: string, newContent: string) => {
      editor.update(() => {
        const node = editor.getEditorState()._nodeMap.get(nodeKey);
        if (node && $isCalloutNode(node)) {
          const writable = node.getWritable();
          writable.__title = newTitle;
          writable.__content = newContent;
        }
      });
    },
    [editor, nodeKey]
  );

  const handleTitleChange = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      const newTitle = e.target.value;
      setEditableTitle(newTitle);
      updateNode(newTitle, editableContent);
    },
    [updateNode, editableContent]
  );

  const handleContentChange = useCallback(
    (e: React.ChangeEvent<HTMLTextAreaElement>) => {
      const newContent = e.target.value;
      setEditableContent(newContent);
      updateNode(editableTitle, newContent);
    },
    [updateNode, editableTitle]
  );

  const handleDelete = useCallback(() => {
    editor.update(() => {
      const node = editor.getEditorState()._nodeMap.get(nodeKey);
      if (node) {
        node.remove();
      }
    });
  }, [editor, nodeKey]);

  return (
    <div
      className={`my-4 border-l-4 rounded-r-lg p-4 ${config.borderColor} ${config.bgColor} group relative`}
    >
      {/* Delete button */}
      <button
        onClick={handleDelete}
        className="absolute top-2 right-2 opacity-0 group-hover:opacity-100 transition-opacity p-1 rounded hover:bg-black/10 dark:hover:bg-white/10 text-xs"
        title="Remove callout"
      >
        ✕
      </button>

      {/* Title row */}
      <div className={`flex items-center gap-2 mb-2 ${config.textColor} font-semibold`}>
        <span>{config.icon}</span>
        <input
          type="text"
          value={editableTitle}
          onChange={handleTitleChange}
          placeholder={config.label}
          className={`bg-transparent border-none outline-none font-semibold flex-1 ${config.textColor} placeholder:opacity-50`}
        />
      </div>

      {/* Content */}
      <textarea
        value={editableContent}
        onChange={handleContentChange}
        placeholder="Type callout content here..."
        className={`w-full bg-transparent border-none outline-none resize-none text-sm leading-relaxed text-text-light-primary dark:text-text-dark-primary placeholder:opacity-40 min-h-[2rem]`}
        rows={Math.max(1, editableContent.split('\n').length)}
      />
    </div>
  );
}

export class CalloutNode extends DecoratorNode<React.ReactElement> {
  __calloutType: CalloutType;
  __title: string;
  __content: string;

  static getType(): string {
    return 'callout';
  }

  static clone(node: CalloutNode): CalloutNode {
    return new CalloutNode(node.__calloutType, node.__title, node.__content, node.__key);
  }

  static importJSON(serializedNode: SerializedCalloutNode): CalloutNode {
    return $createCalloutNode({
      calloutType: serializedNode.calloutType,
      title: serializedNode.title,
      content: serializedNode.content,
    });
  }

  exportJSON(): SerializedCalloutNode {
    return {
      type: 'callout',
      version: 1,
      calloutType: this.__calloutType,
      title: this.__title,
      content: this.__content,
    };
  }

  constructor(calloutType: CalloutType, title: string, content: string, key?: NodeKey) {
    super(key);
    this.__calloutType = calloutType;
    this.__title = title;
    this.__content = content;
  }

  createDOM(_config: EditorConfig): HTMLElement {
    const div = document.createElement('div');
    div.className = 'callout-node';
    return div;
  }

  updateDOM(): boolean {
    return false;
  }

  decorate(): React.ReactElement {
    return (
      <CalloutComponent
        nodeKey={this.__key}
        calloutType={this.__calloutType}
        title={this.__title}
        content={this.__content}
      />
    );
  }

  getTextContent(): string {
    return `${this.__title}\n${this.__content}`;
  }

  isInline(): boolean {
    return false;
  }
}

export function $createCalloutNode(payload: CalloutPayload): CalloutNode {
  return new CalloutNode(
    payload.calloutType,
    payload.title ?? '',
    payload.content ?? '',
    payload.key
  );
}

export function $isCalloutNode(node: LexicalNode | null | undefined): node is CalloutNode {
  return node instanceof CalloutNode;
}

