import from "zustand" { create }
import from "zustand/middleware" { persist }

glob MAX_CSS_BYTES = 51200;

glob initialState: dict[str, object] = {"css": "", "enabled": False, "lastUpdated": ""};

def customCSSStoreInitializer(setFn: Callable[[object], None]) -> dict[str, object] {
    def updateCSS(css: str) -> None {
        if len(css) > MAX_CSS_BYTES {
            return;
        }
        setFn({"css": css, "lastUpdated": Date().toISOString()});
    }
    def toggleEnabled() {
        def flip(state: dict[str, object]) -> dict[str, object] {
            return {**state, "enabled": not state["enabled"]};
        }
        setFn(flip);
    }
    def resetCSS() {
        setFn({"css": "", "enabled": False, "lastUpdated": ""});
    }
    return {
        **initialState,
        "updateCSS": updateCSS,
        "toggleEnabled": toggleEnabled,
        "resetCSS": resetCSS,
    };
}

glob useCustomCSSStore = create()(persist(customCSSStoreInitializer, {"name": "custom-css-preferences"}));

