    has user: DevToUser;
    has positive_reactions_count: int;
    has comments_count: int;
    has published_at: str;
}

def parse_article(raw: dict[str, object]) -> DevToArticle {
    user_raw = raw["user"] as dict[str, str];
    return DevToArticle(
        title=raw["title"] as str,
        url=raw["url"] as str,
        user=DevToUser(name=user_raw["name"]),
        positive_reactions_count=raw["positive_reactions_count"] as int,
        comments_count=raw["comments_count"] as int,
        published_at=raw["published_at"] as str,
    );
}

def:pub DevToWidget() -> JsxElement {
    has articles: list[DevToArticle] = [];
    has loading: bool = True;
    has error: str | None = None;

    async def fetch_articles() {
        loading = True;
        error = None;
        try {
            response = await fetch("https://dev.to/api/articles?per_page=5&top=7");
            if not response.ok {
                raise ValueError("Failed to fetch Dev.to articles");
            }
            raw_list = await response.json() as list[dict[str, object]];
            articles = [parse_article(item) for item in raw_list];
        } except Exception as err {
            error = str(err) if isinstance(err, Exception) else "Failed to load articles";
        } finally {
            loading = False;
