import time;
import from "../helpers/getRequestKey" { getRequestKey }
import from "../types" { EndpointConfig, GlobalConfig, NetworkStatus, EndpointParams }

def setPostRequestProperties(requestProperties: dict) -> dict {
    return {**requestProperties, "body": JSON.stringify(requestProperties["body"])};
}

def setPostHeaders(headers: dict) -> dict {
    return {**headers, "Content-Type": "application/json"};
}

def:pub mockState(
    binding: str,
    hasRequest: bool = False,
    params: dict[str, EndpointParams] | None = None,
    networkStatus: NetworkStatus | None = None,
    config: dict = {},
    globalConfig: dict = {},
    lastCall: int | None = None,
    instanceId: str = ""
) -> dict[str, object] {
    effectiveLastCall = lastCall if lastCall is not None else int(time.time() * 1000);
    binding_params: EndpointParams = params[binding] if params is not None and binding in params else {};
    binding_config = {
        "url": "mockAction.get",
        "setHeaders": (setPostHeaders if config.get("method") == "POST" else None),
        "setRequestProperties": (setPostRequestProperties if config.get("method") == "POST" else None)
    };
    for (key, value) in config.items() {
        binding_config[key] = value;
    }
    endpointConfig = {"getMoreData": {}};
    endpointConfig[binding] = binding_config;
    requests = {};
    if hasRequest {
        requests[getRequestKey(binding, binding_params, instanceId)] = {
            "networkStatus": networkStatus,
            "lastCall": effectiveLastCall,
            "duration": 0
        };
    }
    return {
        "globalConfig": globalConfig,
        "endpointConfig": endpointConfig,
        "requests": requests,
        "entities": {}
    };
}

