def:pub getFiltersOfType(filters: list[SearchFilter], type: str) -> list[str] {
    return [f.value for f in filters if f.type == type];
}

def:pub formatFilter(filter: SearchFilter) -> str {
    match filter.type {
        case "tag":
            return f"tag:{filter.value}";
        case "module":
            return f"in:{filter.value}";
        case "status":
            return f"status:{filter.value}";
        case "date":
            return f"date:{filter.value}";
        case _:
            return f"{filter.type}:{filter.value}";
    }
}

