/**
 * KeyboardShortcutsModal Component
 *
 * Modal displaying keyboard shortcuts for the Notes page.
 * Part of the Notes Page Revolution - Phase 4.
 *
 * Triggered by pressing ? key on the Notes page.
 */

import React from 'react';
import { Keyboard } from 'lucide-react';
import { Modal } from '../Modal';

interface ShortcutGroup {
  title: string;
  shortcuts: { keys: string[]; description: string }[];
}

const SHORTCUT_GROUPS: ShortcutGroup[] = [
  {
    title: 'Folder Navigation',
    shortcuts: [
      { keys: ['↓', 'J'], description: 'Next folder' },
      { keys: ['↑', 'K'], description: 'Previous folder' },
      { keys: ['→', 'L'], description: 'Expand or enter folder' },
      { keys: ['←', 'H'], description: 'Collapse or go to parent' },
      { keys: ['Enter'], description: 'Toggle expand/collapse' },
      { keys: ['Home'], description: 'Go to All Notes' },
      { keys: ['End'], description: 'Go to last folder' },
    ],
  },
  {
    title: 'Notes List Navigation',
    shortcuts: [
      { keys: ['↓', 'J'], description: 'Next note' },
      { keys: ['↑', 'K'], description: 'Previous note' },
      { keys: ['Enter'], description: 'Open note in editor' },
      { keys: ['F'], description: 'Toggle favorite' },
      { keys: ['P'], description: 'Toggle pin' },
      { keys: ['D'], description: 'Delete note (confirm)' },
      { keys: ['Space'], description: 'Toggle selection (bulk mode)' },
      { keys: ['Home'], description: 'First note' },
      { keys: ['End'], description: 'Last note' },
    ],
  },
  {
    title: 'Global Shortcuts',
    shortcuts: [
      { keys: ['Cmd', 'K'], description: 'Focus search' },
      { keys: ['Cmd', 'N'], description: 'New note' },
      { keys: ['Cmd', '\\'], description: 'Toggle sidebar' },
      { keys: ['Cmd', 'Shift', 'E'], description: 'Export notes' },
      { keys: ['?'], description: 'Show this help' },
      { keys: ['Escape'], description: 'Close dialogs/help' },
    ],
  },
];

export interface KeyboardShortcutsModalProps {
  isOpen: boolean;
  onClose: () => void;
}

export const KeyboardShortcutsModal: React.FC<KeyboardShortcutsModalProps> = ({
  isOpen,
  onClose,
}) => {
  return (
    <Modal isOpen={isOpen} onClose={onClose} title="Keyboard Shortcuts" maxWidth="xl">
      <div className="p-6">
        {/* Header */}
        <div className="flex items-center gap-3 mb-6">
          <div className="p-2 bg-accent-primary/10 rounded-lg">
            <Keyboard className="w-6 h-6 text-accent-primary" />
          </div>
          <div>
            <h2 className="text-lg font-semibold text-text-light-primary dark:text-text-dark-primary">
              Keyboard Shortcuts
            </h2>
            <p className="text-sm text-text-light-secondary dark:text-text-dark-secondary">
              Navigate and manage notes efficiently with keyboard
            </p>
          </div>
        </div>

        {/* Shortcut Groups */}
        <div className="grid gap-6 md:grid-cols-2 lg:grid-cols-3">
          {SHORTCUT_GROUPS.map((group) => (
            <div key={group.title}>
              <h3 className="text-sm font-medium uppercase tracking-wide text-text-light-secondary dark:text-text-dark-secondary mb-3">
                {group.title}
              </h3>
              <div className="space-y-2">
                {group.shortcuts.map((shortcut, index) => (
                  <div
                    key={index}
                    className="flex items-center justify-between py-1.5"
                  >
                    <span className="text-sm text-text-light-primary dark:text-text-dark-primary">
                      {shortcut.description}
                    </span>
                    <div className="flex items-center gap-1">
                      {shortcut.keys.map((key, keyIndex) => (
                        <React.Fragment key={keyIndex}>
                          <kbd className="px-2 py-1 text-xs font-mono bg-surface-light-elevated dark:bg-surface-dark-elevated border border-border-light dark:border-border-dark rounded">
                            {key}
                          </kbd>
                          {keyIndex < shortcut.keys.length - 1 && (
                            <span className="text-text-light-tertiary dark:text-text-dark-tertiary text-xs">
                              +
                            </span>
                          )}
                        </React.Fragment>
                      ))}
                    </div>
                  </div>
                ))}
              </div>
            </div>
          ))}
        </div>

        {/* Footer */}
        <div className="mt-6 pt-4 border-t border-border-light dark:border-border-dark">
          <p className="text-xs text-text-light-tertiary dark:text-text-dark-tertiary text-center">
            Press <kbd className="px-1.5 py-0.5 text-xs font-mono bg-surface-light-elevated dark:bg-surface-dark-elevated border border-border-light dark:border-border-dark rounded">?</kbd> anytime to show this help
          </p>
        </div>
      </div>
    </Modal>
  );
};

import React, { useMemo } from 'react';
import { useKanbanStore } from '../../stores/useKanbanStore';
import type { Task } from '../../types';

interface EisenhowerMatrixProps {
  tasks: Task[];
  onTaskClick: (task: Task) => void;
}

type Quadrant = 'do-first' | 'schedule' | 'delegate' | 'eliminate';

function classifyTask(task: Task): Quadrant {
  // Important = high priority
  const isImportant = task.priority === 'high';

  // Urgent = due within 48 hours
  let isUrgent = false;
  if (task.dueDate) {
    const dueDate = new Date(task.dueDate);
    const now = new Date();
    const hoursUntilDue = (dueDate.getTime() - now.getTime()) / (1000 * 60 * 60);
    isUrgent = hoursUntilDue <= 48;
  }

  if (isImportant && isUrgent) return 'do-first';
  if (isImportant && !isUrgent) return 'schedule';
  if (!isImportant && isUrgent) return 'delegate';
  return 'eliminate';
}

const QUADRANT_CONFIG: Record<Quadrant, { title: string; subtitle: string; color: string; bgColor: string; borderColor: string }> = {
  'do-first': {
    title: 'Do First',
    subtitle: 'Urgent & Important',
    color: 'text-status-error',
    bgColor: 'bg-status-error/5 dark:bg-status-error/10',
    borderColor: 'border-status-error/30',
  },
  'schedule': {
    title: 'Schedule',
    subtitle: 'Important, Not Urgent',
    color: 'text-accent-blue',
    bgColor: 'bg-accent-blue/5 dark:bg-accent-blue/10',
    borderColor: 'border-accent-blue/30',
  },
  'delegate': {
    title: 'Delegate',
    subtitle: 'Urgent, Not Important',
    color: 'text-status-warning-text dark:text-status-warning-text-dark',
    bgColor: 'bg-status-warning/5 dark:bg-status-warning/10',
    borderColor: 'border-status-warning/30',
  },
  'eliminate': {
    title: 'Eliminate',
    subtitle: 'Neither',
    color: 'text-text-light-secondary dark:text-text-dark-secondary',
    bgColor: 'bg-surface-light-elevated/50 dark:bg-surface-dark-elevated/50',
    borderColor: 'border-border-light dark:border-border-dark',
  },
};

const QuadrantCell: React.FC<{
  quadrant: Quadrant;
  tasks: Task[];
  onTaskClick: (task: Task) => void;
  onDrop: (taskId: string, quadrant: Quadrant) => void;
}> = ({ quadrant, tasks, onTaskClick, onDrop }) => {
  const config = QUADRANT_CONFIG[quadrant];

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    e.dataTransfer.dropEffect = 'move';
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    const taskId = e.dataTransfer.getData('text/plain');
    if (taskId) onDrop(taskId, quadrant);
  };

  return (
    <div
      className={`rounded-lg border ${config.borderColor} ${config.bgColor} p-4 min-h-[200px] flex flex-col`}
      onDragOver={handleDragOver}
      onDrop={handleDrop}
    >
      <div className="mb-3">
        <h3 className={`font-semibold text-sm ${config.color}`}>
          {config.title}
        </h3>
        <p className="text-xs text-text-light-secondary dark:text-text-dark-secondary">
          {config.subtitle}
        </p>
      </div>
      <div className="flex-1 space-y-2 overflow-y-auto max-h-[300px]">
        {tasks.length === 0 && (
          <p className="text-xs text-text-light-secondary dark:text-text-dark-secondary italic text-center py-4">
            No tasks
          </p>
        )}
        {tasks.map((task) => (
          <div
            key={task.id}
            draggable
            onDragStart={(e) => {
              e.dataTransfer.setData('text/plain', task.id);
            }}
            onClick={() => onTaskClick(task)}
            className="p-2 rounded bg-surface-light dark:bg-surface-dark-elevated border border-border-light dark:border-border-dark cursor-pointer hover:shadow-md transition-shadow text-sm"
          >
            <div className="font-medium text-text-light-primary dark:text-text-dark-primary truncate">
              {task.title}
            </div>
            <div className="flex items-center gap-2 mt-1">
              {task.dueDate && (
                <span className="text-xs text-text-light-secondary dark:text-text-dark-secondary">
                  {new Date(task.dueDate).toLocaleDateString('en-US', { month: 'short', day: 'numeric' })}
                </span>
              )}
              <span className={`text-xs px-1.5 py-0.5 rounded ${
                task.priority === 'high' ? 'bg-status-error/10 text-status-error' :
                task.priority === 'medium' ? 'bg-status-warning/10 text-status-warning-text dark:text-status-warning-text-dark' :
                'bg-status-info/10 text-status-info'
              }`}>
                {task.priority}
              </span>
            </div>
          </div>
        ))}
      </div>
      <div className="mt-2 text-xs text-text-light-secondary dark:text-text-dark-secondary text-right">
        {tasks.length} {tasks.length === 1 ? 'task' : 'tasks'}
      </div>
    </div>
  );
};

export const EisenhowerMatrix: React.FC<EisenhowerMatrixProps> = ({ tasks, onTaskClick }) => {
  const { updateTask } = useKanbanStore();

  // Only show non-done tasks
  const activeTasks = useMemo(() => tasks.filter((t) => t.status !== 'done'), [tasks]);

  const quadrants = useMemo(() => {
    const result: Record<Quadrant, Task[]> = {
      'do-first': [],
      'schedule': [],
      'delegate': [],
      'eliminate': [],
    };
    activeTasks.forEach((task) => {
      const q = classifyTask(task);
      result[q].push(task);
    });
    return result;
  }, [activeTasks]);

  const handleDrop = (taskId: string, quadrant: Quadrant) => {
    // Update task priority/urgency based on target quadrant
    const updates: Partial<Task> = {};

    switch (quadrant) {
      case 'do-first':
        updates.priority = 'high';
        // Set due date to today if no due date
        if (!updates.dueDate) {
          updates.dueDate = new Date().toISOString().split('T')[0];
        }
        break;
      case 'schedule':
        updates.priority = 'high';
        // Remove urgency by pushing due date out
        break;
      case 'delegate':
        updates.priority = 'medium';
        if (!updates.dueDate) {
          updates.dueDate = new Date().toISOString().split('T')[0];
        }
        break;
      case 'eliminate':
        updates.priority = 'low';
        break;
    }

    updateTask(taskId, updates);
  };

  return (
    <div className="eisenhower-matrix">
      {/* Axis Labels */}
      <div className="flex items-center justify-center gap-2 mb-2">
        <span className="text-xs font-semibold text-text-light-secondary dark:text-text-dark-secondary uppercase tracking-wide">
          Urgent
        </span>
        <span className="text-xs text-text-light-secondary dark:text-text-dark-secondary">
          ---
        </span>
        <span className="text-xs font-semibold text-text-light-secondary dark:text-text-dark-secondary uppercase tracking-wide">
          Not Urgent
        </span>
      </div>

      <div className="grid grid-cols-2 gap-3">
        {/* Row 1: Important */}
        <QuadrantCell quadrant="do-first" tasks={quadrants['do-first']} onTaskClick={onTaskClick} onDrop={handleDrop} />
        <QuadrantCell quadrant="schedule" tasks={quadrants['schedule']} onTaskClick={onTaskClick} onDrop={handleDrop} />

        {/* Row 2: Not Important */}
        <QuadrantCell quadrant="delegate" tasks={quadrants['delegate']} onTaskClick={onTaskClick} onDrop={handleDrop} />
        <QuadrantCell quadrant="eliminate" tasks={quadrants['eliminate']} onTaskClick={onTaskClick} onDrop={handleDrop} />
      </div>

      <div className="flex items-center justify-between mt-2 px-1">
        <span className="text-xs font-semibold text-text-light-secondary dark:text-text-dark-secondary uppercase tracking-wide">
          Important
        </span>
        <span className="text-xs font-semibold text-text-light-secondary dark:text-text-dark-secondary uppercase tracking-wide">
          Not Important
        </span>
      </div>
    </div>
  );
};

