import { create } from 'zustand';
import { persist, createJSONStorage } from 'zustand/middleware';
import { createSyncedStorage } from '../lib/syncedStorage';

/**
 * Time Tracking Panel Store
 * Manages UI preferences for the sidebar time tracking panel
 */

export type EntryDisplayDensity = 'compact' | 'normal' | 'comfortable';
export type TimeFormat = '12h' | '24h';

interface TimeTrackingPanelState {
  // Panel layout preferences
  recentEntriesHeight: number; // Height of recent entries list in pixels (0-400px)
  visibleEntries: number; // Number of entries visible before scrolling (3-10)
  showMiniSummary: boolean; // Show today's total at bottom

  // Display preferences
  entryDisplayDensity: EntryDisplayDensity;
  timeFormat: TimeFormat;
  showSeconds: boolean; // Show seconds in time display

  // Panel state
  isPanelCollapsed: boolean; // User can collapse the panel section
  hasManuallyResized: boolean; // Track if user manually resized panel
  autoExpandEnabled: boolean; // Enable auto-expand when entries are added

  // Actions
  setRecentEntriesHeight: (height: number) => void;
  setVisibleEntries: (count: number) => void;
  setShowMiniSummary: (show: boolean) => void;
  setEntryDisplayDensity: (density: EntryDisplayDensity) => void;
  setTimeFormat: (format: TimeFormat) => void;
  setShowSeconds: (show: boolean) => void;
  togglePanelCollapsed: () => void;
  setHasManuallyResized: (value: boolean) => void;
  setAutoExpandEnabled: (value: boolean) => void;

  // Reset to defaults
  resetToDefaults: () => void;
}

const DEFAULT_STATE = {
  recentEntriesHeight: 0, // Start at 0px - fully closed, auto-expand when entries added
  visibleEntries: 5, // Show 5 entries
  showMiniSummary: true,
  entryDisplayDensity: 'normal' as EntryDisplayDensity,
  timeFormat: '24h' as TimeFormat,
  showSeconds: true,
  isPanelCollapsed: false,
  hasManuallyResized: false, // Track manual resize
  autoExpandEnabled: true, // Enable auto-expand by default
};

export const useTimeTrackingPanelStore = create<TimeTrackingPanelState>()(
  persist(
    (set) => ({
      // Initial state
      ...DEFAULT_STATE,

      // Actions
      setRecentEntriesHeight: (height) => {
        // Clamp between 0px and 400px
        const clampedHeight = Math.min(Math.max(height, 0), 400);
        set({ recentEntriesHeight: clampedHeight });
      },

      setVisibleEntries: (count) => {
        // Clamp between 3 and 10
        const clampedCount = Math.min(Math.max(count, 3), 10);
        set({ visibleEntries: clampedCount });
      },

      setShowMiniSummary: (show) => set({ showMiniSummary: show }),

      setEntryDisplayDensity: (density) => set({ entryDisplayDensity: density }),

      setTimeFormat: (format) => set({ timeFormat: format }),

      setShowSeconds: (show) => set({ showSeconds: show }),

      togglePanelCollapsed: () =>
        set((state) => ({ isPanelCollapsed: !state.isPanelCollapsed })),

      setHasManuallyResized: (value) => set({ hasManuallyResized: value }),

      setAutoExpandEnabled: (value) => set({ autoExpandEnabled: value }),

      resetToDefaults: () => set(DEFAULT_STATE),
    }),
    {
      name: 'time-tracking-panel-settings',
      storage: createJSONStorage(() => createSyncedStorage()),
    }
  )
);

/**
 * Toast Store
 *
 * Global toast notification system for user feedback
 * - Success, error, info, warning notifications
 * - Auto-dismiss with configurable duration
 * - Stack multiple toasts
 * - Accessible (aria-live regions)
 *
 * NOTE: This complements useUndoStore - use that for undo actions
 * Use this for general notifications without undo capability
 */

import { create } from 'zustand';
import { v4 as uuidv4 } from 'uuid';
import { logger } from '../services/logger';

const log = logger.module('ToastStore');

/**
 * Toast types for styling and icons
 */
export type ToastType = 'success' | 'error' | 'warning' | 'info';

/**
 * Toast notification
 */
export interface Toast {
  id: string;
  type: ToastType;
  message: string;
  description?: string; // Optional longer description
  duration: number; // Auto-dismiss duration in ms
  createdAt: number;
}

/**
 * Toast Store State
 */
interface ToastStore {
  // State
  toasts: Toast[];

  // Actions
  addToast: (
    type: ToastType,
    message: string,
    options?: { description?: string; duration?: number }
  ) => string;
  dismissToast: (id: string) => void;
  dismissAll: () => void;

  // Convenience methods
  success: (message: string, description?: string) => string;
  error: (message: string, description?: string) => string;
  warning: (message: string, description?: string) => string;
  info: (message: string, description?: string) => string;
}

/**
 * Default durations by toast type (ms)
 */
const DEFAULT_DURATIONS: Record<ToastType, number> = {
  success: 4000,
  info: 5000,
  warning: 6000,
  error: 8000, // Errors stay longer
};

/**
 * Maximum number of toasts to show at once
 */
const MAX_TOASTS = 5;

/**
 * Create the Toast store
 * NOTE: This store is NOT persisted - toasts are temporary
 */
export const useToastStore = create<ToastStore>((set, get) => ({
  // Initial state
  toasts: [],

  /**
   * Add a new toast notification
   * Returns the toast ID
   */
  addToast: (type, message, options = {}) => {
    const id = uuidv4();
    const duration = options.duration ?? DEFAULT_DURATIONS[type];

    const toast: Toast = {
      id,
      type,
      message,
      description: options.description,
      duration,
      createdAt: Date.now(),
    };

    set((state) => {
      // Keep only the most recent MAX_TOASTS
      const existingToasts = state.toasts.slice(-(MAX_TOASTS - 1));
      return {
        toasts: [...existingToasts, toast],
      };
    });

    // Auto-dismiss after duration
    setTimeout(() => {
      get().dismissToast(id);
    }, duration);

    log.debug('Toast added', { id, type, message });
    return id;
  },

  /**
   * Dismiss a specific toast
   */
  dismissToast: (id) => {
    set((state) => ({
      toasts: state.toasts.filter((toast) => toast.id !== id),
    }));
    log.debug('Toast dismissed', { id });
  },

  /**
   * Dismiss all toasts
   */
  dismissAll: () => {
    set({ toasts: [] });
    log.debug('All toasts dismissed');
  },

  // Convenience methods
  success: (message, description) => get().addToast('success', message, { description }),
  error: (message, description) => get().addToast('error', message, { description }),
  warning: (message, description) => get().addToast('warning', message, { description }),
  info: (message, description) => get().addToast('info', message, { description }),
}));

/**
 * Selector hooks for optimized re-renders
 */
export const useToasts = () => useToastStore((state) => state.toasts);
export const useHasToasts = () => useToastStore((state) => state.toasts.length > 0);

/**
 * Standalone toast function for use outside React components
 * Useful in services, stores, and async operations
 */
export const toast = {
  success: (message: string, description?: string) =>
    useToastStore.getState().success(message, description),
  error: (message: string, description?: string) =>
    useToastStore.getState().error(message, description),
  warning: (message: string, description?: string) =>
    useToastStore.getState().warning(message, description),
  info: (message: string, description?: string) =>
    useToastStore.getState().info(message, description),
  dismiss: (id: string) => useToastStore.getState().dismissToast(id),
  dismissAll: () => useToastStore.getState().dismissAll(),
};

