import from "@/lib/utils" { cn }

glob ALERT_BASE: str = "relative w-full rounded-lg border p-4 [&>svg~*]:pl-7 [&>svg+div]:translate-y-[-3px] [&>svg]:absolute [&>svg]:left-4 [&>svg]:top-4 [&>svg]:text-foreground";

glob ALERT_VARIANT_CLASSES: dict[str, str] = {
    "default": "bg-background text-foreground",
    "destructive": "border-destructive/50 text-destructive dark:border-destructive [&>svg]:text-destructive",
};

def alertVariants(variant: str | None = None) -> str {
    v = variant or "default";
    extra = ALERT_VARIANT_CLASSES.get(v, ALERT_VARIANT_CLASSES["default"]);
    return cn(ALERT_BASE, extra);
}

def:pub Alert(
    className: str | None = None,
    variant: str | None = None,
    ref: Ref[HTMLDivElement] = Ref(),
    props: dict[str, object] = {},
    children: object | None = None,
) -> JsxElement {
    <div ref={ref} role="alert" className={cn(alertVariants(variant=variant), className)} {**props}>{children}</div>
}

def:pub AlertTitle(
    className: str | None = None,
    ref: Ref[HTMLHeadingElement] = Ref(),
    props: dict[str, object] = {},
    children: object | None = None,
) -> JsxElement {
    <h5 ref={ref} className={cn("mb-1 font-medium leading-none tracking-tight", className)} {**props}>{children}</h5>
}

def:pub AlertDescription(
