import from "@radix-ui/react-slot" { Slot }
import from "lucide-react" { ChevronRight, MoreHorizontal }
import from "@/lib/utils" { cn }

def:pub Breadcrumb(
    ref: Ref[HTMLElement] = Ref(),
    props: dict[str, object] = {},
    children: object | None = None,
) -> JsxElement {
    <nav ref={ref} aria-label="breadcrumb" {**props}>{children}</nav>
}

def:pub BreadcrumbList(
    className: str | None = None,
    ref: Ref[HTMLOListElement] = Ref(),
    props: dict[str, object] = {},
    children: object | None = None,
) -> JsxElement {
    <ol
        ref={ref}
        className={cn("flex flex-wrap items-center gap-1.5 break-words text-sm text-muted-foreground sm:gap-2.5", className)}
        {**props}
    >{children}</ol>
}

def:pub BreadcrumbItem(
    className: str | None = None,
    ref: Ref[HTMLLIElement] = Ref(),
    props: dict[str, object] = {},
    children: object | None = None,
) -> JsxElement {
    <li ref={ref} className={cn("inline-flex items-center gap-1.5", className)} {**props}>{children}</li>
}

def:pub BreadcrumbLink(
    asChild: bool = False,
    className: str | None = None,
    ref: Ref[object] = Ref(),
    props: dict[str, object] = {},
    children: object | None = None,
) -> JsxElement {
    linkClass = cn("transition-colors hover:text-foreground", className);
    if asChild {
        return <Slot ref={ref} className={linkClass} {**props}>{children}</Slot>;
    }
    return <a ref={ref} className={linkClass} {**props}>{children}</a>;
}

def:pub BreadcrumbPage(
    className: str | None = None,
    ref: Ref[HTMLSpanElement] = Ref(),
    props: dict[str, object] = {},
    children: object | None = None,
) -> JsxElement {
    <span
        ref={ref}
        role="link"
        aria-disabled="true"
        aria-current="page"
        className={cn("font-normal text-foreground", className)}
        {**props}
    >{children}</span>
}

def:pub BreadcrumbSeparator(
    className: str | None = None,
    props: dict[str, object] = {},
    children: object | None = None,
) -> JsxElement {
    <li role="presentation" aria-hidden="true" className={cn("[&>svg]:size-3.5", className)} {**props}>
        {children if children is not None else <ChevronRight />}
    </li>
}

def:pub BreadcrumbEllipsis(
    className: str | None = None,
    props: dict[str, object] = {},
) -> JsxElement {
    <span
        role="presentation"
        aria-hidden="true"
        className={cn("flex h-9 w-9 items-center justify-center", className)}
        {**props}
    >
        <MoreHorizontal className="h-4 w-4" />
        <span className="sr-only">More</span>
    </span>
}

