// hooks/useContainerWidth.ts
import { useEffect, useRef, useState } from 'react';

export function useContainerWidth() {
    const containerRef = useRef<HTMLDivElement>(null);
    const [width, setWidth] = useState<number>(0);

    useEffect(() => {
        const container = containerRef.current;
        if (!container) return;

        const observer = new ResizeObserver((entries) => {
            setWidth(entries[0].contentRect.width);
        });

        observer.observe(container);
        return () => observer.disconnect();
    }, []);

    return { containerRef, width };
}

jac:
obj ResizeObserverLike {
    def observe(target: object) -> None;
    def disconnect() -> None;
}

def:pub useContainerWidth() -> dict {
    has containerRef: Ref[HTMLDivElement] = Ref();
    has width: float = 0;
    has observerRef: Ref[ResizeObserverLike | None] = Ref();

    def on_resize(entries: list) {
        width = (entries[0].contentRect.width as float);
    }

    can with entry {
        container = containerRef.current;
        if container {
            ro_cls = ResizeObserver as type[ResizeObserverLike];
            observer = new(ro_cls, on_resize);
            observerRef.current = observer;
            observer.observe(container);
        }
    }

    can with exit {
        observer = observerRef.current;
        if observer {
            observer.disconnect();
        }
    }

    return {"containerRef": containerRef, "width": width};
}

