import from "react-color-palette" { ColorPicker, useColor }
import "react-color-palette/css";

obj PaletteColor {
    has hex: str;
}

def:pub ColorSelector(color: str | None, setColor: Callable[[str], None], onClose: Callable[[], None]) -> JsxElement {
    colorTuple = useColor(color or "gray") as tuple[PaletteColor, Callable[[PaletteColor], None]];
    pickerColor = colorTuple[0];
    setPickerColor = colorTuple[1];
    return (
        <div className="modal">
            <div className="content">
                <ColorPicker hideInput={["rgb", "hsv"]} color={pickerColor} onChange={setPickerColor} />
                <button onClick={lambda () { setColor(pickerColor.hex); }}>Ok</button>
                <button onClick={onClose}>Cancel</button>
            </div>
        </div>
    );
}

