def compare(value: dict[str, object] | str | int | float | bool | None, other: dict[str, object] | str | int | float | bool | None) -> bool {
    if value is other {
        return True;
    }
    if isinstance(value, dict) and isinstance(other, dict) and len(value) == len(other) {
        for key_value in value {
            if not (key_value in other and value[key_value] == other[key_value]) {
                return False;
            }
        }
        return True;
    }
    return False;
}

