/**
 * A still of the journey: the path the cursor took, with a marker at every
 * click, on transparency. Cheap to produce and it drops straight onto a
 * screenshot in a slide.
 */

import { PERSONALITIES, type Traits } from './motion'
import type { Script } from './script'
import { buildTimeline } from './timeline'

export type PngOptions = {
  /** Output width in px. Defaults to the recorded viewport width. */
  width?: number
  color?: string
  traits?: Traits
  /** Multiplier for retina output. Defaults to the device pixel ratio. */
  pixelRatio?: number
  lineWidth?: number
}

const DEFAULT_COLOR = '#2f6bff'

export async function scriptToPathPng(script: Script, options: PngOptions = {}): Promise<Blob> {
  if (typeof document === 'undefined') {
    throw new Error('matinee: toPathPng() needs a browser')
  }

  const traits = options.traits ?? PERSONALITIES.confident
  const color = options.color ?? DEFAULT_COLOR
  const vw = script.viewport.w || 1200
  const vh = script.viewport.h || 630
  const width = options.width ?? vw
  const height = Math.round((width / vw) * vh)
  const dpr = options.pixelRatio ?? (typeof devicePixelRatio === 'number' ? devicePixelRatio : 1)

  const canvas = document.createElement('canvas')
  canvas.width = Math.round(width * dpr)
  canvas.height = Math.round(height * dpr)
  const ctx = canvas.getContext('2d')
  if (!ctx) throw new Error('matinee: could not get a 2d context')

  // Draw in recorded-viewport coordinates and let the transform handle both
  // the requested size and the pixel density.
  ctx.scale((width / vw) * dpr, (height / vh) * dpr)

  const tl = buildTimeline(script, traits, 60)

  ctx.lineJoin = 'round'
  ctx.lineCap = 'round'
  ctx.strokeStyle = color
  ctx.lineWidth = options.lineWidth ?? 2.5

  // Fade the tail in, so the path reads as having a direction.
  const n = tl.samples.length
  for (let i = 1; i < n; i++) {
    const a = tl.samples[i - 1]
    const b = tl.samples[i]
    if (!a || !b) continue
    ctx.globalAlpha = 0.12 + (i / n) * 0.68
    ctx.beginPath()
    ctx.moveTo(a.x, a.y)
    ctx.lineTo(b.x, b.y)
    ctx.stroke()
  }

  ctx.globalAlpha = 1
  for (const c of tl.clicks) {
    ctx.beginPath()
    ctx.arc(c.x, c.y, c.kind === 'dblclick' ? 13 : 10, 0, Math.PI * 2)
    ctx.strokeStyle = color
    ctx.lineWidth = 2
    ctx.stroke()

    ctx.beginPath()
    ctx.arc(c.x, c.y, 3.5, 0, Math.PI * 2)
    ctx.fillStyle = color
    ctx.fill()
  }

  return new Promise<Blob>((resolve, reject) => {
    canvas.toBlob((blob) => {
      if (blob) resolve(blob)
      else reject(new Error('matinee: canvas produced no blob'))
    }, 'image/png')
  })
}

/**
 * <Stage>: the two lines of integration.
 *
 * It renders its children completely untouched and mounts one fixed,
 * pointer-events:none, aria-hidden overlay beside them. It must never affect
 * layout, never intercept a click, and never appear to a screen reader.
 */

import {
  createContext,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
  type ReactNode,
} from 'react'
import { Actor, type Target } from './actor'
import { CursorLayer, type CursorGlyph } from './cursor'
import { scriptToPathPng, type PngOptions } from './export-png'
import { scriptToSvg, type SvgOptions } from './export-svg'
import { traitsFor, type PersonalityName, type Point } from './motion'
import type { Script } from './script'

export type Cursor = {
  moveTo(target: Target): Promise<void>
  click(target?: Target): Promise<void>
  dblclick(target?: Target): Promise<void>
  type(target: Target, text: string): Promise<void>
  scrollTo(target: Target): Promise<void>
  hover(target: Target, ms?: number): Promise<void>
  pause(ms?: number): Promise<void>
  say(text: string, ms?: number): Promise<void>
  show(): Promise<void>
  hide(): Promise<void>
  /** The performance so far, as plain data. */
  getScript(): Script
  clearScript(): void
  play(script: Script): Promise<void>
  /** Self-contained animated SVG of the recorded performance. */
  toSvg(options?: SvgOptions): string
  /** Static PNG of the path with click markers, on transparency. */
  toPathPng(options?: PngOptions): Promise<Blob>
  readonly position: Point
}

export type StageProps = {
  children?: ReactNode
  /** Nameplate riding with the cursor. `false` removes it. */
  label?: string | false
  color?: string
  cursor?: CursorGlyph
  personality?: PersonalityName
  /** `true` for the default length, or a number of dots. */
  trail?: boolean | number
  scale?: number
  zIndex?: number
  respectReducedMotion?: boolean
  onScriptChange?: (script: Script) => void
}

/** A blue that is confident without being a link. */
const DEFAULT_COLOR = '#2f6bff'

const StageContext = createContext<Cursor | null>(null)

export function Stage({
  children,
  label = 'Agent',
  color = DEFAULT_COLOR,
  cursor = 'pointer',
  personality = 'confident',
  trail = false,
  scale = 1,
  zIndex = 9999,
  respectReducedMotion = true,
  onScriptChange,
}: StageProps): ReactNode {
  const traits = useMemo(() => traitsFor(personality), [personality])

  // Read through a ref so a mid-performance OS toggle takes effect, and so
  // flipping the prop does not tear down the actor.
  const reducedRef = useRef(false)
  const respectRef = useRef(respectReducedMotion)
  respectRef.current = respectReducedMotion

  // The actor is created during render rather than in an effect: a child's
  // effect runs *before* its parent's, so an app that starts performing on
  // mount would otherwise find no actor there.
  const actorRef = useRef<Actor | null>(null)
  if (actorRef.current === null && typeof window !== 'undefined') {
    actorRef.current = new Actor({
      traits,
      reducedMotion: () => respectRef.current && reducedRef.current,
    })
  }
  const actor = actorRef.current

  const [mounted, setMounted] = useState(false)
  useEffect(() => {
    setMounted(true)
    return () => actorRef.current?.destroy()
  }, [])

  useEffect(() => {
    if (typeof window === 'undefined' || !window.matchMedia) return
    const mq = window.matchMedia('(prefers-reduced-motion: reduce)')
    reducedRef.current = mq.matches
    const onChange = (e: MediaQueryListEvent): void => {
      reducedRef.current = e.matches
    }
    mq.addEventListener('change', onChange)
    return () => mq.removeEventListener('change', onChange)
  }, [])

  useEffect(() => {
    actor?.setTraits(traits)
  }, [actor, traits])

  useEffect(() => {
    actor?.setHandlers({ onScriptChange })
  }, [actor, onScriptChange])

  // Read through refs so the handle keeps one identity for the life of the
  // Stage. Memoising on `traits`/`color` would hand out a new object every
  // time the personality changed, re-firing any consumer effect that depends
  // on the cursor, which for most apps means restarting the performance.
  const traitsRef = useRef(traits)
  traitsRef.current = traits
  const colorRef = useRef(color)
  colorRef.current = color

  const value = useMemo<Cursor>(() => makeCursor(actor, traitsRef, colorRef), [actor])

  return (
    <StageContext.Provider value={value}>
      {children}
      {mounted && actor && (
        <CursorLayer
          actor={actor}
          label={label}
          color={color}
          glyph={cursor}
          trail={trail}
          scale={scale}
          zIndex={zIndex}
        />
      )}
    </StageContext.Provider>
  )
}

export function useCursor(): Cursor {
  const ctx = useContext(StageContext)
  if (!ctx) {
    throw new Error('matinee: useCursor() must be called inside a <Stage>')
  }
  return ctx
}

/**
 * Wraps the actor in the public surface. On the server (and before mount)
 * every method is a resolved no-op, so an app that performs on load renders
 * identically in Node and never throws during SSR.
 */
function makeCursor(
  actor: Actor | null,
  traits: { current: ReturnType<typeof traitsFor> },
  color: { current: string },
): Cursor {
  const noop = (): Promise<void> => Promise.resolve()
  const emptyScript = (): Script => ({
    version: 1,
    viewport: { w: 0, h: 0 },
    seed: 1,
    origin: { x: 0, y: 0 },
    steps: [],
  })

  if (!actor) {
    return {
      moveTo: noop,
      click: noop,
      dblclick: noop,
      type: noop,
      scrollTo: noop,
      hover: noop,
      pause: noop,
      say: noop,
      show: noop,
      hide: noop,
      getScript: emptyScript,
      clearScript: () => {},
      play: noop,
      toSvg: () => '',
      toPathPng: () => Promise.resolve(new Blob()),
      get position() {
        return { x: 0, y: 0 }
      },
    }
  }

  return {
    moveTo: (t) => actor.moveTo(t),
    click: (t) => actor.click(t),
    dblclick: (t) => actor.dblclick(t),
    type: (t, text) => actor.type(t, text),
    scrollTo: (t) => actor.scrollTo(t),
    hover: (t, ms) => actor.hover(t, ms),
    pause: (ms) => actor.pause(ms),
    say: (text, ms) => actor.say(text, ms),
    show: () => actor.show(),
    hide: () => actor.hide(),
    getScript: () => actor.getScript(),
    clearScript: () => actor.clearScript(),
    play: (s) => actor.play(s),
    toSvg: (options) =>
      scriptToSvg(actor.getScript(), {
        traits: traits.current,
        color: color.current,
        ...options,
      }),
    toPathPng: (options) =>
      scriptToPathPng(actor.getScript(), {
        traits: traits.current,
        color: color.current,
        ...options,
      }),
    get position() {
      return { ...actor.position }
    },
  }
}

/**
 * Turns a recorded Script back into positions over time.
 *
 * Both exporters need this: the SVG turns it into keyframes, the PNG turns it
 * into a stroked path. It runs with no DOM, which is what lets `toSvg()` be
 * called from a test, a build script, or a browser without three code paths.
 *
 * The reconstruction is faithful rather than bit-identical. It re-rolls the
 * curve between the same recorded landing points using the script's seed, so
 * the arcs are of the same character as the ones on screen without being the
 * exact same arcs. At 24fps over a nine-second clip nobody can tell, and the
 * alternative is storing thousands of sampled points in every script.
 */

import {
  buildPath,
  createRng,
  distanceBetween,
  driftAt,
  sampleMotion,
  travelDuration,
  type Point,
  type Traits,
} from './motion'
import { isPoint, type Script, type Step } from './script'

export type TimelineSample = { t: number; x: number; y: number }
export type TimelineClick = { t: number; x: number; y: number; kind: 'click' | 'dblclick' }

export type Timeline = {
  samples: TimelineSample[]
  clicks: TimelineClick[]
  /** Total length in ms, including a tail so a loop does not snap. */
  duration: number
}

const DEFAULT_FPS = 24
/** Below this, two consecutive samples are the same pixel to the eye. */
const MERGE_EPSILON = 0.4
/** A beat of stillness at the end so the loop reads as deliberate. */
const TAIL_MS = 700

export function buildTimeline(script: Script, traits: Traits, fps = DEFAULT_FPS): Timeline {
  const rng = createRng(script.seed)
  const step = 1000 / fps
  const samples: TimelineSample[] = []
  const clicks: TimelineClick[] = []

  let pos: Point = { ...script.origin }
  let time = 0

  const emit = (t: number, p: Point): void => {
    samples.push({ t, x: p.x, y: p.y })
  }

  const hold = (from: number, ms: number): void => {
    if (ms <= 0) return
    for (let t = from; t < from + ms; t += step) emit(t, pos)
  }

  /** Drift in place: what `pause` and `say` look like. */
  const wander = (from: number, ms: number): void => {
    if (ms <= 0) return
    const anchor = { ...pos }
    const phase = rng() * 100
    for (let t = from; t < from + ms; t += step) {
      const d = driftAt(t - from, traits, phase)
      emit(t, { x: anchor.x + d.x, y: anchor.y + d.y })
    }
    pos = anchor
  }

  /**
   * Travel, then stand still for whatever is left of the step's budget: the
   * hesitation, the click, the typing all happen without the cursor moving.
   */
  const travel = (from: number, to: Point, budget: number): number => {
    const dist = distanceBetween(pos, to)
    if (dist < 0.5) {
      hold(from, budget)
      pos = { ...to }
      return budget
    }
    const path = buildPath(pos, to, traits, rng)
    const dur = Math.min(travelDuration(dist, traits), Math.max(budget, 1))
    const phase = rng() * 100
    for (let t = from; t < from + dur; t += step) {
      emit(t, sampleMotion(path, (t - from) / dur, traits, phase))
    }
    pos = { ...to }
    emit(from + dur, pos)
    hold(from + dur, budget - dur)
    return dur
  }

  emit(0, pos)

  for (const s of script.steps) {
    // Dead air between steps is part of the rhythm; keep it.
    if (s.at > time) {
      hold(time, s.at - time)
      time = s.at
    }

    const target = targetPoint(s)

    switch (s.action) {
      case 'move':
      case 'hover': {
        if (target) travel(time, target, s.duration)
        else hold(time, s.duration)
        break
      }
      case 'click':
      case 'dblclick': {
        const travelled = target ? travel(time, target, s.duration) : (hold(time, s.duration), 0)
        // The press lands after the travel and the hesitation.
        clicks.push({
          t: time + travelled + traits.hesitation,
          x: pos.x,
          y: pos.y,
          kind: s.action,
        })
        break
      }
      case 'type': {
        if (target) {
          const travelled = travel(time, target, s.duration)
          clicks.push({ t: time + travelled + traits.hesitation, x: pos.x, y: pos.y, kind: 'click' })
        } else {
          hold(time, s.duration)
        }
        break
      }
      case 'scroll': {
        // The page moves, not the cursor, but it bobs, the way a hand resting
        // on a trackpad mid-swipe does.
        const anchor = { ...pos }
        for (let t = time; t < time + s.duration; t += step) {
          const p = (t - time) / Math.max(s.duration, 1)
          emit(t, { x: anchor.x + Math.sin(p * Math.PI) * 6, y: anchor.y + Math.sin(p * Math.PI) * 14 })
        }
        pos = anchor
        break
      }
      case 'pause':
      case 'say': {
        wander(time, s.duration)
        break
      }
      case 'show':
      case 'hide':
        break
    }

    time = s.at + s.duration
  }

  hold(time, TAIL_MS)
  emit(time + TAIL_MS, pos)

  return { samples: compress(samples), clicks, duration: Math.max(time + TAIL_MS, 1) }
}

function targetPoint(s: Step): Point | null {
  if (s.point) return s.point
  if (s.target !== undefined && isPoint(s.target)) return s.target
  return null
}

/**
 * Drops samples that sit inside a stationary run. A twelve-second performance
 * is mostly holding still; without this the keyframe block is several times
 * larger for no visible difference.
 */
function compress(samples: TimelineSample[]): TimelineSample[] {
  if (samples.length < 3) return samples
  const out: TimelineSample[] = [samples[0] as TimelineSample]

  for (let i = 1; i < samples.length - 1; i++) {
    const prev = out[out.length - 1] as TimelineSample
    const cur = samples[i] as TimelineSample
    const next = samples[i + 1] as TimelineSample
    const stillBehind = Math.hypot(cur.x - prev.x, cur.y - prev.y) < MERGE_EPSILON
    const stillAhead = Math.hypot(next.x - cur.x, next.y - cur.y) < MERGE_EPSILON
    if (stillBehind && stillAhead) continue
    out.push(cur)
  }

  out.push(samples[samples.length - 1] as TimelineSample)
  return out
}

