      unobserve: jest.fn(),
      root: null,
      rootMargin: "",
      thresholds: [],
      disconnect: jest.fn(),
      takeRecords: jest.fn(),
    }));

    render(<OnScreenExample />);
    const p = screen.getByText(/Intersecting/i);

    // Element is not intersecting in test
    expect(p).toHaveTextContent("Intersecting: false");

    // Observing should have begun
    expect(observe).toHaveBeenCalled();
  });
});

