import React, { ChangeEvent, useContext, useEffect } from "react"
import {
  createReactive,
  createSubscription,
  ISubscription,
  useReactive,
  useReducerSubscription,
  useSubscription,
  useSyncStore,
} from "../src/index"
import { createRoot } from "react-dom/client"

const counterSubscription = createSubscription({ count: 0, foo: 10 })

const useCounter = () => {
  let { state, subscription } = useSyncStore(counterSubscription)
  const increment = () => subscription.updateState({ count: state.count + 1 })
  const decrement = () => subscription.updateState({ count: state.count - 1 })
  return { count: state.count, increment, decrement }
}

function CounterDisplay() {
  let { count, increment, decrement } = useCounter()
  return (
    <div>
      <button onClick={decrement}>-</button>
      <span>{count}</span>
      <button onClick={increment}>+</button>
    </div>
  )
}
