  if (typeof raw.model === 'string') result.model = raw.model;
  if (raw.confirm_required === true) {
    result.confirm_required = true;
    if (typeof raw.confirm_message === 'string') result.confirm_message = raw.confirm_message;
  }
  return result;
}

