glob prefixCls = "fam-badge";

obj:pub BadgeProps {
    has className: str | None = None;
    has style: dict[str, object] | None = None;
    has overflowCount: int | None = None;
    has corner: bool | None = None;
    has dot: bool | None = None;
    has text: str | int | None = None;
}

def:pub Badge(
    className: str | None = None,
    style: dict[str, object] | None = None,
    overflowCount: int = 99,
    corner: bool = False,
    dot: bool = False,
    text: str | int | None = None,
    children: object | None = None,
    props: dict[str, object] | None = None,
) -> JsxElement {
    rest = props if props is not None else {};
    if style is not None {
        rest = {**rest, "style": style};
    }
    display_text: str | int | None = text;
    if isinstance(display_text, int) and display_text > overflowCount {
        display_text = f"{overflowCount}+";
    }
    if dot {
        display_text = "";
    }
    scrollNumberCls = classnames({
        f"{prefixCls}-dot": dot,
        f"{prefixCls}-text": not dot and not corner,
        f"{prefixCls}-corner": corner,
    });
    badgeCls = classnames(prefixCls, className, {
        f"{prefixCls}-not-a-wrapper": not children,
        f"{prefixCls}-a-wrapper": bool(children),
        f"{prefixCls}-corner-wrapper": corner,
    });
    <div className={badgeCls}>
        {children}
        {if display_text or dot {
            <div className={scrollNumberCls} {**rest}>{display_text}</div>
        }}
    </div>
}

