def:pub Collapse(
    className: str | None = None,
    style: dict[str, object] | None = None,
    accordion: bool = False,
    bordered: bool = True,
    onChange: Callable[[list[str | int]], None] | None = None,
    activeKeys: list[str | int] | None = None,
    defaultActiveKey: list[str | int] | str | int | None = None,
    expandIcon: object | None = None,
    children: object | None = None,
    props: dict[str, object] | None = None,
) -> JsxElement {
    has activeKeysState: list[str | int] = [];
    rest = props if props is not None else {};
    can with entry {
        init_keys: list[str | int] = [];
        if activeKeys is not None {
            if accordion {
                init_keys = [activeKeys[0]];
            } else {
                init_keys = [k for k in activeKeys if k];
            }
        }
        activeKeysState = init_keys;
    }
    def handleActiveKeyChange(k: str) {
        keys = activeKeysState;
        if accordion {
            keys = [k];
        } elif k not in keys {
            keys = keys + [k];
        }
        activeKeysState = keys;
        if onChange {
            onChange(keys);
        }
    }
    def map_child(child: object) -> object {
        child_key = getattr(child, "key", None);
        return cloneElement(child, {"callback": handleActiveKeyChange, "fkey": child_key, "activeKeys": activeKeysState, "accordion": accordion, "expandIcon": expandIcon});
    }
    wrapCls = classnames(prefixCls, className, {f"{prefixCls}-bordered": bordered});
    rendered = Children.map(children, map_child);
    <div className={wrapCls} style={style if style is not None else {}} {**rest}>
        {rendered}
