      </Box>

      <Modal
        isOpen={isOpen}
        close={closeModal}
        header="Awesome Modal Title"
        footer={renderFooter()}
      >
        <Text>Are you sure you want to delete your account?</Text>
      </Modal>
    </>
  );
};

