    percent: int | float = 0,
    unfilled: bool = True,
    inactive: bool = False,
    info: bool = False,
    sliderWidth: int | float = 2,
    textColor: str = "#000",
    sliderColor: str | None = None,
    style: dict[str, object] | None = None,
    barStyle: dict[str, object] | None = None,
) -> JsxElement {
    inactiveColor = "#CCC";
