    has animate: bool | None = None;
    has title: bool | None = None;
    has avatar: bool | None = None;
    has row: int | None = None;
    has rowWidth: str | int | None = None;
    has round: bool | None = None;
    has titleWidth: str | int | None = None;
    has avatarSize: int | None = None;
    has avatarShape: str | None = None;
    has loops: int | None = None;
    has onClick: Callable[[], None] | None = None;
}

def:pub Skeleton(
    className: str | None = None,
    style: dict[str, object] | None = None,
    loading: bool = True,
    animate: bool = True,
    title: bool = False,
    avatar: bool = False,
    row: int = 0,
    rowWidth: str | int = "100%",
    round: bool = False,
    titleWidth: str | int = "40%",
    avatarSize: int = 32,
    avatarShape: str = "round",
    loops: int = 1,
    children: object | None = None,
    onClick: Callable[[], None] | None = None,
) -> JsxElement {
    if not loading {
        return <>{children}</>;
    }
    wrapCls = classnames(prefixCls, className, {f"{prefixCls}-animate": animate, f"{prefixCls}-round": round});
    avatarWrapCls = classnames(f"{prefixCls}-avatar", {f"{prefixCls}-shape--{avatarShape}": avatarShape});
    rows = [0 for _ in range(row)];
    entries = [0 for _ in range(loops)];
    def handleClick() {
        if onClick {
            onClick();
        }
    }
    <>
        {for (i, _) in enumerate(entries) {
            entryStyle = {**({"marginTop": 30} if i > 0 else {}), **(style if style is not None else {})};
            <div key={str(i)} className={wrapCls} style={entryStyle} onClick={handleClick}>
                {if avatar {
                    <div className={avatarWrapCls} style={{"width": avatarSize, "height": avatarSize}} />
                }}
                <div className={f"{prefixCls}-content"}>
                    {if title {
                        <div className={f"{prefixCls}-title"} style={{"width": titleWidth}} />
                    }}
                    {for (_, rowIdx) in enumerate(rows) {
                        <div key={str(rowIdx)} className={f"{prefixCls}-row"} style={{"width": rowWidth}} />
                    }}
                </div>
            </div>
        }}
    </>
}

