    (copied_value, set_copied_value) = useState(None);
    (error, set_error) = useState(None);
    clipboard_api = ClipboardApi(service=DefaultClipboardService());

    async def copy(value: str) -> bool {
        try {
            await clipboard_api.copy(value);
            set_copied_value(value);
            set_error(None);
            return True;
        } except Exception as err {
            console.error("Failed to Copy", err);
            set_error(str(err));
            set_copied_value(None);
            return False;
        }
    }

    return (copied_value, copy, error);
