        <span className="hm-thinking__title">Thinking</span>
        {streaming && <span className="hm-thinking__spinner" aria-label="thinking" />}
      </button>
      {open && (
        <pre className="hm-thinking__body">
          <code>{text}</code>
        </pre>
      )}
    </div>
  );
}

