                <TextInput
                    label="Author"
                    id="author"
                    placeholder="Lewis Carroll"
                    value={author}
                    setter={setAuthor}
                    maxLength={50}
                    required={generationFormat == "commands"}
                />
            </div>
            <div className="w-full sm:w-1/2 px-2">
                <TextInput
                    label="Title"
                    id="title"
                    placeholder="Alice in Wonderland"
                    value={title}
                    setter={setTitle}
                    maxLength={15}
                    required={generationFormat == "commands"}
                />
            </div>
        </div>
        <div className="mb-4">
            <div className={classNames({"hidden": inputFormat == "text"})}>
                <FileUpload
                    label="Text"
                    callback={lambda (txt: str) { setText(txt); }}
                    useFileUpload={inputFormat == "file"}
                />
            </div>
            <div className={classNames({"hidden": inputFormat == "file"})}>
                <TextArea
                    label="Text"
                    id="text"
                    placeholder="Once upon a time, there was a girl..."
                    value={text}
                    setter={setText}
                    required={inputFormat == "text"}
                />
                <span className="text-gray-500 text-sm">
                    {str(len(text))}{" characters, "}{str(word_count)}{" words"}
                </span>
            </div>
        </div>
        <button
            type="submit"
            className="w-full h-10 bg-blue-500 hover:bg-blue-600 text-white font-bold py-2 px-4 rounded focus:outline-none focus:shadow-outline"
            disabled={loading}
        >
            <ButtonTitle />
        </button>
    </form>
}

