import { ROOT_DATA } from '../../root/vars';

interface HorizontalSidePosition {
  top: number;
  left: number;
  transformOrigin: string;
}

export function getHorizontalSidePosition(
  targetEl: HTMLElement,
  popupSize: { width: number; height: number },
  config: {
    placement: 'right' | 'left';
    gap?: number;
    inWindow?: number | false;
  },
): HorizontalSidePosition {
  const { width, height } = popupSize;
  const { placement, gap = 10, inWindow = false } = config;

  const targetRect = targetEl.getBoundingClientRect();

  let top = targetRect.top;
  if (inWindow !== false) {
    top = Math.min(Math.max(top, inWindow), ROOT_DATA.windowSize.height - height - inWindow);
  }
  let left = placement === 'right' ? targetRect.left + targetRect.width + gap : targetRect.left - width - gap;
  if (inWindow !== false) {
    left = Math.min(Math.max(left, inWindow), ROOT_DATA.windowSize.width - width - inWindow);
  }

  const transformOrigin =
    placement === 'right'
      ? `left ${Math.min(targetRect.top - top + targetRect.height / 2, height)}px`
      : `right ${Math.min(targetRect.top - top + targetRect.height / 2, height)}px`;

  return {
    top,
    left,
    transformOrigin,
  };
}

jac:
import from libs.components.src.root.vars { ROOT_DATA }

obj:pub HorizontalSidePosition {
    has top: float;
    has left: float;
    has transformOrigin: str;
}

obj PopupSize {
    has width: float;
    has height: float;
}

obj HorizontalSideConfig {
    has placement: str;
    has gap: float = 10;
    has inWindow: float | bool = False;
}

def:pub getHorizontalSidePosition(
    targetEl: HTMLElement,
    popupSize: PopupSize,
    config: HorizontalSideConfig
) -> HorizontalSidePosition {
    width = popupSize.width;
    height = popupSize.height;
    placement = config.placement;
    gap = config.gap;
    inWindow = config.inWindow;

    targetRect = targetEl.getBoundingClientRect();

    top = targetRect.top;
    if inWindow is not False {
        margin = inWindow as float;
        top = min(max(top, margin), ROOT_DATA.windowSize.height - height - margin);
    }
    if placement == "right" {
        left = targetRect.left + targetRect.width + gap;
    } else {
        left = targetRect.left - width - gap;
    }
    if inWindow is not False {
        margin = inWindow as float;
        left = min(max(left, margin), ROOT_DATA.windowSize.width - width - margin);
    }

    centerY = min(targetRect.top - top + targetRect.height / 2, height);
    if placement == "right" {
        transformOrigin = f"left {centerY}px";
    } else {
        transformOrigin = f"right {centerY}px";
    }

    return HorizontalSidePosition(top=top, left=left, transformOrigin=transformOrigin);
}

