def:pub isDeepEqual(value1: object, value2: object) -> bool {
    if type(value1) != type(value2) {
        return False;
    }
    if isinstance(value1, list) and isinstance(value2, list) {
        if len(value1) != len(value2) {
            return False;
        }
        for i in range(len(value1)) {
            if not isDeepEqual(value1[i], value2[i]) {
                return False;
            }
        }
        return True;
    }
    if isinstance(value1, dict) and isinstance(value2, dict) {
        keys1 = list(value1.keys());
        keys2 = list(value2.keys());
        if len(keys1) != len(keys2) {
            return False;
        }
        for key in keys1 {
            if key not in value2 {
                return False;
            }
            if not isDeepEqual(value1[key], value2[key]) {
                return False;
            }
        }
        return True;
    }
    return value1 == value2;
}

def:pub isSubset(array: list[object], subObject: object) -> bool {
    if isinstance(array, list) or subObject is not None {
        if subObject in array {
            return True;
        }
    }
    for i in range(len(array)) {
        if isDeepEqual(array[i], subObject) {
            return True;
        }
    }
    return False;
}

