import math;
import re;
import time;

type SpawnStatus = str;
type StreamKind = str;

obj StreamEntry {
    has at: int;
    has kind: StreamKind;
    has text: str;
    has isError: bool = False;
}

obj SpawnedAgent {
    has id: str;
    has parentId: str | None;
    has sessionId: str;
    has goal: str;
    has status: SpawnStatus;
    has taskIndex: int;
    has taskCount: int;
    has startedAt: int;
    has updatedAt: int;
    has filesRead: list[str] = [];
    has filesWritten: list[str] = [];
    has stream: list[StreamEntry] = [];
    has model: str | None = None;
    has durationSeconds: float | None = None;
    has inputTokens: float | None = None;
    has outputTokens: float | None = None;
    has costUsd: float | None = None;
    has toolCount: float | None = None;
}

obj SpawnNode {
    has id: str;
    has parentId: str | None;
    has sessionId: str;
    has goal: str;
    has status: SpawnStatus;
    has taskIndex: int;
    has taskCount: int;
    has startedAt: int;
    has updatedAt: int;
    has filesRead: list[str] = [];
    has filesWritten: list[str] = [];
    has stream: list[StreamEntry] = [];
    has children: list[SpawnNode] = [];
    has model: str | None = None;
    has durationSeconds: float | None = None;
    has inputTokens: float | None = None;
    has outputTokens: float | None = None;
    has costUsd: float | None = None;
    has toolCount: float | None = None;
}

glob TERMINAL: set[str] = {"completed", "failed", "interrupted"};
glob MAX_STREAM: int = 24;

def asStr(v: object | None) -> str {
    return v if isinstance(v, str) else "";
}

def asNum(v: object | None) -> float | None {
    if isinstance(v, (int, float)) and math.isfinite(v) {
        return v;
    }
    return None;
}

def asStrList(v: object | None) -> list[str] {
    if isinstance(v, list) {
        return [x for x in v if isinstance(x, str)];
    }
    return [];
}

def asStatus(v: object | None) -> SpawnStatus {
    if v == "completed" or v == "failed" or v == "interrupted" or v == "queued" {
        return v as SpawnStatus;
    }
    return "running";
}

def compact(text: str, max_len: int = 220) -> str {
    line = re.sub(r"\s+", " ", text).strip();
    if len(line) > max_len {
        return line[:max_len - 1] + "…";
    }
    return line;
}

def agentIdFromPayload(p: dict[str, object]) -> str {
    subagent = asStr(p.get("subagent_id"));
    if subagent {
        return subagent;
    }
    parent = asStr(p.get("parent_id")) or "root";
    task_idx = asNum(p.get("task_index"));
    task_idx_str = str(int(task_idx)) if task_idx is not None else "0";
    goal = asStr(p.get("goal"));
    return f"{parent}:{task_idx_str}:{goal}";
}

def agentFromPayload(p: dict[str, object], sessionId: str) -> SpawnedAgent {
    id = agentIdFromPayload(p);
    status = asStatus(p.get("status"));
    toolName = asStr(p.get("tool_name"));
    toolPreview = asStr(p.get("tool_preview")) or asStr(p.get("text"));
    text = compact(asStr(p.get("text")) or toolPreview);
    stream: list[StreamEntry] = [];
    if toolName and status not in TERMINAL {
        snippet = compact(toolPreview, 96) if toolPreview else "";
        words = [w for w in toolName.split("_") if w];
        label = " ".join([w[0].upper() + w[1:] for w in words]);
        stream_text = f"{label}(\"{snippet}\")" if snippet else label;
        stream.append(StreamEntry(at=int(time.time() * 1000), kind="tool", text=stream_text));
    } elif text {
        stream.append(StreamEntry(at=int(time.time() * 1000), kind="progress", text=text));
    }
    parent_raw = asStr(p.get("parent_id"));
    parent_id: str | None = parent_raw if parent_raw else None;
    task_idx = asNum(p.get("task_index"));
    task_count = asNum(p.get("task_count"));
    started = asNum(p.get("started_at"));
    updated = asNum(p.get("updated_at"));
    model_val = asStr(p.get("model"));
    duration = asNum(p.get("duration_seconds"));
    input_tokens = asNum(p.get("input_tokens"));
    output_tokens = asNum(p.get("output_tokens"));
    cost = asNum(p.get("cost_usd"));
    tool_count = asNum(p.get("tool_count"));
    now_ms = int(time.time() * 1000);
    return SpawnedAgent(
        id=id,
        parentId=parent_id,
        sessionId=sessionId,
        goal=asStr(p.get("goal")) or "Task",
        status=status,
        taskIndex=int(task_idx) if task_idx is not None else 0,
        taskCount=int(task_count) if task_count is not None else 1,
        startedAt=int(started) if started is not None else now_ms,
        updatedAt=int(updated) if updated is not None else now_ms,
        filesRead=asStrList(p.get("files_read")),
        filesWritten=asStrList(p.get("files_written")),
        stream=stream,
        model=model_val if model_val else None,
        durationSeconds=duration,
        inputTokens=input_tokens,
        outputTokens=output_tokens,
        costUsd=cost,
        toolCount=tool_count,
    );
}

def buildSpawnTree(agents: list[SpawnedAgent]) -> list[SpawnNode] {
    node_map: dict[str, SpawnNode] = {};
    for a in agents {
        node_map[a.id] = SpawnNode(
            id=a.id,
            parentId=a.parentId,
            sessionId=a.sessionId,
            goal=a.goal,
            status=a.status,
            taskIndex=a.taskIndex,
            taskCount=a.taskCount,
            startedAt=a.startedAt,
            updatedAt=a.updatedAt,
            filesRead=a.filesRead,
            filesWritten=a.filesWritten,
            stream=a.stream,
            children=[],
            model=a.model,
            durationSeconds=a.durationSeconds,
            inputTokens=a.inputTokens,
            outputTokens=a.outputTokens,
            costUsd=a.costUsd,
            toolCount=a.toolCount,
        );
    }
    roots: list[SpawnNode] = [];
    for node in node_map.values() {
        if node.parentId and node.parentId in node_map {
            node_map[node.parentId].children.append(node);
        } else {
            roots.append(node);
        }
    }
    return roots;
}

