import { isNumber, isUndefined } from 'lodash';
import { use, useRef } from 'react';

import { mergeCS } from '../../utils';
import { TableContext, type CLASSES } from '../vars';

const ZINDEX_CONFIG = {
  top: 5,
  right: 2,
  bottom: 5,
  left: 2,
