  let fixedRight = false;
  let fixedStyle = {};
  if (fixed) {
    fixedStyle = {
      ...fixed,
      position: 'sticky',
      zIndex:
        (tag === 'th' ? 1 : 0) +
        Object.keys(fixed).reduce((previous, current) => previous + ZINDEX_CONFIG[current as keyof typeof ZINDEX_CONFIG], 0),
