import React, { Fragment } from 'react'
import classnames from 'classnames'
import Popup from '../popup'

const prefixCls = 'fam-number-keyboard'

export interface NumberKeyboardProps {
  className?: string
  style?: object
  type?: 'professional' | 'simple'
  defaultValues?: Array<number | string>
  disorder?: boolean
  isHideConfirm?: boolean
  okText?: string
  header?: React.ReactNode
  maxLength?: number
  textRender?: (e?: any) => void
  onDelete?: (e?: any) => void
  onConfirm?: (e?: any) => void
  onChange?: (e?: any) => void
  maskClosable?: boolean
  overlay?: boolean
  transparent?: boolean
}

const NumberKeyboard = (props: NumberKeyboardProps) => {

  const {
    className,
    type = 'professional', // professional、simple
    defaultValues = [],
    disorder = false,
    isHideConfirm = true,
    okText = '确认',
    header,
    maxLength,
    textRender,
    onConfirm,
    onDelete,
    onChange,
    maskClosable = true,
    overlay = true,
    transparent = false,
  } = props

  let res: any
  let selectedValues: any = [...defaultValues] // 已选中的值

  // 加工数字序列
  const baseSpecialStr: any = textRender ? textRender('.') : '.'
  const baseStack = [1, 2, 3, 4, 5, 6, 7, 8, 9, 0]
  const baseStackTmp = [...baseStack]

  const keyNumberList: any = baseStack.map(item => {
    const val = disorder ? baseStackTmp.splice(parseInt((Math.random() * baseStackTmp.length).toString()), 1)[0] || 0 : item
    return textRender ? textRender(val) : val
  })

  // 删除
  const handleDelete = () => {

    let lastValue = selectedValues[selectedValues.length - 1]

    selectedValues.pop()

    if (onChange) {
      onChange({removeValue: lastValue, values: selectedValues})
    }

    if (onDelete) {
      onDelete({removeValue: lastValue, values: selectedValues})
    }

  }

  // 确认
  const handleConfirm = () => {

    if (onChange) {
      onChange({ values: selectedValues })
    }

    if (onConfirm) {
      onConfirm({ values: selectedValues })
    }

    if (isHideConfirm) {
      handleClosePopup()
    }

  }

  // 选择值
  const handleSelectedValues = (val: any) => {

    if (val || val === 0) {

      if (maxLength && maxLength > 0 && selectedValues.length >= maxLength) {
        return false
      }

      selectedValues.push(val)

      if (onChange) {
        onChange({addValue: val, values: selectedValues })
      }

    }

  }

  const handleClosePopup = () => {
    if (res) {
      res.close()
    }
  }

  const wrapCls = classnames(prefixCls, className)

  res = Popup({
    maskClosable,
    overlay,
    transparent,
    children: (
      <Fragment>
        {
          header && <div className={`${prefixCls}-header`}>{header}</div>
        }
        <div className={wrapCls}>
          <div className={`${prefixCls}-number`}>
            <ul className={`${prefixCls}-list`}>
              {
                keyNumberList.map((val: any, i: number) => {
                  if (i > 8) return false
                  return (
                    <li key={i} className={`${prefixCls}-item`} onClick={() => handleSelectedValues(val)}>
                      <span>{val}</span>
                    </li>
                  )
                })
              }
              {
                type === 'simple' ?
                  <li className={`${prefixCls}-item ${prefixCls}-disabled`}></li>
                :
                  <li className={`${prefixCls}-item`} onClick={() => handleSelectedValues(baseSpecialStr)}>{baseSpecialStr}</li>
              }
              <li className={`${prefixCls}-item`} onClick={() => handleSelectedValues(keyNumberList[9])}>{keyNumberList[9]}</li>
              <li className={`${prefixCls}-item ${prefixCls}-slidedown`} onClick={handleConfirm}></li>
            </ul>
          </div>
          <div className={`${prefixCls}-operate`}>
            <ul className={`${prefixCls}-operate-list`}>
              <li className={`${prefixCls}-operate-item ${prefixCls}-delete`} onClick={handleDelete}></li>
              <li className={`${prefixCls}-operate-item ${prefixCls}-confirm`} onClick={handleConfirm}>{okText}</li>
            </ul>
          </div>
        </div>
      </Fragment>
    ),
  })

  return {...res}
}

export default NumberKeyboard

import React, { useState, Fragment } from 'react'
import classnames from 'classnames'
import { NumberKeyboardProps } from '../number-keyboard'
import NumberKeyboard from '../number-keyboard'

const prefixCls = 'fam-password-input'

export interface PasswordInputProps extends NumberKeyboardProps {
  className?: string
  defaultValues?: Array<number | string>
  maxLength?: number
  gutter?: string | number
  mask?: boolean
  focused?: boolean
  autofocus?: boolean
  autoClose?: boolean
  closable?: boolean
  underline?: boolean
  onClose?: () => void
}

const PasswordInput: React.FC<PasswordInputProps> = props => {

  const {
    className,
    type,
    defaultValues = [],
    maxLength = 6,
    gutter = 15,
    mask = true,
    focused = false,
    autofocus = false,
    // closable = true,
    underline = false,
    autoClose = true,
    overlay = true, // 以下为数字键盘属性
    maskClosable = false,
    transparent = true,
    onChange,
    ...restProps
  } = props

  const thisRef = React.createRef()

  const [nodeRef] = useState<any>(thisRef)
  const [currentValues, setCurrentValues] = useState([...defaultValues])
  const [isFocus, setIsFocus] = useState(focused || autofocus)

  const wrapCls = classnames(prefixCls, className)
  const itemCls = classnames({
    [`${prefixCls}-item`]: !underline,
    [`${prefixCls}-underline-item`]: underline,
  })

  let res: any
  let rows = new Array(maxLength).fill(0)

  // 变更情况
  const handleChange = (e: any) => {

    let currentValuesTmp = [...e.values]
    setCurrentValues(currentValuesTmp)

    // 字符到达指定长度自动关闭数字键盘
    if (res && res.close && autoClose && maxLength > 0 && currentValuesTmp.length >= maxLength) {
      res.close()
    }

    if (onChange) {
      onChange({ values: currentValuesTmp })
    }

  }

  const handleDelete = (e: any) => {
    setCurrentValues([...e.values])
  }

  const handleConfirm = (e: any) => {
    setIsFocus(false)
  }

  // 点击可输入区域
  const handleClickItem = (e: any) => {

    setIsFocus(true)

    if (!res || (res && !res.close)) {
      // 返回的是Popup的内容
      res = NumberKeyboard(
        {
          ...restProps,
          type,
          defaultValues: [...currentValues],
          maxLength,
          maskClosable,
          transparent,
          overlay,
          onDelete: handleDelete,
          onConfirm: handleConfirm,
          onChange: handleChange
        }
      )

    }

  }

  // 光标
  let focusIndexTmp = currentValues.length

  if (focusIndexTmp < 1) focusIndexTmp = 0

  return (
    <Fragment>
      <div className={wrapCls} ref={nodeRef}>
        <ul className={`${prefixCls}-list`}>
          {
            rows.map((v, i) => {

              let hasValue = currentValues[i]

              if (hasValue === 0) hasValue = '0'

              let valueDOM = (hasValue && mask) ? <i className={`${prefixCls}-maskicon`} /> : (hasValue || '')

              let marginLeftTmp: any = 0

              if (gutter && i > 0 && i < maxLength) {
                marginLeftTmp = gutter
              }

              return (
                <li
                  key={i}
                  className={itemCls}
                  style={{marginLeft: marginLeftTmp}}
                  onClick={() => handleClickItem(i)}
                >
                  { valueDOM }
                  {
                    isFocus && focusIndexTmp === i && <div className={`${prefixCls}-focus`}/>
                  }
                </li>
              )
            })
          }
        </ul>
      </div>
    </Fragment>
  )
}

export default PasswordInput

import React from 'react'
import * as ReactDOM from 'react-dom'
import classnames from 'classnames'
import Icon from '../icon'

const prefixCls = 'fam-popup'
export interface StyleType {
  minHeight?: React.CSSProperties
}

export interface PopupProps {
  position?: 'top' | 'bottom' | 'left' | 'right'
  className?: string
  maskClosable?: boolean
  closable?: boolean
  overlay?: boolean
  transparent?: boolean
  visible?: boolean
  children?: React.ReactNode
  style?: React.CSSProperties
  radius?: any
  onClose?: (e?: any) => void
}

const rxTwoCNChar = /^[\u4e00-\u9fa5]{2}$/
const isTwoCNChar = rxTwoCNChar.test.bind(rxTwoCNChar)
function isString(str: any) {
  return typeof str === 'string'
}

// Insert one space between two chinese characters automatically.
function insertSpace(child: any) {
  if (isString(child.type) && isTwoCNChar(child.props.children)) {
    return React.cloneElement(
      child,
      {},
      child.props.children.split('').join(' '),
    )
  }
  if (isString(child)) {
    if (isTwoCNChar(child)) {
      child = child.split('').join(' ')
    }
    return <span>{child}</span>
  }
  return child
}

const divs:any = [], maskDivs:any = [] // 存在多个popup（实际不建议多个popup叠加）

const Popup = (props: PopupProps) => {

  const {
    className,
    position = 'bottom',
    visible = true,
    overlay = true,
    transparent = false,
    closable = false,
    radius = false,
    maskClosable = true,
    children,
    onClose,
    ...restProps
  } = props

  let closed = false
  let div: any = divs[divs.length > 0 ? (divs.length - 1) : 0], maskDiv: any = maskDivs[maskDivs.length > 0 ? (maskDivs.length - 1) : 0]

  if (!visible) {
    // console.log('Must specify either an alert title, or message, or both')

    if (!closed && div) {
      close()
    }

    return {
      close: () => {}
    }
  }

  div = document.createElement('div')
  maskDiv = document.createElement('div')

  const timestamp = new Date().getTime()
  const nodeID = `${prefixCls}-main-${timestamp}`

  div.id = nodeID

  // 蒙层是否显示
  if (overlay) {

    document.body.className = "fam-overfow-hidden" // 针对弹出层滚动击穿，body隐藏处理

    // 蒙层是否透明
    maskDiv.className = transparent ? `${prefixCls}-mask-transparent` : `${prefixCls}-mask`
    maskDiv.onclick = () => {
      // 蒙层允许关闭
      if (maskClosable) {
        close()
      }
    }

  }

  document.body.appendChild(div)

  // 关闭popup
  function close() {

    closed = true

    handleReander(position) // 重新渲染

    maskDiv.className += ` ${prefixCls}-mask-leave`

    // 延时销毁
    setTimeout(() => {

      ReactDOM.unmountComponentAtNode(div)
      ReactDOM.unmountComponentAtNode(maskDiv)

      if (div && div.parentNode) {
        div.parentNode.removeChild(div)
      }

      if (maskDiv && maskDiv.parentNode) {
        maskDiv.parentNode.removeChild(maskDiv)
      }

      document.body.className = "" // 取消body溢出隐藏

      if (onClose) {
        onClose(div) // 关闭popup回调
      }

      divs.pop()
      maskDivs.pop()

    }, 150)

  }

  divs.push(div)
  maskDivs.push(maskDiv)

  function handleReander(position: any) {

    // 子节点
    const kids = React.Children.map(children, insertSpace)

    // 样式类合并
    const wrapCls = classnames(prefixCls, className, {
      [`${prefixCls}-${position}`]: position,
      [`${prefixCls}-${position}-leave`]: position && closed
    })

    // 圆角
    let borderRadius = ''

    if (radius) {

      let initRadius = (radius instanceof Number) ? radius : 15

      switch (position) {
        case 'top':
          borderRadius = `0 0 ${initRadius}px ${initRadius}px`
          break
        case 'bottom':
          borderRadius = `${initRadius}px ${initRadius}px 0 0`
          break
        case 'right':
          borderRadius = `${initRadius}px 0 0 ${initRadius}px`
          break
        case 'left':
          borderRadius = `0 ${initRadius}px ${initRadius}px 0`
          break
        default:
          borderRadius = `${initRadius}px ${initRadius}px 0 0`
          break
      }

    }

    ReactDOM.render(
      <div
        className={wrapCls}
        {...restProps}
        style={{borderRadius}}
      >
        <div className="fam-popup-warp">
          {
            closable && <Icon.CloseOutline className="fam-popup-close-icon" onClick={close} />
          }
          {kids}
        </div>
      </div>,
      div,
    )
  }

  handleReander(position)

  div.appendChild(maskDiv)

  return {
    close
  }
}

export default Popup

import React from 'react'
