            {run.errors?.length > 0 && (
              <span className="inline-flex items-center gap-1 rounded-full bg-rose-50 px-2.5 py-1 font-medium text-rose-700">
                <FiAlertTriangle size={12} />
                {run.errors.length} error{run.errors.length !== 1 ? "s" : ""}
