import from react { useEffect, useLayoutEffect }

def _is_browser() -> bool {
    return (
        typeof(window) != "undefined"
        and typeof(window.document) != "undefined"
        and typeof(window.document.createElement) != "undefined"
    );
}

def:pub useIsomorphicLayoutEffect(effect: Callable[[], None | Callable[[], None]], deps: list[object] | None = None) {
    if _is_browser() {
        useLayoutEffect(effect, deps);
    } else {
        useEffect(effect, deps);
    }
}

