import from "react" { useEffect }
import from "react-dom" { createPortal }
import from "@/lib/utils" { cn }

def:pub Modal(
    open: bool,
    onClose: Callable[[], None],
    title: str | None = None,
    description: str | None = None,
    children: object | None = None,
    footer: object | None = None,
    className: str | None = None,
) -> JsxElement | None {
    has mounted: bool = False;

    can with entry {
        mounted = True;
    }

    useEffect(lambda () -> object {
        if not open {
            return lambda () -> object { return None; };
        }
        def handle_key_down(event: KeyboardEvent) -> None {
            if event.key == "Escape" {
                onClose();
            }
        }
        window.addEventListener("keydown", handle_key_down);
        return lambda () -> object {
            window.removeEventListener("keydown", handle_key_down);
            return None;
        };
    }, [open, onClose]);

    if not mounted or not open {
        return None;
    }

    createPortal(
        <div className="pointer-events-none fixed inset-0 z-50 flex items-start justify-center px-4 py-6 sm:items-center sm:py-0">
            <div
                className="bg-background/70 pointer-events-auto absolute inset-0 backdrop-blur-sm"
                onClick={onClose}
            />
            <div
                role="dialog"
                aria-modal="true"
                className={cn(
                    "pointer-events-auto relative z-10 w-full max-w-3xl rounded-xl border bg-background p-6 shadow-2xl",
                    "max-h-[85vh] overflow-y-auto",
                    className,
                )}
            >
                <button
                    type="button"
                    onClick={onClose}
                    className="text-muted-foreground hover:text-foreground absolute right-4 top-4 inline-flex size-8 items-center justify-center rounded-full border border-transparent bg-transparent transition hover:border-muted-foreground/40 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2"
                    aria-label="Close"
                >
                    <svg
                        className="size-4"
                        xmlns="http://www.w3.org/2000/svg"
                        width="24"
                        height="24"
                        viewBox="0 0 24 24"
                        fill="none"
                        stroke="currentColor"
                        strokeWidth="2"
                        strokeLinecap="round"
                        strokeLinejoin="round"
                    >
                        <path d="M18 6 6 18" />
                        <path d="m6 6 12 12" />
                    </svg>
                </button>
                <div className="flex flex-col gap-2">
                    {if title {
                        <h2 className="text-lg font-semibold leading-tight">{title}</h2>
                    }}
                    {if description {
                        <p className="text-sm text-muted-foreground">{description}</p>
                    }}
                </div>
                <div className="mt-4 flex flex-col gap-4">{children}</div>
                {if footer {
                    <div className="mt-6 flex justify-end gap-2">{footer}</div>
                }}
            </div>
        </div>,
        document.body,
    )
}

