            <div className='absolute right-0 bottom-0 flex rotate-[25deg] translate-x-[18%] translate-y-[5%]'>
                <Image
                    alt={title}
                    src={img}
                    width={smaller ? 100 : 128}
                    height={smaller ? 100 : 128}
                />
            </div>
        </div>
    )
}

export default GenreItem

