import from "." { WHITE_SPACE_CODE }

def:pub splitChildrenToFragments(children: str | int) -> list[str] {
    return str(children).split(" ");
}

def:pub concatFragments(children: str | int) -> list[str] {
    splittedChildren = splitChildrenToFragments(children);
    parts: list[str] = [];
    for (index, word) in enumerate(splittedChildren) {
        if index != 0 {
            parts.append(WHITE_SPACE_CODE);
        }
        parts.append(word);
    }
    return [(WHITE_SPACE_CODE if word == " " else word) for word in parts];
}

