import { Stack, Text, Button, Collapse, List, Center, Title } from "@mantine/core"
import React from "react"
import { Ce, Database } from "tabler-icons-react"
import type { Breach, styles } from "../types"

const styles: styles = {
    img: {
        backgroundColor: 'snow',
        marginRight: 10
    },
    text: {
        color: "snow"
    }
}

interface BreachDetailsProps {
    breach: Breach
}

const BreachDetails: React.FC<BreachDetailsProps> = ({ breach }) => {
    const [opened, setOpened] = React.useState<boolean>(false)
    const onClick = () => setOpened(!opened)
    return (
        <>
            <Center>
                <img src={breach.LogoPath} alt={breach.Name} height='30' width={'30'} style={styles.img} />
                <Title style={styles.text} order={5}>{breach.Name} Breaches</Title>
            </Center>
            <Button leftIcon={<Database />} color={'red'} variant={'light'} onClick={onClick}>Date: {breach.BreachDate} </Button>
            <Collapse in={opened}>
                <List style={styles.text}>
                    <List.Item>Domain: {breach.Domain}</List.Item>
                    <List.Item>Users: {breach.PwnCount.toLocaleString()}</List.Item>
                    <List.Item>Data Breached: </List.Item>
                    <List style={styles.text} withPadding >
                        {breach?.DataClasses?.map((dataClass) => (
                            <List.Item key={dataClass}>{dataClass}</List.Item>
                        ))}
                    </List>
                </List>
            </Collapse>
        </>
    )
}

export default BreachDetails

import React from "react"
import BreachDetails from "./BreachDetails"
import { vulnerableStatus, secureStatus } from "../constants"
import { Stack, Modal, ScrollArea, Badge, ActionIcon } from '@mantine/core'
import { Check, X } from "tabler-icons-react"
import type { Breach, styles } from "../types"

const styles: styles = {
    statusText: {
        backgroundColor: "#71959A",
    },
    scrollArea: {
        height: "150px"
    },
    badge: {
        cursor: "pointer"
    }
}

interface StatusProps {
    breaches: Breach[]
}


const Status: React.FC<StatusProps> = ({ breaches }) => {
    const [opened, setOpened] = React.useState<boolean>(false)
    const imageSrc = breaches ? vulnerableStatus : secureStatus
    const badgeText = breaches ? `${breaches.length} data breach(es)` : "No breaches"
    const badgeColor = breaches ? "red" : "green"
    const leftSection = (
        <ActionIcon size='xs' color={badgeColor} radius={'xl'} variant={'transparent'}>
            {breaches ? <X size={14} /> : <Check size={14} />}
        </ActionIcon>
    )

    const onClick = () => breaches && setOpened(!opened)

    return (
        <>
            <img src={imageSrc} width="120" />
            <Badge radius={'xl'} variant={'light'} color={badgeColor} onClick={onClick} style={styles.badge} leftSection={leftSection}>{badgeText}</Badge>
            <Modal trapFocus={false} styles={{ modal: { backgroundColor: '#d53867' } }} opened={opened} withCloseButton={false} onClose={() => setOpened(false)}>
                <ScrollArea style={styles.scrollArea}>
                    <Stack>
                        {breaches?.map((breach) => <BreachDetails breach={breach} key={breach.Name} />)}
                    </Stack>
                </ScrollArea>
            </Modal>
        </>
    )
}

export default Status

