      <ul>
        <li>{block2Paragraph1}</li>
        <li>{block2Paragraph2}</li>
        <li>{block2Paragraph3}</li>
      </ul>
      <p>{block2Paragraph4}</p>
      {showGoToTheHomePage ? <Link href="/">Go to the homepage</Link> : null}
    </PageContent>
  );
}

