type WaterfallItem = dict[str, str | int];

def:pub App(cols: int = 2, data: list[WaterfallItem] | None = None, style: dict[str, str | int] = {}) -> JsxElement {
    has arrs: list[list[WaterfallItem]] = [];

    def filiter(arr: list[WaterfallItem]) {
        num: int = 0;
        newArr: list[list[WaterfallItem]] = [];
        if len(arrs) == 0 {
            for _ in range(cols) {
                newArr.append([]);
            }
        } else {
            for col in arrs {
                newArr.append(col[:]);
            }
        }
        for element in arr {
            newArr[num].append(element);
            num = (num + 1) % cols;
        }
        arrs = newArr;
