  const form = useForm<{ kind: string }>({ defaultValues: { kind: "a" } });
  return (
    <FormProvider form={form}>
      <FormSwitch
        field="kind"
        unionOptions={{
          a: [{ name: "label", type: "text", label: "Label" }],
        }}
      />
    </FormProvider>
  );
}

