  get(key: string) {
    return JSON.parse(localStorage.getItem(key) || 'null');
  },
  set(key: string, val: any) {
    localStorage.setItem(key, JSON.stringify(val));
  },
  del(key: string) {
    localStorage.removeItem(key);
  },
};

const TOKEN_NAME = 'auth_token';

