import from "@/services/common" { requestVerifyCodeUrl }

def:pub VerifyCode(setCert: Callable[[str], None], style: dict[str, str | int] | None = None) -> JsxElement {
    has url: str = "";

    def refresh_code() {
        cert = f"{int(Math.random() * Date.now())}_{int(Math.random() * Date.now())}";
        setCert(cert);
        requestVerifyCodeUrl(cert).then(lambda (response: dict[str, str]) {
            url = response["data"];
        });
    }

    can with [setCert] entry {
        refresh_code();
    }

    img_style: dict[str, str | int] = {"height": 30};
    if style {
        img_style = {**style, **img_style};
    }

    <img style={img_style} onClick={lambda (e: MouseEvent) { refresh_code(); }} src={url} />
}

