    restProps = {k: props[k] for k in props if k != "children"};
    svgRef = useCallback(lambda (el: object | None) -> None {
        if not el {
            return;
        }
        svg = d3.select(el);
        g = svg.select("g");
        zoom = d3
            .zoom()
            .extent([[0, 0], [0, 0]])
            .scaleExtent([0.5, 8])
            .on("zoom", lambda (event: object) {
                g.attr("transform", event.transform);
            });
        svg.call(zoom);
    }, []);
    <svg {**restProps} ref={svgRef}>
        <g width="100%" height="100%">
            <foreignObject x={0} y={0} width="100%" height="100%">{children}</foreignObject>
        </g>
    </svg>
}

