"""Calculates item size
- CSS `height` property for vertical timeline
- CSS `width` property for horizontal timeline
"""
import type from ..types { TimelineEvent }
import from "date-fns" { differenceInMilliseconds }
import from ..components.TimelineProvider { useTimelineContext }

def:pub useSizeCalculator() -> Callable[[TimelineEvent], str] {
    timeline = useTimelineContext();

    return lambda (event: TimelineEvent) -> str {
        timelineDatesDiff: float = abs(float(differenceInMilliseconds(timeline.endDate, timeline.startDate)));
        eventDatesDiff: float = abs(float(differenceInMilliseconds(event.endDate, event.startDate)));
        sizePercentage: float = (eventDatesDiff * 100.0) / timelineDatesDiff;
        return f"{sizePercentage}%";
    };
}

