import { PropsWithChildren } from 'react';
import { useProfile } from '../useProfile';
import { selectValueFromProfile } from './helpers';

type MergeTagProps = {
  id: string;
  fallback?: string;
};

export const MergeTag = ({
  id,
  fallback,
}: PropsWithChildren<MergeTagProps>) => {
  const { profile, loading } = useProfile();

  if (loading || !profile) {
    return null;
  }

  // Uses truthy fallback behavior: falsy resolved values (e.g. 0, false, '')
  // are treated the same as unresolved values and will trigger the fallback if provided.
  const value = selectValueFromProfile(profile, id) || fallback;

  return value ? <>{value}</> : null;
};

jac:
import from ..useProfile { useProfile }
import from .helpers { selectValueFromProfile }

def:pub MergeTag(id: str, fallback: str | None = None) -> JsxElement | None {
    profile_state = useProfile();
    profile = profile_state.profile;
    loading = profile_state.loading;
    if loading or profile is None {
        return None;
    }
    resolved = selectValueFromProfile(profile, id);
    value = resolved or fallback;
    if value {
        return <span>{value}</span>;
    }
    return None;
}

