import from "murmurhash-js" { murmur3 }
import from "../../types/Profile/Profile" { Profile }
import from "../../types/ExperienceDefinition" { ExperienceConfiguration }

glob LOWER_BOUND = 0;

glob UPPER_BOUND = 4294967295;

def normalize(val: float, min: float, max: float) -> float {
    return ((val - min) / (max - min));
}

def getRandom(text: str) -> any {
    hash = murmur3(text, 0);
    random = normalize(hash, LOWER_BOUND, UPPER_BOUND);
    return random;
}

def:pub getTrafficRandom(profile: any, experience: any) -> any {
    return getRandom(f"traffic-{experience.id}-{profile.stableId}");
}

def:pub getDistributionRandom(profile: any, experience: any) -> any {
    return getRandom(f"distribution-{experience.id}-{profile.stableId}");
}

