  const [value, setValue] = useState('');
  return (
    <div style={{ display: 'flex', justifyContent: 'space-between' }}>
      <AutosizeInput
        placeholder="我是输入框"
        style={{ border: '1px solid #666' }}
        value={value}
        onChange={function (event) {
          console.log('onChange', event);
          setValue(event.target.value);
        }}
      />
    </div>
  );
}

