def getPurchasesTargets() -> list[dict[str, str | HTMLElement]] {
    items = document.querySelectorAll(PURCHASES_ITEM_SELECTOR) as list[HTMLElement];
    targets: list[dict[str, str | HTMLElement]] = [];
    for item in items {
        id = item.getAttribute("sale_item_id");
        if not id {
            continue;
        }
        links = item.querySelector(PURCHASES_LINKS_SELECTOR) as HTMLElement | None;
        if not links {
            continue;
        }
        mount = links.querySelector(f"[data-band-play-batch-checkbox-mount=\"{id}\"]") as HTMLElement | None;
        if not mount {
            continue;
