def:pub BatchDownloadCheckboxesLayer(
    page: str | None,
    checkboxClass: str,
    onCheckboxClick: Callable[[str, HTMLInputElement, bool, bool], None]
) -> JsxElement {
    if not page {
        return <></>;
    }
    if page == "collection" {
        targets = getCollectionTargets();
        return <>
            {for target in targets {
                tid = target["id"] as str;
                host = target["host"] as HTMLElement;
                createPortal(
