import from "react" { useCallback, useEffect, useRef }

def:pub useScrollEffect(callback: Callable[[Event], None], deps: list[object]) {
    isLock = useRef(False);
    animationFrame = useRef(0);

    onScroll = useCallback(lambda (event: Event) {
        if not isLock.current {
            cancelAnimationFrame(animationFrame.current);
            animationFrame.current = requestAnimationFrame(lambda {
                callback(event);
                setTimeout(lambda { isLock.current = False; }, 10);
            });
            isLock.current = True;
        }
    }, deps);

    useEffect(lambda {
        document.addEventListener("scroll", onScroll);
        return lambda {
            cancelAnimationFrame(animationFrame.current);
            document.removeEventListener("scroll", onScroll);
        };
    }, [onScroll]);
}

