import from "react" { useState, useCallback }

def useLocalStorage[T](key: str, defaultValue: T) -> tuple[T, Callable[[T | Callable[[T], T]], None]] {
    (storedValue, setStoredValue) = useState(lambda {
        try {
            item = localStorage.getItem(key);
            if item {
                return JSON.parse(item) as T;
            }
            return defaultValue;
        } except Exception {
            return defaultValue;
        }
    });
    setValue = useCallback(lambda (value: T | Callable[[T], T]) {
        setStoredValue(lambda (prev: T) {
            newValue: T;
            if callable(value) {
                newValue = (value as Callable[[T], T])(prev);
            } else {
                newValue = value as T;
            }
            try {
                localStorage.setItem(key, JSON.stringify(newValue));
            } except Exception {}
            return newValue;
        });
    }, [key]);
    return (storedValue, setValue);
}

