import { EqualityFn } from "types";

export const shallow: EqualityFn<any> = (a, b) => {
    if (Object.is(a, b)) return true;

    if (
        typeof a !== 'object' || a === null ||
        typeof b !== 'object' || b === null
    ) {
        return false;
    }

    const keysA = Object.keys(a);
    const keysB = Object.keys(b);

    if (keysA.length !== keysB.length) return false;

    for (const key of keysA) {
        if (!Object.prototype.hasOwnProperty.call(b, key) || !Object.is(a[key], b[key])) {
            return false;
        }
    }

    return true;
}

jac:
def:pub shallow(a: object, b: object) -> bool {
    if a is b {
        return True;
    }
    if (
        not isinstance(a, dict)
        or a is None
        or not isinstance(b, dict)
        or b is None
    ) {
        return False;
    }
    a_map = a as dict[str, object];
    b_map = b as dict[str, object];
    keys_a = list(a_map.keys());
    keys_b = list(b_map.keys());
    if len(keys_a) != len(keys_b) {
        return False;
    }
    for key in keys_a {
        if key not in b_map or not (a_map[key] is b_map[key]) {
            return False;
        }
    }
    return True;
}

