import { useState, useCallback } from 'react'
import { message } from 'antd'
import { RPC } from '../../../../shared/types/gateway-rpc'
import type {
   ExecApprovalsFile,
   ExecApprovalsSnapshot,
   ExecApprovalsAllowlistEntry,
} from '../../../../shared/types/gateway-protocol'
import { setPathValue, removePathValue, cloneConfigObject } from '../../../utils/formUtils'
import {
   resolveNodeTargets,
   resolveConfigAgents,
   EXEC_APPROVALS_DEFAULT_SCOPE,
} from '../utils/nodesHelpers'

type ExecSecurity = 'deny' | 'allowlist' | 'full'
type ExecAsk = 'off' | 'on-miss' | 'always'

export interface ExecApprovalsResolvedDefaults {
   security: ExecSecurity
   ask: ExecAsk
   askFallback: ExecSecurity
   autoAllowSkills: boolean
}

export interface ExecApprovalsAgentOption {
   id: string
   name?: string
   isDefault?: boolean
}

function normalizeSecurity(value?: string): ExecSecurity {
   if (value === 'allowlist' || value === 'full' || value === 'deny') return value
   return 'deny'
}

function normalizeAsk(value?: string): ExecAsk {
   if (value === 'always' || value === 'off' || value === 'on-miss') return value
   return 'on-miss'
}

function resolveDefaults(form: ExecApprovalsFile | null): ExecApprovalsResolvedDefaults {
   const defaults = form?.defaults ?? {}
   return {
      security: normalizeSecurity(defaults.security),
      ask: normalizeAsk(defaults.ask),
      askFallback: normalizeSecurity(defaults.askFallback ?? 'deny'),
      autoAllowSkills: Boolean(defaults.autoAllowSkills ?? false),
   }
}

function mergeAgents(
   configForm: Record<string, unknown> | null,
   form: ExecApprovalsFile | null,
): ExecApprovalsAgentOption[] {
   const configAgents = resolveConfigAgents(configForm).map((a) => ({
      id: a.id,
      name: a.name,
      isDefault: a.isDefault,
   }))
   const approvalsAgents = Object.keys(form?.agents ?? {})
   const merged = new Map<string, ExecApprovalsAgentOption>()
   configAgents.forEach((a) => merged.set(a.id, a))
   approvalsAgents.forEach((id) => {
      if (!merged.has(id)) merged.set(id, { id })
   })
   const agents = Array.from(merged.values())
   if (agents.length === 0) agents.push({ id: 'main', isDefault: true })
   agents.sort((a, b) => {
      if (a.isDefault && !b.isDefault) return -1
      if (!a.isDefault && b.isDefault) return 1
      const aLabel = a.name?.trim() ? a.name : a.id
      const bLabel = b.name?.trim() ? b.name : b.id
      return aLabel.localeCompare(bLabel)
   })
   return agents
}

export function useExecApprovals(
   rpc: <T = unknown>(method: string, params?: unknown) => Promise<T>,
   connected: boolean,
   nodes: Array<Record<string, unknown>>,
   configForm: Record<string, unknown> | null,
) {
   const [snapshot, setSnapshot] = useState<ExecApprovalsSnapshot | null>(null)
   const [form, setForm] = useState<ExecApprovalsFile | null>(null)
   const [loading, setLoading] = useState(false)
   const [saving, setSaving] = useState(false)
   const [dirty, setDirty] = useState(false)
   const [selectedAgent, setSelectedAgent] = useState<string | null>(null)
   const [target, setTarget] = useState<'gateway' | 'node'>('gateway')
   const [targetNodeId, setTargetNodeId] = useState<string | null>(null)

   const targetNodes = resolveNodeTargets(nodes, [
      'system.execApprovals.get',
      'system.execApprovals.set',
   ])
   const effectiveForm = form ?? snapshot?.file ?? null
   const defaults = resolveDefaults(effectiveForm)
   const agents = mergeAgents(configForm, effectiveForm)

   // 解析当前 scope
   const selectedScope = (() => {
      if (selectedAgent === EXEC_APPROVALS_DEFAULT_SCOPE) return EXEC_APPROVALS_DEFAULT_SCOPE
      if (selectedAgent && agents.some((a) => a.id === selectedAgent)) return selectedAgent
      return EXEC_APPROVALS_DEFAULT_SCOPE
   })()

   // 当前 agent 的数据
   const selectedAgentData: Record<string, unknown> | null =
      selectedScope !== EXEC_APPROVALS_DEFAULT_SCOPE
         ? (((effectiveForm?.agents ?? {})[selectedScope] as Record<string, unknown>) ?? null)
         : null

   const allowlist: ExecApprovalsAllowlistEntry[] = Array.isArray(
      (selectedAgentData as { allowlist?: unknown })?.allowlist,
   )
      ? ((selectedAgentData as { allowlist: ExecApprovalsAllowlistEntry[] }).allowlist ?? [])
      : []

   const load = useCallback(async () => {
      if (!connected) return
      setLoading(true)
      try {
         const method =
            target === 'node' ? RPC.EXEC_APPROVALS_NODE_GET : RPC.EXEC_APPROVALS_GET
         const params = target === 'node' ? { nodeId: targetNodeId } : {}
         const result = await rpc<ExecApprovalsSnapshot>(method, params)
         setSnapshot(result)
         if (result?.file) {
            setForm(cloneConfigObject(result.file as unknown as Record<string, unknown>) as unknown as ExecApprovalsFile)
         }
         setDirty(false)
      } catch (err) {
         message.error(`加载审批配置失败: ${err instanceof Error ? err.message : String(err)}`)
         console.error('[NodesPage] Load exec approvals error:', err)
      } finally {
         setLoading(false)
      }
   }, [rpc, connected, target, targetNodeId])

   const save = useCallback(async () => {
      if (!connected || !snapshot) return
      setSaving(true)
      try {
         const method =
            target === 'node' ? RPC.EXEC_APPROVALS_NODE_SET : RPC.EXEC_APPROVALS_SET
         const file = form ?? snapshot.file ?? {}
         const params =
            target === 'node'
               ? { nodeId: targetNodeId, file, baseHash: snapshot.hash }
               : { file, baseHash: snapshot.hash }
         await rpc(method, params)
         message.success('审批配置已保存')
         setDirty(false)
         await load()
      } catch (err) {
         message.error(`保存失败: ${err instanceof Error ? err.message : String(err)}`)
         console.error('[NodesPage] Save exec approvals error:', err)
      } finally {
         setSaving(false)
      }
   }, [rpc, connected, target, targetNodeId, form, snapshot, load])

   const changeTarget = useCallback(
      (kind: 'gateway' | 'node', nodeId: string | null) => {
         setTarget(kind)
         setTargetNodeId(kind === 'node' ? nodeId : null)
         setSnapshot(null)
         setForm(null)
         setDirty(false)
      },
      [],
   )

   const selectAgent = useCallback((agentId: string) => {
      setSelectedAgent(agentId)
   }, [])

   const patch = useCallback(
      (path: Array<string | number>, value: unknown) => {
         setForm((prev) => {
            const base = prev ?? snapshot?.file ?? {}
            const next = setPathValue(
               base as unknown as Record<string, unknown>,
               path,
               value,
            )
            return next as unknown as ExecApprovalsFile
         })
         setDirty(true)
      },
      [snapshot],
   )

   const remove = useCallback(
      (path: Array<string | number>) => {
         setForm((prev) => {
            const base = prev ?? snapshot?.file ?? {}
            const next = removePathValue(
               base as unknown as Record<string, unknown>,
               path,
            )
            return next as unknown as ExecApprovalsFile
         })
         setDirty(true)
      },
      [snapshot],
   )

   const ready = Boolean(effectiveForm)
   const targetReady = target !== 'node' || Boolean(targetNodeId)
   const disabled = saving || loading

   return {
      ready,
      disabled,
      dirty,
      loading,
      saving,
      target,
      targetNodeId,
      targetNodes,
      defaults,
      agents,
      selectedScope,
      selectedAgentData,
      allowlist,
      targetReady,
      load,
      save,
      changeTarget,
      selectAgent,
      patch,
      remove,
   }
}

import type { WizardStep } from './useWizardRpc'

// ── 阶段状态机 ──

export type WizardPhase = 'pre-auth' | 'auth' | 'post-auth'

// ── 已知 provider 关键字（用于检测 auth provider 选择步骤） ──

const KNOWN_PROVIDER_VALUES = new Set([
   'anthropic',
   'openai',
   'google',
   'copilot',
   'openrouter',
   'moonshot',
   'ollama',
   'minimax',
   'custom',
   'xai',
   'mistral',
   'skip',
   'qwen',
   'together',
   'huggingface',
   'venice',
   'deepseek',
   'groq',
   'litellm',
   'ai-gateway',
   'cloudflare-ai-gateway',
   'volcengine',
   'byteplus',
   'qianfan',
   'modelstudio',
])

// ── 退出 AUTH_PHASE 的信号值（select options 中出现这些值说明已进入后续配置） ──

const POST_AUTH_SIGNAL_VALUES = new Set([
   // Gateway 配置
   'loopback',
   'lan',
   'tailnet',
   'auto',
   'token',
   'password',
   'later',
   'tui',
   'web',
   'restart',
   'reinstall',
   'configure',
   'remove',
   'npm',
   'pnpm',
   'node',
   'bun',
   'serve',
   'funnel',
   'off',
])

// ── 频道和搜索相关关键字（option value 包含这些子串则为 POST_AUTH 信号） ──
// 使用 contains 匹配以应对 value 格式变化（如 "telegram-bot-api", "brave-search" 等）

const POST_AUTH_CONTAINS_KEYWORDS = [
   // 消息频道
   'telegram',
   'whatsapp',
   'discord',
   'slack',
   'signal',
   'imessage',
   'imsg',
   'irc',
   'line',
   'google-chat',
   // 搜索引擎
   'brave',
   'perplexity',
   'firecrawl',
   'tavily',
]

// ── 检测 secret input mode 选择步骤（plaintext vs ref） ──
// 该步骤询问 API key 存储方式，始终选择 plaintext 以直接保存到 openclaw.json

function isSecretInputModeStep(step: WizardStep): boolean {
   if (step.type !== 'select' || !step.options || step.options.length !== 2) return false
   const values = new Set(step.options.map((o) => String(o.value).toLowerCase()))
   return values.has('plaintext') && values.has('ref')
}

// ── 检测凭据输入步骤（API key、token 等） ──
// 通过 message 内容检测，作为安全网防止凭据步骤被错误地自动回答
// （即使阶段检测失败也能正确展示给用户）

const CREDENTIAL_MESSAGE_PATTERNS = [
   /api[\s_-]?key/i,
   /enter.*key/i,
   /paste.*key/i,
   /use existing.*key/i,
   /existing.*api/i,
   /\btoken\b.*enter/i,
   /enter.*\btoken\b/i,
   /\bsecret\b/i,
   /\bpassword\b/i,
   /\bcredential/i,
]

function isCredentialStep(step: WizardStep): boolean {
   if (step.type !== 'text' && step.type !== 'confirm') return false
   const msg = step.message ?? ''
   return CREDENTIAL_MESSAGE_PATTERNS.some((re) => re.test(msg))
}

// ── select 自动回答的优先级值列表 ──
// 按优先级从高到低排列，匹配到第一个即使用

const SELECT_PREFERRED_VALUES: string[] = [
   'quickstart',
   'keep',
   'later',
   'skip',
   'restart',
   'plaintext',
]

/**
 * 检测步骤是否为 auth provider 选择步骤（进入 AUTH_PHASE 的入口）。
 *
 * 判断条件：type='select'，且 options 中至少 2 个 value 匹配已知 provider 关键字。
 */
export function isAuthProviderStep(step: WizardStep): boolean {
   if (step.type !== 'select' || !step.options || step.options.length < 3) return false

   let matchCount = 0
   for (const opt of step.options) {
      const val = String(opt.value).toLowerCase()
      if (KNOWN_PROVIDER_VALUES.has(val)) {
         matchCount++
         if (matchCount >= 2) return true
      }
   }
   return false
}

/**
 * 检测步骤是否为退出 AUTH_PHASE 的信号。
 *
 * 以下情况表示已离开模型配置阶段：
 * - progress / action 类型步骤
 * - select 步骤的 options 含有 gateway/daemon/channel/search 相关值
 */
export function isPostAuthSignal(step: WizardStep): boolean {
   if (step.type === 'progress' || step.type === 'action') return true

   if (step.type === 'select' && step.options) {
      for (const opt of step.options) {
         const val = String(opt.value).toLowerCase()
         // 精确匹配 gateway/daemon 相关值
         if (POST_AUTH_SIGNAL_VALUES.has(val)) return true
         // 包含匹配频道/搜索相关关键字
         for (const kw of POST_AUTH_CONTAINS_KEYWORDS) {
            if (val.includes(kw)) return true
         }
      }
   }

   return false
}

/**
 * 计算步骤的自动回答值。
 *
 * 返回 `undefined` 表示无法确定默认答案，应回退为展示给用户。
 */
export function resolveAutoAnswer(step: WizardStep, phase: WizardPhase): unknown | undefined {
   // 凭据输入步骤永远不自动回答（双重保险，与 shouldShowToUser 配合）
   if (isCredentialStep(step)) return undefined

   switch (step.type) {
      case 'note':
         return null

      case 'confirm':
         // PRE_AUTH：风险确认 → 同意；POST_AUTH：daemon/skills → 拒绝
         return phase === 'pre-auth'

      case 'progress':
         return null

      case 'action':
         return null

      case 'text':
         // 敏感输入（API Key 等）不应自动回答
         if (step.sensitive) return undefined
         return step.initialValue ?? ''

      case 'multiselect':
         return step.initialValue ?? []

      case 'select': {
         if (!step.options || step.options.length === 0) return undefined

         // 按优先级匹配已知的默认值（使用 contains 匹配以覆盖 "skip-for-now" 等变体）
         for (const preferred of SELECT_PREFERRED_VALUES) {
            const match = step.options.find((o) =>
               String(o.value).toLowerCase().includes(preferred),
            )
            if (match) return match.value
         }

         // 使用 initialValue（如果在 options 中存在）
         if (step.initialValue !== undefined && step.initialValue !== null) {
            const exists = step.options.some((o) => o.value === step.initialValue)
            if (exists) return step.initialValue
         }

         // 回退：选第一个非 __back 的选项
         const first = step.options.find((o) => !String(o.value).startsWith('__'))
         return first?.value
      }

      default:
         return undefined
   }
}

/**
 * 判断在当前阶段下，步骤是否需要展示给用户。
 *
 * - PRE_AUTH / POST_AUTH：全部自动回答
 * - AUTH_PHASE：select/text/confirm 展示给用户，note/progress/action 自动跳过
 */
export function shouldShowToUser(step: WizardStep, phase: WizardPhase): boolean {
   // Secret input mode 步骤始终自动回答（选择 plaintext，API key 直接保存到 openclaw.json）
   if (isSecretInputModeStep(step)) return false

   // 凭据输入步骤（API key / token 等）无论在哪个阶段都展示给用户
   // 这是安全网：即使阶段检测出错，也不会跳过凭据输入
   if (isCredentialStep(step)) return true

   // Auth provider 选择步骤也始终展示（双重保险，防止阶段未正确转换到 auth）
   if (isAuthProviderStep(step)) return true

   if (phase === 'pre-auth' || phase === 'post-auth') return false

   // AUTH_PHASE 内部：交互类步骤展示给用户
   if (
      step.type === 'select' ||
      step.type === 'text' ||
      step.type === 'confirm' ||
      step.type === 'multiselect'
   ) {
      return true
   }

   // note / progress / action 在 AUTH_PHASE 中也自动跳过
   return false
}

import React, { useState, useEffect, useCallback, useRef } from 'react'
import { Typography, Spin, Button, Alert, Space, Badge } from 'antd'
import { ReloadOutlined, ApiOutlined } from '@ant-design/icons'
import { useGateway } from '../../../contexts/GatewayContext'
import { createLogger } from '../../../../shared/logger'
import type { GatewayProcessStatus } from '../../../types/global'

const log = createLogger('BuiltinGatewayStep')

const { Title, Paragraph, Text } = Typography

const STATUS_TEXT: Record<GatewayProcessStatus, string> = {
   idle: '准备启动...',
   starting: '正在启动 Gateway...',
   running: '正在连接...',
   stopping: '正在停止...',
   crashed: 'Gateway 启动失败',
}

interface Props {
   onConnected: () => void
   onSwitchToExternal: () => void
   onBack: () => void
}

export default function BuiltinGatewayStep({ onConnected, onSwitchToExternal, onBack }: Props) {
   const { connected } = useGateway()
   const [status, setStatus] = useState<GatewayProcessStatus>('idle')
   const [error, setError] = useState<string | null>(null)
   const [loading, setLoading] = useState(false)
   const triggeredRef = useRef(false)
   const connectedCalledRef = useRef(false)

   // 连接成功 → 通知父组件
   useEffect(() => {
      if (connected && !connectedCalledRef.current) {
         connectedCalledRef.current = true
         log.log('Connected, proceeding')
         onConnected()
      }
   }, [connected, onConnected])

   // 监听进程状态
   useEffect(() => {
      window.clawAPI.gateway.getBuiltinStatus().then((s) => {
         log.log('Initial builtin status: %s', s)
         setStatus(s)
      })

      const unsubscribe = window.clawAPI.gateway.onBuiltinStatusChanged((s) => {
         log.log('Builtin status changed: %s', s)
         setStatus(s)
         setLoading(false)
      })

      return () => {
         unsubscribe()
      }
   }, [])

   // 自动启动
   useEffect(() => {
      if (triggeredRef.current) return
      if (connected) return // 已连接则不需要启动

      if (status === 'idle' || status === 'crashed') {
         triggeredRef.current = true
         startGateway()
      }
      // running 状态说明已被主进程自动启动，只需等待连接
   }, [status, connected])

   const startGateway = useCallback(async () => {
      log.log('Starting builtin gateway')
      setLoading(true)
      setError(null)
      try {
         const result = await window.clawAPI.gateway.startBuiltin()
         if (!result.success) {
            setError(result.error ?? '启动失败')
            setLoading(false)
         }
      } catch (err) {
         log.error('startBuiltin error:', err)
         setError(err instanceof Error ? err.message : String(err))
         setLoading(false)
      }
   }, [])

   const handleRetry = useCallback(() => {
      triggeredRef.current = true
      connectedCalledRef.current = false
      startGateway()
   }, [startGateway])

   const isFailed = status === 'crashed' || (error !== null && !loading)

   return (
      <div style={{ textAlign: 'center' }}>
         <Title level={3} style={{ marginBottom: 8 }}>
            启动内置 Gateway
         </Title>
         <Paragraph type="secondary" style={{ marginBottom: 32 }}>
            正在启动 OpenClaw Gateway，请稍候...
         </Paragraph>

         {!isFailed && (
            <div style={{ marginBottom: 24 }}>
               <Spin size="large" />
               <div style={{ marginTop: 16 }}>
                  <Badge
                     status={
                        status === 'running' || connected ? 'processing' : 'default'
                     }
                  />
                  <Text style={{ marginLeft: 8 }}>
                     {connected ? '已连接' : STATUS_TEXT[status]}
                  </Text>
               </div>
               <div style={{ marginTop: 24 }}>
                  <Button onClick={onBack}>上一步</Button>
               </div>
            </div>
         )}

         {isFailed && (
            <div>
               <Alert
                  type="error"
                  message="Gateway 启动失败"
                  description={error ?? '内置 Gateway 进程崩溃，请重试或切换为外部模式。'}
                  style={{ marginBottom: 24, textAlign: 'left' }}
               />
               <Space>
                  <Button onClick={onBack}>上一步</Button>
                  <Button
                     type="primary"
                     icon={<ReloadOutlined />}
                     onClick={handleRetry}
                     loading={loading}
                  >
                     重试
                  </Button>
                  <Button icon={<ApiOutlined />} onClick={onSwitchToExternal}>
                     切换为外部模式
                  </Button>
               </Space>
            </div>
         )}
      </div>
   )
}

import { useState, useCallback, useEffect, useRef } from 'react'
import { useGateway } from '../../contexts/GatewayContext'
import { RPC } from '../../../shared/types/gateway-rpc'
import type { SkillStatusReport } from '../../../shared/types/gateway-protocol'
import { listSkills, searchPackages, packageToStoreSkill } from './clawhub-api'
import type { StoreSkill } from './clawhub-api'
import { createLogger } from '../../../shared/logger'

const log = createLogger('StoreState')

const PAGE_SIZE = 20
const DEBOUNCE_MS = 300

export interface StoreState {
   skills: StoreSkill[]
   loading: boolean
   error: string | null
   query: string
   hasMore: boolean
   installingSlug: string | null
   installedSlugs: Set<string>
   installMessage: { slug: string; kind: 'success' | 'error'; text: string } | null
   setQuery: (q: string) => void
   loadMore: () => Promise<void>
   installSkill: (slug: string) => Promise<void>
   refresh: () => Promise<void>
}

function getErrorMessage(err: unknown): string {
   if (err instanceof DOMException && err.name === 'AbortError') return '请求超时'
   return err instanceof Error ? err.message : String(err)
}

export function useStoreState(): StoreState {
   const { rpc, connected } = useGateway()

   const [skills, setSkills] = useState<StoreSkill[]>([])
   const [loading, setLoading] = useState(false)
   const [error, setError] = useState<string | null>(null)
   const [query, setQueryRaw] = useState('')
   const [nextCursor, setNextCursor] = useState<string | null>(null)
   const [hasMore, setHasMore] = useState(false)
   const [installingSlug, setInstallingSlug] = useState<string | null>(null)
   const [installedSlugs, setInstalledSlugs] = useState<Set<string>>(new Set())
   const [installMessage, setInstallMessage] = useState<{
      slug: string
      kind: 'success' | 'error'
      text: string
   } | null>(null)

   const debounceRef = useRef<ReturnType<typeof setTimeout> | null>(null)
   const mountedRef = useRef(true)

   useEffect(() => {
      mountedRef.current = true
      return () => {
         mountedRef.current = false
      }
   }, [])

   // ── 加载已安装技能名称集合 ──

   const refreshInstalledSlugs = useCallback(async () => {
      if (!connected) return
      try {
         const raw = await rpc<SkillStatusReport>(RPC.SKILLS_STATUS, {})
         if (raw?.skills && mountedRef.current) {
            setInstalledSlugs(new Set(raw.skills.map((s) => s.name)))
         }
      } catch {
         // 静默失败 — 仅影响"已安装"标记
      }
   }, [rpc, connected])

   // ── 浏览模式加载 ──

   const loadBrowse = useCallback(async (cursor?: string) => {
      setLoading(true)
      setError(null)
      try {
         const resp = await listSkills(PAGE_SIZE, cursor)
         if (!mountedRef.current) return
         const newSkills = resp.items.map(packageToStoreSkill)
         if (cursor) {
            setSkills((prev) => [...prev, ...newSkills])
         } else {
            setSkills(newSkills)
         }
         setNextCursor(resp.nextCursor ?? null)
         setHasMore(Boolean(resp.nextCursor))
      } catch (err) {
         if (!mountedRef.current) return
         const msg = getErrorMessage(err)
         log.error('loadBrowse error:', msg)
         setError(msg)
      } finally {
         if (mountedRef.current) setLoading(false)
      }
   }, [])

   // ── 搜索模式加载 ──

   const loadSearch = useCallback(async (q: string) => {
      setLoading(true)
      setError(null)
      try {
         const results = await searchPackages(q, PAGE_SIZE)
         if (!mountedRef.current) return
         setSkills(results.map((r) => packageToStoreSkill(r.package)))
         setNextCursor(null)
         setHasMore(false)
      } catch (err) {
         if (!mountedRef.current) return
         const msg = getErrorMessage(err)
         log.error('loadSearch error:', msg)
         setError(msg)
      } finally {
         if (mountedRef.current) setLoading(false)
      }
   }, [])

   // ── 初始加载 ──

   useEffect(() => {
      loadBrowse()
      refreshInstalledSlugs()
   }, [loadBrowse, refreshInstalledSlugs])

   // ── 搜索防抖 ──

   const setQuery = useCallback(
      (q: string) => {
         setQueryRaw(q)
         if (debounceRef.current) clearTimeout(debounceRef.current)
         debounceRef.current = setTimeout(() => {
            const trimmed = q.trim()
            if (trimmed) {
               loadSearch(trimmed)
            } else {
               loadBrowse()
            }
         }, DEBOUNCE_MS)
      },
      [loadBrowse, loadSearch],
   )

   // 组件卸载清理防抖
   useEffect(() => {
      return () => {
         if (debounceRef.current) clearTimeout(debounceRef.current)
      }
   }, [])

   // ── 加载更多 ──

   const loadMore = useCallback(async () => {
      if (!nextCursor || loading) return
      await loadBrowse(nextCursor)
   }, [nextCursor, loading, loadBrowse])

   // ── 安装技能 ──

   const installSkill = useCallback(
      async (slug: string) => {
         if (!connected) return
         setInstallingSlug(slug)
         setInstallMessage(null)

         const MAX_RETRIES = 3
         const RETRY_BASE_MS = 5000

         try {
            for (let attempt = 0; attempt <= MAX_RETRIES; attempt++) {
               try {
                  const result = await rpc<{ message?: string; ok?: boolean }>(RPC.SKILLS_INSTALL, {
                     source: 'clawhub',
                     slug,
                  })
                  if (mountedRef.current) {
                     setInstallMessage({
                        slug,
                        kind: 'success',
                        text: result?.message ?? '安装完成',
                     })
                     await refreshInstalledSlugs()
                  }
                  return
               } catch (err) {
                  if (!mountedRef.current) return
                  const msg = getErrorMessage(err)
                  const isRateLimit = /429|rate.?limit/i.test(msg)
                  if (isRateLimit && attempt < MAX_RETRIES) {
                     const delayMs = RETRY_BASE_MS * Math.pow(2, attempt)
                     log.log(
                        'installSkill rate limited, retrying in %dms (attempt %d)',
                        delayMs,
                        attempt + 1,
                     )
                     setInstallMessage({
                        slug,
                        kind: 'error',
                        text: `请求限频，${Math.round(delayMs / 1000)}s 后自动重试...`,
                     })
                     await new Promise((r) => setTimeout(r, delayMs))
                     if (!mountedRef.current) return
                     continue
                  }
                  log.error('installSkill error:', msg)
                  setInstallMessage({ slug, kind: 'error', text: msg })
                  return
               }
            }
         } finally {
            if (mountedRef.current) setInstallingSlug(null)
         }
      },
      [rpc, connected, refreshInstalledSlugs],
   )

   // ── 刷新 ──

   const refresh = useCallback(async () => {
      const trimmed = query.trim()
      if (trimmed) {
         await loadSearch(trimmed)
      } else {
         await loadBrowse()
      }
      await refreshInstalledSlugs()
   }, [query, loadBrowse, loadSearch, refreshInstalledSlugs])

   return {
      skills,
      loading,
      error,
      query,
      hasMore,
      installingSlug,
      installedSlugs,
      installMessage,
      setQuery,
      loadMore,
      installSkill,
      refresh,
   }
}

import { useMemo } from 'react'
import { Tooltip } from 'antd'
import type { SessionUsageEntry } from '../../../../shared/types/gateway-protocol'
import { buildUsageMosaicStats, formatTokens } from '../usage-utils'
import css from '../UsagePage.module.css'

interface UsageActivityGridProps {
   sessions: SessionUsageEntry[]
   timeZone: 'local' | 'utc'
   selectedHours: number[]
   onSelectHour: (hour: number, shiftKey: boolean) => void
   onClearHours: () => void
}

const HOUR_LABELS: Array<{ hour: number; label: string }> = [
   { hour: 0, label: '午夜' },
   { hour: 4, label: '4时' },
   { hour: 8, label: '8时' },
   { hour: 12, label: '正午' },
   { hour: 16, label: '16时' },
   { hour: 20, label: '20时' },
]

function cellBg(intensity: number): string {
   if (intensity <= 0) return 'transparent'
   return `rgba(255, 77, 77, ${0.08 + intensity * 0.7})`
}

function cellBorder(intensity: number, selected: boolean): string {
   if (selected) return 'rgba(255, 77, 77, 0.8)'
   if (intensity > 0.7) return 'rgba(255, 77, 77, 0.4)'
   return 'rgba(255, 77, 77, 0.15)'
}

export default function UsageActivityGrid(props: UsageActivityGridProps) {
   const { sessions, timeZone, selectedHours, onSelectHour } = props

   const stats = useMemo(
      () => buildUsageMosaicStats(sessions, timeZone),
      [sessions, timeZone],
   )

   const maxWeekday = useMemo(() => {
      if (!stats.hasData) return 1
      return Math.max(...stats.weekdayTotals.map((w) => w.tokens), 1)
   }, [stats])

   const maxHour = useMemo(() => {
      if (!stats.hasData) return 1
      return Math.max(...stats.hourTotals, 1)
   }, [stats])

   if (!stats.hasData) {
      return (
         <div className={css.chartCard}>
            <div className={css.chartHeader}>
               <span className={css.chartTitle}>按时间活动</span>
            </div>
            <div
               className={css.chartBody}
               style={{
                  display: 'flex',
                  justifyContent: 'center',
                  alignItems: 'center',
                  padding: '40px 0',
                  color: 'var(--ant-color-text-quaternary)',
                  fontSize: 13,
               }}
            >
               暂无时间线数据
            </div>
         </div>
      )
   }

   return (
      <div className={css.chartCard}>
         <div className={css.chartHeader}>
            <span className={css.chartTitle}>按时间活动</span>
         </div>
         <div className={css.chartBody}>
            {/* ── Weekday distribution ── */}
            <div style={{ marginBottom: 16 }}>
               <div className={css.activityLabel}>星期分布</div>
               <div className={css.weekdayGrid}>
                  {stats.weekdayTotals.map((day) => {
                     const intensity = day.tokens / maxWeekday
                     return (
                        <Tooltip
                           key={day.label}
                           title={`${day.label}: ${formatTokens(day.tokens)}`}
                        >
                           <div
                              className={css.weekdayCell}
                              style={{
                                 background: cellBg(intensity),
                                 borderColor: cellBorder(intensity, false),
                              }}
                           >
                              <div style={{ color: 'var(--ant-color-text)', fontSize: 11 }}>
                                 {day.label}
                              </div>
                              <div
                                 style={{
                                    color: 'var(--ant-color-text-tertiary)',
                                    marginTop: 2,
                                    fontSize: 10,
                                    fontFamily:
                                       "'SF Mono', 'Menlo', 'Monaco', 'Cascadia Code', monospace",
                                 }}
                              >
                                 {formatTokens(day.tokens)}
                              </div>
                           </div>
                        </Tooltip>
                     )
                  })}
               </div>
            </div>

            {/* ── Hourly distribution ── */}
            <div>
               <div
                  style={{
                     display: 'flex',
                     justifyContent: 'space-between',
                     alignItems: 'center',
                     marginBottom: 6,
                  }}
               >
                  <span className={css.activityLabel} style={{ marginBottom: 0 }}>
                     小时分布
                  </span>
                  <span style={{ fontSize: 10, color: 'var(--ant-color-text-quaternary)' }}>
                     0 → 23
                  </span>
               </div>
               <div className={css.hourGrid}>
                  {stats.hourTotals.map((tokens, hour) => {
                     const intensity = tokens / maxHour
                     const selected = selectedHours.includes(hour)
                     return (
                        <Tooltip
                           key={hour}
                           title={`${String(hour).padStart(2, '0')}:00 - ${formatTokens(tokens)}`}
                        >
                           <div
                              className={css.hourCell}
                              style={{
                                 background: cellBg(intensity),
                                 border: `1px solid ${cellBorder(intensity, selected)}`,
                                 ...(selected ? { borderWidth: 2 } : {}),
                              }}
                              onClick={(e) => onSelectHour(hour, e.shiftKey)}
                           />
                        </Tooltip>
                     )
                  })}
               </div>

               {/* Hour labels */}
               <div className={css.hourLabels}>
                  {Array.from({ length: 24 }, (_, hour) => {
                     const label = HOUR_LABELS.find((h) => h.hour === hour)
                     return (
                        <div key={hour} className={css.hourLabel}>
                           {label?.label ?? ''}
                        </div>
                     )
                  })}
               </div>

               <div className={css.densityLegend}>低 → 高 token 密度</div>
            </div>
         </div>
      </div>
   )
}

