import React from 'react';
import { createSlice, PayloadAction } from '@reduxjs/toolkit';
import { JSX } from 'react';

export interface ModalState {
    isOpen: boolean;
    modalType: 'course' | 'add-lesson' | 'alert-fields' | 'standard' | 'confirm' | 'confirm-video' | 'video-queued' | 'alert-error-creating-codevideo' | 'confirm-codevideo-generation'
    title: string;
    callbackId: string;
}

const initialState: ModalState = {
    isOpen: false,
    modalType: 'standard',
    title: '',
    callbackId: ''
};

const modalSlice = createSlice({
    name: 'modal',
    initialState,
    reducers: {
        openModal: (state, action: PayloadAction<{ modalType: 'course' | 'add-lesson' | 'alert-fields' | 'standard' | 'confirm' | 'video-queued' | 'alert-error-creating-codevideo' | 'confirm-codevideo-generation', title: string}>) => {
            state.isOpen = true;
            state.modalType = action.payload.modalType;
            state.title = action.payload.title;
        },
        openCourseModal: (state) => {
            state.isOpen = true;
            state.modalType = 'course';
        },
        openLessonModal: (state) => {
            state.isOpen = true;
            state.modalType = 'add-lesson';
        },
        closeModal: (state) => {
            state.isOpen = false;
            state.modalType = 'standard';
            state.title = "";
        },
        setCallbackId: (state, action: PayloadAction<string>) => {
            state.callbackId = action.payload;
        }
    }
});

export const { openModal, openCourseModal, openLessonModal, closeModal, setCallbackId } = modalSlice.actions;
export default modalSlice.reducer;

import { IAction } from "@fullstackcraftllc/codevideo-types";
import { createSlice } from "@reduxjs/toolkit";

export interface RecordingState {
    isRecording: boolean;
    isFileExplorerFocused: boolean;
    isEditorFocused: boolean;
    isTerminalFocused: boolean;
    atomicRecordedActions: IAction[];
    collectedRecordedActions: IAction[];
}

export const recordingInitialState: RecordingState = {
    isRecording: false,
    isFileExplorerFocused: false,
    isEditorFocused: false,
    isTerminalFocused: false,
    atomicRecordedActions: [],
    collectedRecordedActions: [],
};

const recordingSlice = createSlice({
    name: "recording",
    initialState: recordingInitialState,
    reducers: {
        setIsRecording(state, action) {
            state.isRecording = action.payload;
        },
        setIsFileExplorerFocused(state, action) {
            state.isFileExplorerFocused = action.payload;
            state.isEditorFocused = false;
            state.isTerminalFocused = false;
        },
        setIsEditorFocused(state, action) {
            state.isEditorFocused = action.payload;
            state.isFileExplorerFocused = false;
            state.isTerminalFocused = false;
        },
        setIsTerminalFocused(state, action) {
            state.isTerminalFocused = action.payload;
            state.isFileExplorerFocused = false;
            state.isEditorFocused = false;
        },
        setAtomicRecordedActions(state, action) {
            state.atomicRecordedActions = action.payload;
        },
        setCollectedRecordedActions(state, action) {
            state.collectedRecordedActions = action.payload
        },
        turnOffRecording(state) {
            state.isRecording = false;
            state.atomicRecordedActions = [];
            state.collectedRecordedActions = [];
            state.isFileExplorerFocused = false;
            state.isEditorFocused = false;
            state.isTerminalFocused = false;
        }
    }
});

