export function shuffleArray<T>(array: Array<T>) {
  const copy = [...array];
  for (let i = copy.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [copy[i], copy[j]] = [copy[j], copy[i]];
  }
  return copy;
}

export type Unpack<T> = T extends (infer U)[] ? U : T;

