  titleSuffixComponent?: React.ReactNode;
  titleSuffix?: string;
  titleSuffixProps?: DetailedHTMLProps<
    React.HTMLAttributes<HTMLSpanElement>,
    HTMLSpanElement
  >;
}

const Title = (props: { field: TitleProps }) => {
  const {
    field: {
      title,
      titleProps,
      titleContainerProps,
      titleSuffixComponent,
      titleSuffix,
      titleSuffixProps,
    },
  } = props;

  return (
    <Box
      {...titleContainerProps}
      sx={{
        display: "flex",
        alignItems: "baseline",
        ...titleContainerProps?.sx,
      }}
    >
      <Typography {...titleProps}>
        {title?.split("\n").map((text, index) => {
          if (index === 0) {
            return <span key={index}>{text}</span>;
          }
          return (
            <Fragment key={index}>
              <br />
              <span>{text}</span>
            </Fragment>
          );
        })}{" "}
        {titleSuffixComponent ||
          (titleSuffix && <span {...titleSuffixProps}>{titleSuffix}</span>)}
      </Typography>
    </Box>
  );
};

export { Title };

