def:pub Title(props: TitleComponentProps) -> JsxElement {
    field = props.field;
    titleLines: list[str] = field.title.split("\n") if field.title is not None else [];
    containerProps: dict[str, object] = field.titleContainerProps or {};
    titleSpanProps: dict[str, object] = field.titleProps or {};
    suffixSpanProps: dict[str, object] = field.titleSuffixProps or {};
    return <div
        {...containerProps}
        style={{"display": "flex", "alignItems": "baseline"}}
    >
        <span {...titleSpanProps}>
            {for (i, text) in enumerate(titleLines) {
                if i == 0 {
                    <span>{text}</span>;
                } else {
                    <><br /><span>{text}</span></>;
                }
            }}{" "}
            {field.titleSuffixComponent or (field.titleSuffix and <span {...suffixSpanProps}>{field.titleSuffix}</span>)}
        </span>
    </div>;
}

