import os;

def _bool_env(key: str, fallback: str = "false") -> bool {
    return (os.environ.get(key, fallback) or fallback) == "true";
}

def _int_env(key: str, fallback: int) -> int {
    return int(os.environ.get(key, str(fallback)) or str(fallback));
}

def _opt_env(key: str) -> str | None {
    return os.environ.get(key);
}

obj Env {
    has DATABASE_URL: str;
    has BETTER_AUTH_SECRET: str;
    has APP_NAME: str;
    has SMTP_HOST: str;
    has SMTP_PORT: int;
    has SMTP_USER: str;
    has SMTP_PASSWORD: str;
    has SMTP_FROM: str;
    has NEXT_PUBLIC_APP_URL: str;
