      >
        Clear
      </button>
      <button
        type="button"
        onClick={() => {
          setCount(initialValue)
        }}
      >
        Initial
      </button>
      <button
        type="button"
        onClick={() => {
          setCount(prevCount => prevCount + 1)
        }}
      >
        +
      </button>
    </div>
  )
}

function Count() {
