def:pub CanvasReplacer(id: str, children: object = None) -> JsxElement {
    has container: object | None = getContainer(id);

    can with [container] entry {
        if not container {
            container = getContainer(id);
        }
    }

    can with [container] entry {
        if container {
            query_fn = getattr(container, "querySelector") as Callable[[str], object | None];
            defaultCanvas = query_fn(".sbdocs-preview");
            if defaultCanvas {
                set_attr = getattr(defaultCanvas, "setAttribute") as Callable[[str, str], None];
                set_attr("style", "display: none");
            }
        }
    }

    if not container {
        return <></>;
    }

    return ReactDOM.createPortal(<div key={id}>{children}</div>, container);
}

