def:pub SkillForm(
    onAdd: Callable[[SkillFormData], None],
    skills: list[SkillFormData],
    onDelete: Callable[[int], None],
) -> JsxElement {
    has skill_name: str = "";
    has skill_level: str = "1";
    has name_error: str | None = None;

    selected_level = int(skill_level) if skill_level else 1;

