import from "../../lib/utils" { cn }

obj SelectOption {
    has label: str;
    has value: str | int;
}

def select_error_message(error: str | dict[str, str]) -> str {
    if isinstance(error, str) {
        return error;
    }
    msg = error.get("message");
    if msg {
        return msg;
    }
    return "";
}

def:pub Select(
    label: str | None = None,
    options: list[SelectOption] = [],
    error: str | dict[str, str] | None = None,
    helperText: str | None = None,
    className: str | None = None,
    ref: Ref[HTMLSelectElement] = Ref(),
    props: dict[str, object] = {},
) -> JsxElement {
    <div className="flex flex-col gap-1">
        {if label {
            <label className="text-sm font-medium text-gray-700">{label}</label>
        }}
        <select
            ref={ref}
            className={cn(
                "border rounded-md px-3 py-2 text-sm shadow-sm focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-blue-500",
                "border-red-500 focus:ring-red-500 focus:border-red-500" if error else "",
                className,
            )}
            {**props}
        >
            <option value="">Select...</option>
            {for opt in options {
                <option key={str(opt.value)} value={str(opt.value)}>{opt.label}</option>
            }}
        </select>
        {if helperText and not error {
            <p className="text-xs text-gray-500">{helperText}</p>
        }}
        {if error {
            <p className="text-xs text-red-600">{select_error_message(error)}</p>
        }}
    </div>
}

