def:pub parsePersistedEntry(`entry: str | None) -> PersistedEntry {
    if `entry is None {
        return {};
    }
    parsed: object = JSON.parse(`entry);
    if not isObject(parsed) {
        raise TypeError("use-persisted-state: the stored entry is not an object of hook keys");
    }
    return parsed as PersistedEntry;
}

