jac:
type ReactNodeLike = JsxElement | str | int | float | bool | list[object] | None;

def:pub OpsWrapper(opacity: float, children: ReactNodeLike = None) -> JsxElement {
    return <section
        className="ops-wrapper"
        style={{"opacity": opacity, "transition": "all 0.3s ease"}}
    >{children}</section>;
}

def:pub OpsElement(bg: str, children: ReactNodeLike = None) -> JsxElement {
    hovered = useState(False);
    baseStyle: dict[str, object] = {
        "cursor": "pointer",
        "fontSize": "12px",
        "verticalAlign": "middle",
        "padding": "4px",
        "marginLeft": "2px",
        "borderRadius": "33px",
        "zIndex": 2,
    };
    hoverStyle: dict[str, object] = {
        "backgroundColor": bg,
        "boxShadow": "10px",
        "opacity": 0.9,
    };
    style = {**baseStyle, **hoverStyle} if hovered[0] else baseStyle;
    return <span
        style={style}
        onMouseEnter={lambda () { hovered[1](True); }}
        onMouseLeave={lambda () { hovered[1](False); }}
    >{children}</span>;
}

