export const catchLog = <T, R>(
  fn: (err: Error, source: Observable<T>) => Observable<R>
) =>
  catchError<T, R>((err, source) => {
    if (process.env.NODE_ENV !== 'test') {
      // tslint:disable-next-line:no-console
      console.error(err);
    }
    return fn(err, source);
