import from "../typings" { ImportedUrlObj }

def:pub createImportedUrlObjs(singleLines: list[str]) -> list[list[ImportedUrlObj]] {
    res: list[list[ImportedUrlObj]] = [[]];
    isEmptyLine = lambda (s: str) -> bool { s == ""; };
    for singleLine in singleLines {
        urlObj = genImportedUrlObj(singleLine);
        if isEmptyLine(singleLine) {
            res.append([]);
        } else {
            res[len(res) - 1].append(urlObj);
        }
    }
    return res;
}

def genImportedUrlObj(singleLine: str) -> ImportedUrlObj {
    urlAndTitle: list[str] = singleLine.split("|");
    return {"url": urlAndTitle[0], "title": urlAndTitle[1]};
}

