obj ValueObject[T] {
    has val: T;

    def get() -> T {
        return self.val;
    }

    def equals(vo: ValueObject[T]) -> bool {
        if type(self).__name__ != type(vo).__name__ {
            return False;
        }
        return self.get() == vo.get();
    }
}

