def:pub useDebouncedValue[T](value: T, delayMs: int = 300) -> T {
    state = useState(value);
    debounced = state[0];
    setDebounced = state[1];
    useEffect(lambda {
        timer = setTimeout(lambda { setDebounced(value); }, delayMs);
        return lambda { clearTimeout(timer); };
    }, [value, delayMs]);
    debounced
}

