import from "@mui/material" { Stack, Typography }
import from "@mui/x-charts/Gauge" { Gauge, gaugeClasses }
import from "react-i18next" { useTranslation }

glob fearGreedColors: list[dict[str, int | str]] = [
    {"min": 1, "max": 19, "color": "rgb(234, 57, 67)"},
    {"min": 20, "max": 39, "color": "rgb(234, 140, 0)"},
    {"min": 40, "max": 59, "color": "rgb(243, 212, 47)"},
    {"min": 60, "max": 79, "color": "rgb(147, 217, 0)"},
    {"min": 80, "max": 100, "color": "rgb(22, 199, 132)"}
];

def get_color_for_index(index: int) -> str | None {
    for range_entry in fearGreedColors {
        min_val = range_entry["min"] as int;
        max_val = range_entry["max"] as int;
        if index >= min_val and index <= max_val {
            return range_entry["color"] as str;
        }
    }
    return None;
}

def:pub FearGreedIndex(data: dict[str, object]) -> JsxElement {
    has fearGreedIndex: int = 0;
    has fearGreedClass: str = "extremefear";
    i18n_bundle = useTranslation();
    t = i18n_bundle["t"];

    def sync_from_data() {
        classification = data["value_classification"] as str;
        fg_class = "".join(classification.split(" "));
        fg_class = fg_class[0].lower() + fg_class[1:];
        fearGreedClass = fg_class;
        fearGreedIndex = data["value"] as int;
    }

    can with entry {
        sync_from_data();
    }

    arc_color = get_color_for_index(fearGreedIndex);
    gauge_sx = {f"& .{gaugeClasses.valueArc}": {"fill": arc_color}};

    <>
        <Stack direction="column" spacing={0} sx={{"justifyContent": "center", "alignItems": "center"}}>
            <Gauge width={100} height={87} value={fearGreedIndex} startAngle={-100} endAngle={100} sx={gauge_sx} />
            <Typography variant="caption" component="p">{t(fearGreedClass)}</Typography>
        </Stack>
