def:pub dropDefault[T](value: T, fallback: T) -> T | None {
    return None if value == fallback else value;
}

obj:pub FilterCodec[TSearch, TFilters] {
    has decode: Callable[[TSearch], TFilters];
    has encode: Callable[[TFilters], dict[str, object]];
    has resetOnChange: dict[str, object] | None = None;
}

def:pub applyFilterUpdate[TSearch, TFilters](
    prev: TSearch,
    updater: Callable[[TFilters], TFilters],
    codec: FilterCodec[TSearch, TFilters],
) -> TSearch {
    next = updater(codec.decode(prev));
    reset_on_change = codec.resetOnChange if codec.resetOnChange is not None else {};
    return {**prev, **codec.encode(next), **reset_on_change};
}

