/**
 * The single live-traffic subscription on the map page.
 *
 * Everything downstream reads the store rather than the socket, and each
 * consumer gets its own clock: the map's rAF loop is called imperatively per
 * batch, while the reading surfaces snapshot at 1Hz. A naive setState here
 * would re-render the map subtree seven times a second.
 */
import { createContext, useContext, useEffect, useMemo, useRef, useState } from "react"
import { useLiveEvents, useLiveFeedStatus } from "@/lib/live-feed-context"
import { useBannedIps } from "@/lib/queries"
import { getDemoTrafficMode, makeDemoRequests } from "@/lib/demo-traffic"
import { pairLiveEvents } from "./pairing"
import { LiveTrafficStore } from "./store"
import { EMPTY_SUMMARY, summarize, type LiveSummary } from "./summary"
import type { LiveRequest, Vitals } from "./types"

/**
 * What is actually feeding the store, as far as the UI should care.
 * Demo mode never opens the socket, so "connected" here means "something is
 * feeding this" rather than "the socket is open" - the distinction the
 * disconnected states downstream (the rail and the pill) depend on.
 */
export type LiveFeedState = "connected" | "reconnecting"

const EMPTY_VITALS: Vitals = {
  rpm: 0,
  errorRate: 0,
  threatCount: 0,
  uniqueIps: 0,
  countries: 0,
  dropped: 0,
  droppedRecently: false,
  sparkline: [],
}

const StoreContext = createContext<LiveTrafficStore | null>(null)
const FeedStateContext = createContext<LiveFeedState>("reconnecting")

const SNAPSHOT_INTERVAL_MS = 1000

export function LiveTrafficProvider({
  enabled,
  children,
}: {
  enabled: boolean
  children: React.ReactNode
}) {
  const store = useMemo(() => new LiveTrafficStore(), [])
  const { data: bannedIps } = useBannedIps()
  // Read through a ref so a refetched ban list does not resubscribe the socket.
  const bannedRef = useRef<ReadonlySet<string>>(new Set())
  bannedRef.current = bannedIps ?? new Set()
  const demoMode = getDemoTrafficMode()
  const socketStatus = useLiveFeedStatus()
  // Demo mode is a feed in its own right: it never opens the socket, so the
  // socket's status alone would read as permanently disconnected.
  const feedState: LiveFeedState =
    demoMode !== "off" || socketStatus === "connected" ? "connected" : "reconnecting"

  useLiveEvents(
    (events, dropped) => {
      const now = Date.now()
      store.ingest(pairLiveEvents(events, bannedRef.current, now), dropped, now)
    },
    enabled && demoMode === "off",
  )

  useEffect(() => {
    if (!enabled || demoMode === "off") return
    let cursor = 0
    const emit = () => {
      const now = Date.now()
      const count = demoMode === "burst" ? 4 : 1
      store.ingest(makeDemoRequests(cursor, count, now), 0, now)
      cursor += count
    }
    const kickoff = window.setTimeout(emit, 250)
    const interval = window.setInterval(emit, demoMode === "burst" ? 2800 : 1100)
    return () => {
      window.clearTimeout(kickoff)
      window.clearInterval(interval)
    }
  }, [demoMode, enabled, store])

  useEffect(() => {
    if (!enabled) store.clear()
  }, [enabled, store])

  return (
    <StoreContext.Provider value={store}>
      <FeedStateContext.Provider value={feedState}>{children}</FeedStateContext.Provider>
    </StoreContext.Provider>
  )
}

export function useLiveTrafficStore(): LiveTrafficStore {
  const store = useContext(StoreContext)
  if (!store) throw new Error("useLiveTrafficStore must be used inside LiveTrafficProvider")
  return store
}

/** "connected" when something is feeding the store, demo mode included. */
export function useLiveFeedState(): LiveFeedState {
  return useContext(FeedStateContext)
}

/**
 * The whole window plus its aggregates, refreshed once a second. Pass
 * `active: false` for a surface that is closed - a hidden sheet should not
 * pay for a snapshot it will not render.
 */
export function useLiveWindow(active = true): {
  requests: readonly LiveRequest[]
  summary: LiveSummary
} {
  const store = useLiveTrafficStore()
  const [requests, setRequests] = useState<readonly LiveRequest[]>(() =>
    active ? store.getRequests() : [],
  )

  useEffect(() => {
    if (!active) {
      // Drop the snapshot so a reopened surface never flashes stale rows.
      setRequests([])
      return
    }
    const tick = () => setRequests(store.getRequests())
    tick()
    const interval = window.setInterval(tick, SNAPSHOT_INTERVAL_MS)
    return () => window.clearInterval(interval)
  }, [active, store])

  const summary = useMemo(
    () => (requests.length === 0 ? EMPTY_SUMMARY : summarize(requests)),
    [requests],
  )

  return { requests, summary }
}

export function useLiveVitals(): Vitals {
  const store = useLiveTrafficStore()
  const [vitals, setVitals] = useState<Vitals>(EMPTY_VITALS)

  useEffect(() => {
    const tick = () => setVitals(store.getVitals(Date.now()))
    tick()
    const interval = window.setInterval(tick, SNAPSHOT_INTERVAL_MS)
    return () => window.clearInterval(interval)
  }, [store])

  return vitals
}

import { describe, expect, it } from "vitest"
import type { LiveEvent } from "@/lib/websocket"
import { pairLiveEvents } from "./pairing"

const TS = "2026-07-22T19:57:54+02:00"

function geo(ip: string, timestamp = TS): LiveEvent {
  return {
    type: "geo_event",
    data: {
      timestamp,
      ip_address: ip,
      latitude: 59.9133,
      longitude: 10.7389,
      city: "Oslo",
      country_code: "NO",
    },
  }
}

function log(ip: string, status: number, timestamp = TS): LiveEvent {
  return {
    type: "access_log",
    data: {
      timestamp,
      ip_address: ip,
      remote_user: null,
      method: "GET",
      url: "/map",
      http_version: "HTTP/2.0",
      status_code: status,
      bytes_sent: 903,
      referrer: null,
      user_agent: "curl/8.4.0",
      request_time: 0.204,
      upstream_response_time: 0.026,
      host: "geometrikks.example.com",
      country_code: "NO",
      country_name: "Norway",
      city: "Oslo",
    },
  }
}

describe("pairLiveEvents", () => {
  it("joins a geo event with the access log that follows it", () => {
    const requests = pairLiveEvents([geo("1.1.1.1"), log("1.1.1.1", 200)], new Set(), 1000)

    expect(requests).toHaveLength(1)
    expect(requests[0].coordinates).toEqual([10.7389, 59.9133])
    expect(requests[0].log?.status_code).toBe(200)
    expect(requests[0].statusClass).toBe("2xx")
  })

  it("keeps a geo event that has no log line, with no detail", () => {
    const requests = pairLiveEvents([geo("1.1.1.1")], new Set(), 1000)

    expect(requests).toHaveLength(1)
    expect(requests[0].log).toBeNull()
    expect(requests[0].statusClass).toBe("unknown")
    expect(requests[0].coordinates).not.toBeNull()
  })

  it("keeps a log line that has no geo event, with no coordinates", () => {
    const requests = pairLiveEvents([log("1.1.1.1", 404)], new Set(), 1000)

    expect(requests).toHaveLength(1)
    expect(requests[0].coordinates).toBeNull()
    expect(requests[0].statusClass).toBe("4xx")
    expect(requests[0].city).toBe("Oslo")
  })

  it("does not pair events from different IPs that happen to be adjacent", () => {
    const requests = pairLiveEvents([geo("1.1.1.1"), log("2.2.2.2", 200)], new Set(), 1000)

    expect(requests).toHaveLength(2)
    expect(requests[0].log).toBeNull()
    expect(requests[1].coordinates).toBeNull()
  })

  it("does not pair events from the same IP at different timestamps", () => {
    const requests = pairLiveEvents(
      [geo("1.1.1.1"), log("1.1.1.1", 200, "2026-07-22T19:58:00+02:00")],
      new Set(),
      1000,
    )

    expect(requests).toHaveLength(2)
  })

  it("pairs two records from one IP in the same batch", () => {
    const requests = pairLiveEvents(
      [geo("1.1.1.1"), log("1.1.1.1", 200), geo("1.1.1.1"), log("1.1.1.1", 404)],
      new Set(),
      1000,
    )

    expect(requests).toHaveLength(2)
    expect(requests[0].log?.status_code).toBe(200)
    expect(requests[1].log?.status_code).toBe(404)
  })

  it("gives every request in a batch a distinct id", () => {
    const requests = pairLiveEvents(
      [geo("1.1.1.1"), log("1.1.1.1", 200), geo("1.1.1.1"), log("1.1.1.1", 404)],
      new Set(),
      1000,
    )

    expect(new Set(requests.map((r) => r.id)).size).toBe(2)
  })

  it("marks banned IPs and makes them threats whatever their status", () => {
    const requests = pairLiveEvents(
      [geo("9.9.9.9"), log("9.9.9.9", 200)],
      new Set(["9.9.9.9"]),
      1000,
    )

    expect(requests[0].banned).toBe(true)
    expect(requests[0].threat).toBe(true)
  })

  it("marks a 5xx as an error but not a threat", () => {
    const requests = pairLiveEvents([geo("1.1.1.1"), log("1.1.1.1", 502)], new Set(), 1000)

    expect(requests[0].statusClass).toBe("5xx")
    expect(requests[0].threat).toBe(false)
  })

  it("marks a refused request as a threat but leaves a 404 alone", () => {
    const requests = pairLiveEvents(
      [geo("1.1.1.1"), log("1.1.1.1", 403), geo("2.2.2.2"), log("2.2.2.2", 404)],
      new Set(),
      1000,
    )

    expect(requests[0].threat).toBe(true)
    // Both are 4xx on the map and in the response mix; only one is a threat.
    expect(requests[1].statusClass).toBe("4xx")
    expect(requests[1].threat).toBe(false)
  })

  it("returns nothing for an empty heartbeat frame", () => {
    expect(pairLiveEvents([], new Set(), 1000)).toEqual([])
  })
})

/**
 * In-memory store for the live traffic stream.
 *
 * Deliberately framework-free: every hot-path consumer (the map's rAF loop)
 * reads it imperatively, and React sees only throttled snapshots. Buckets and
 * vitals are derived on read, at 1 Hz over at most MAX_REQUESTS records.
 */
import { worseStatus } from "./classify"
import type { LiveRequest, SecondBucket, StatusClass, Vitals } from "./types"

export const WINDOW_SECONDS = 300
export const MAX_REQUESTS = 2000
export const SPARKLINE_SECONDS = 60
export const RECENT_DROP_MS = 60_000

type RequestsListener = (requests: LiveRequest[]) => void

export class LiveTrafficStore {
  /** Newest first. */
  private requests: LiveRequest[] = []
  private byId = new Map<string, LiveRequest>()
  private listeners = new Set<RequestsListener>()
  private droppedTotal = 0
  private lastDropAt: number | null = null
  private readonly maxRequests: number
  private readonly windowSeconds: number

  constructor(options: { maxRequests?: number; windowSeconds?: number } = {}) {
    this.maxRequests = options.maxRequests ?? MAX_REQUESTS
    this.windowSeconds = options.windowSeconds ?? WINDOW_SECONDS
  }

  ingest(requests: LiveRequest[], dropped: number, now: number): void {
    this.droppedTotal += dropped
    if (dropped > 0) this.lastDropAt = now
    if (requests.length > 0) {
      // Newest first, so a batch is reversed before it is prepended.
      this.requests = [...[...requests].reverse(), ...this.requests]
      for (const request of requests) this.byId.set(request.id, request)
    }
    this.evict(now)
    if (requests.length > 0) {
      this.listeners.forEach((listener) => listener(requests))
    }
  }

  private evict(now: number): void {
    const cutoff = now - this.windowSeconds * 1000
    let end = this.requests.length
    while (end > 0 && this.requests[end - 1].receivedAt < cutoff) end -= 1
    if (end > this.maxRequests) end = this.maxRequests
    if (end === this.requests.length) return

    for (const request of this.requests.slice(end)) this.byId.delete(request.id)
    this.requests = this.requests.slice(0, end)
  }

  /**
   * Push a request at the subscribers again without storing it. The timeline
   * replays an arc this way; re-ingesting would double-count it in the vitals
   * and buckets, so the same second would grow every time you clicked it.
   */
  replay(request: LiveRequest): void {
    this.listeners.forEach((listener) => listener([request]))
  }

  getRequests(): readonly LiveRequest[] {
    return this.requests
  }

  getRequest(id: string): LiveRequest | undefined {
    return this.byId.get(id)
  }

  onRequests(callback: RequestsListener): () => void {
    this.listeners.add(callback)
    return () => {
      this.listeners.delete(callback)
    }
  }

  getBuckets(now: number): SecondBucket[] {
    this.evict(now)
    const newest = Math.floor(now / 1000)
    const oldest = newest - (this.windowSeconds - 1)
    const buckets: SecondBucket[] = []
    for (let second = oldest; second <= newest; second += 1) {
      buckets.push({ second, total: 0, threats: 0, banned: 0, worstStatus: "unknown", requestIds: [] })
    }

    for (const request of this.requests) {
      const index = Math.floor(request.receivedAt / 1000) - oldest
      if (index < 0 || index >= buckets.length) continue
      const bucket = buckets[index]
      bucket.total += 1
      if (request.threat) bucket.threats += 1
      if (request.banned) bucket.banned += 1
      bucket.worstStatus = worseStatus(bucket.worstStatus, request.statusClass)
      bucket.requestIds.push(request.id)
    }

    return buckets
  }

  getVitals(now: number): Vitals {
    this.evict(now)
    const ips = new Set<string>()
    const countries = new Set<string>()
    let threatCount = 0
    let serverErrors = 0
    let rpm = 0
    const rpmCutoff = now - 60_000

    for (const request of this.requests) {
      if (request.ip) ips.add(request.ip)
      if (request.countryCode) countries.add(request.countryCode)
      if (request.threat) threatCount += 1
      if (request.statusClass === "5xx") serverErrors += 1
      if (request.receivedAt >= rpmCutoff) rpm += 1
    }

    const buckets = this.getBuckets(now)
    return {
      rpm,
      errorRate: this.requests.length === 0 ? 0 : serverErrors / this.requests.length,
      threatCount,
      uniqueIps: ips.size,
      countries: countries.size,
      dropped: this.droppedTotal,
      droppedRecently: this.lastDropAt !== null && now - this.lastDropAt <= RECENT_DROP_MS,
      sparkline: buckets.slice(-SPARKLINE_SECONDS).map((bucket) => bucket.total),
    }
  }

  clear(): void {
    this.requests = []
    this.byId.clear()
    this.droppedTotal = 0
    this.lastDropAt = null
  }
}

export type { StatusClass }

