  return (
    <TodoContext.Provider
      value={{
        todoItems: state.todoItems,
        editingId: state.editingId,
        addTodo,
        toggleTodoComplete,
        deleteTodo,
        updateTodo,
        setEditingId,
      }}
    >
      {children}
    </TodoContext.Provider>
  );
