  color: "white",
});

const CardWrapper = styled(Card)((props: { bg: string }) => ({
  borderRadius: 20,
  backgroundColor: props.bg,
}));

const TitleText = styled(Title)({
  color: "white",
});

const ParagraphText = styled(Paragraph)({
  color: "white",
});

export interface IMatrixCardProps {
  id: 1 | 2 | 3 | 4;
